INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1030367-chem101', 'stk-s2010xxxxx', 'CHEM 101', 'info', '{"desc": "الكورس سهل ويغطي اشياء درسناها بالثنوي … وانصح الجميع بالمذاكره من الكتاب … والتركيز على التشك بوينتس لانها مفيده للغاية … ولابد من المذاكره اول باول لان الكورس طويييييل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/2", "user": "s2010xxxxx", "ts": 1335740302000, "tid": 120589, "pn": 2}}', 1335740302000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048977-chem101', 'stk-user7558', 'CHEM 101', 'info', '{"desc": "الكورس طويل جدا جدا ويتكون من 12 شابتر وكل شابتر ماهو متعلق بالثاني\nبس عموما مستوى الاسئلة في المياجر مايكون صعب ويكون مشابه لاسئلة الكتاب\n\nالبعض يقول ان المادة مادة جريد بس طبعا لازم تهتم فيها ولابتجيب العيد 🤠\n\nالمادة ميجرين كل ميجر عليه 15 % وكلاس وورك 17.5 % والحضور 2.5% واللاب 25% والفاينل 25%\n\nالكتاب جدا ممتاااااااز وأمثلته وأسئلته ممتازة جدا واللي يذاكر الكتاب اول باول فالاي بلس مضمونه وطبعا مفيد جدا في الحياة ويربط لك الكيمياء بالحياة\n\nالكورس بشكل عام ممتع للي يحب الكمستري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/3", "user": "user7558", "ts": 1338557285000, "tid": 120589, "pn": 3}}', 1338557285000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1049561-chem101', 'stk-king_of_net', 'CHEM 101', 'info', '{"desc": "بشكل عام الكورس طويل ويبغاله مذاكرة لكن سهل مو صعب\n\nوتقريبا هو نفس الي أخذناه في الثانوي لكن بشكل أوسع شوية\n\nوالكتاب المستخدم صراحة رائع جدا يعني من وجهة نظري لو تذاكر من سلايدات السعدي\n\nوكل ما خلصت سكشن روح شوف السامبل بروبلم والبراكتيس بروبلم والتشيك بوينت وحلها كلها وإنت فاهم\n\nوإذا خلصت من التشابتر بشكل عام حل أسئلة الهوم وورك وإن شاء الله بتطلع بـ a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/4", "user": "KinG_OF_NeT", "ts": 1338667167000, "tid": 120589, "pn": 4}}', 1338667167000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050311-chem101', 'stk-the_legend1', 'CHEM 101', 'info', '{"desc": "ذاكر اول باول من سلايدات السعدي وحل التشيك بوينت وخذ لك كم اولد اقزام ورتبه حسب الشابتر\nوحل منه بعد ما تخلص كل شابتر واهم شيء حاول تسوي لك سامري لان المنهج طويل ووقت الميجر راجع السمري وحل كم اولد اقزام\n\nالكورس هذا ما ينفع ابد ابد ابد انك ما تذاكره اول باول لانه طووووووووووووووووووووووويل مررررررررررررررررررررررة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/5", "user": "THE_LEGEND1", "ts": 1338769284000, "tid": 120589, "pn": 5}}', 1338769284000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1164366-chem101', 'stk-_716', 'CHEM 101', 'info', '{"desc": "مهم هالكلام انا سويت اللي قاله الرجال بخصوص الملخص وجبت درجه في ميجر 2 دبل ميجر 1\n\nكنت جايب العيد في ميجر 1 …\n\nأيضاً الملاحظة الثانية الكويزات لاتروح عليك …\n\nعليها 17.5\n\nيعني تشكل شي كبير في القريد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/9", "user": "_716", "ts": 1358206676000, "tid": 120589, "pn": 9}}', 1358206676000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234332-chem101', 'stk-user9056', 'CHEM 101', 'info', '{"desc": "الكورس طويل جدا لدرجة متعبه\nجدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا طويـــل\n\nيعني يغطي كل اللي اخذناه في الثانوي وزياده بعض الأشياء.\nالكتاب ممتاز جدا جدا جدا ، وشرحه بسيط ، كان اعتمادي على الكتاب ،أخذت قريد ممتاز ولله الحمد ( دكتوري كان مازن خالد (شرحه سيء ))\n\nسوّف في أي شيء ولا تسوّف في هذا المنهج .\nلأنه طويل ومترابط بعض الأحيان\n\nوطويــــــل 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/11", "user": "user9056", "ts": 1371024940000, "tid": 120589, "pn": 11}}', 1371024940000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1312284-chem101', 'stk-abo-da7m', 'CHEM 101', 'info', '{"desc": "الفصل 131\n\nجودة المقرر بشكل عامممتاز جدا ومفيد\n\nالمواضيع التي يغطيها المقرر\nمبادئ أساسية وعامة مع تعمق بعض الأحيان\n\nالكتاب المستخدم للمقرر\n\nChemistry by J. Burdge, 2nd Edition* كتاب رائع بكل ما تعنيه الكلمة - واضح جدا بالشرح والرسومات\n\n* فيه تمرينين ومثال على كل مهارة تتعلمه بوسط الأبواب وتمارين بنهاية كل باب\n\n* يربطلك الكيمياء بالعلوم الثانية باسلوب جميل + تذاكره لحاله من دون اي شي تضمن A+\n\nالأختباراتأكثر الأسئلة مباشرة مع كم سؤال فيه لفات. وبرأيي ان سبب انخفاظ الآفرج ان الطلاب ما يذاكرون لأن المقرر طويل ويبغاله دراسة أول بأول يصعب تغطيه قبل المياجر\n\nمدى فائدته في الناحية التطبيقيةمفيد جدا لأنه يشرح مبادئ أساسية داخلة بكل شيء\n\nإضافات * يعيب المقرر توزيع الدرجات ( جميع الاختبارات تشكل 55 % فقط والباقي يعتمد على الآفرج بشكل كبير )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/14", "user": "abo-da7m", "ts": 1388484641000, "tid": 120589, "pn": 14}}', 1388484641000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1312428-chem101', 'stk-ieren', 'CHEM 101', 'info', '{"desc": "مثل ما قالو الشباب … بتأجل مذاكرة شابتر واحد بتجيب العيد … الكتاب ممتااااااااااااااااااااااااز جدا ويفهمك احسن من بعض الدكاترة بس يبيله متابعة لانه طوييييييييييييييييييييييييييييييل جدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/15", "user": "iEreN", "ts": 1388501637000, "tid": 120589, "pn": 15}}', 1388501637000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1355723-chem101', 'stk-user8914', 'CHEM 101', 'info', '{"desc": "^^^^^^^^^^^\nالماتيريال طويييييييييييييييييييييييييييل وغثيث\nواللاب من 8 الى 12 لكنه ممتع\nوالافرج على كلام الشباب مرتفع\nلكن فكر فيها ياصاحبي\nتقدر تنزل 8ساعات في الصيفي ووقت الدوام يكون اقل من الكمستري\n\nبينما الكمستري وقت دوام طويل وماتيريال اطول وتطلع من الصيفي ب4 ساعات\n-------------\nلكن مشكلته في الترم العادي واذا انت سفمور بيغثك وبتذاكر مواد التخصص وبتسحب عليه\n\nفا انت بين نارين\nفاختر ايهما اخف 🤠 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/17", "user": "user8914", "ts": 1398168459000, "tid": 120589, "pn": 17}}', 1398168459000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1363852-chem101', 'stk-user9306', 'CHEM 101', 'info', '{"desc": "ترم 132\nكورس سهل لكن الاسئلة فغي الميجر فيها لف شوي لكن اذا تبي تفهم التريكات حل الاسئلة اللي في اخر الكتاب والتشيك بوينت واقراء الكتاب وركز شوي في الكلاس وشوف الاستاذ كيف يحل واذا مافهمت روح للسلايدات ولاتعتمد كير على السلايدات ارجع للكتاب افضل خصوصا ان في بعض المسائل موجودة في الكاتب وتكون غير موجودة في السلايدات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/18", "user": "user9306", "ts": 1399840037000, "tid": 120589, "pn": 18}}', 1399840037000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1367607-chem101', 'stk-user8890', 'CHEM 101', 'info', '{"desc": "التشيك بوينتز جدا جدا جدا مفيدة وكذلك الاولد اقزام للمسائل, اما النظري اقرا الكتاب بتركيز\n\nميجر تو سهل جدا لا تفوته .\n\nفاينل غدار .\n\nاسئلتهم عموما فيها ترك , اقر السؤال زين .\n\nالمادة طويلة والكويزات عليها ١٧.٥ من ١٠٠ يعني لا تفوتها أبداااا, ٦ أو ١٠ بكويز واحد تفرق إلى قريد 😦\n\nعموما مادة سهلة حرام تاخذ فيها أقل من b", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/19", "user": "user8890", "ts": 1400602506000, "tid": 120589, "pn": 19}}', 1400602506000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1368265-chem101', 'stk-abofaisal', 'CHEM 101', 'info', '{"desc": "^^\n+1\nبالإضافة إلى أولد إكزام بالشبتر حق أنور الجميل ( أو الجمل ) جدا مفيد من ناحية أسئلة المسائل\nأما الكونسبت لو دكتورك جيد ما راح تحتاج الكتاب بكثرة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/20", "user": "AboFaisal", "ts": 1400679239000, "tid": 120589, "pn": 20}}', 1400679239000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373671-chem101', 'stk-user9534', 'CHEM 101', 'info', '{"desc": "وش هالكورس الطوووووووووووويل 🤪\nعموما الكورس أغلبه مسائل وقليل الجزء النظري فيه … في المياجر التريكات راح تكون في تحويل الوحدات غالبا 😆 …\nأنصحك بالاولد اكزام المرتب … تلقاه بالجمعية 🌹\nميجر 2 أسهل من 1 🥰 … الفاينل حررررررررررريقة ! 😞\nموفق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/22", "user": "user9534", "ts": 1401337285000, "tid": 120589, "pn": 22}}', 1401337285000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1375355-chem101', 'stk-playa', 'CHEM 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nكمستري 101 صراحة الغالبية يقول طويل انا ماحسيت انه طويل لانه في ترابط افكار بين الشباتر, طبعا في البداية حتاخد حاجات بسيطة الي هي المولز والكتلة والتحويلات من متر ل مايل … بعدين حتروح ع الذائبية والتركيز بعدها حتخش على الجزيئات وتفاصيل الاشكال والزوايا الجزيئية واخبرا على الغازات. انا افضل مذاكرة هذا الكورس من الكتاب صح فيه كلام كثير بس ممتاز وترتيبه حلو ومليان صور وحتغطي جميع الافكار والمعلومات بقراءته , الكوزات عليها 17.5 درجة فتحتاج انك تنتبه لها , حاول قدر الامكان تجيب اعلى درجات ممكنة في المياجر والفاينل لأن الدرجات الباقية حتطير منها كثير نورمالايزيشين , الكورس بصفه عامة سهل وحيعطيك خلفية حلوة في الكمستري.\n\nملاحطة : من وجهة نظري اكثر شي مهم وحيخليك متمكن انك تعرف تطلع عدد المولات بمختلف المعطيات وطرق الاسئلة , موفقين 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/23", "user": "PLAYA", "ts": 1401631012000, "tid": 120589, "pn": 23}}', 1401631012000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420431-chem101', 'stk-user8581', 'CHEM 101', 'info', '{"desc": "المادة سهلة خصوصا في الشباتر الأولى لكن الماتيريال طويل و يصير غثيث بعد الميجر الثاني\nبإختصار تبي تاخذ قريد عالي : تابع اول بأول وحاول تنزل مع دكتور في اللاب ممتاز ومتساهل ولاتهمل الكلاس ورك لأن عليها اعلى من الميجر الواحد + حل الامثلة والـ check points في الكتاب.\nالشباتر نوعا ما مترابطة فلا تسحب وتترك المذاكرة …\nيمكن اكون غلطان لكن اشوف الدكتور ما يأثر كثير الا من ناحية الكلاس ورك اما الشرح فالكتاب يغنيك عنه .\nلاتنزلها في الصيف الا اذا كنت مظطر لأنه متعب اللاب\n\nالكورس افرج وللأسف غالبا مايعلنون عن توزيع القريدات لكن هذا توزيع القريدات لـ 131\nhttp://skfupm.kfupm.edu.sa/vb/showpost.php?p=1354174&postcount=10\n\nاولداقزامات\nhttp://www.kfupm.edu.sa/departments/chem/SitePages/en/ContentDetailsPage.aspx?CUSTOMID=34", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/24", "user": "user8581", "ts": 1421621349000, "tid": 120589, "pn": 24}}', 1421621349000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438257-chem101', 'stk-hassan001', 'CHEM 101', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالكورس راح يعطيك فكرة عامة عن الكيمياء وأساسياتها\n\nالمواضيع التي يغطيها المقرر\n\n151\nميجر 1 ( من شابتر 1 إلى 4 ) الأفرج 56%\n\n1- نظرة عامة على الكيمياء وبعض المصطلحات الأساسية\n2- الذرة ، الأيونات والمركبات (شابتر تسمية المركبات)\n3- stoichiometry (فرع الرياضيات في الكيمياء) 🙂 وأعتبره أهم شابتر أساسي لأن بقية الدروس تعتمد عليه\n4- التفاعلات في المحاليل\n\nميجر 2 ( من شابتر 5 إلى 8 ) الأفرج 57-56 %\n5- الكيمياء الحرارية\n6- نظرية الكم ومخطط الذرة\n7- الجدول الدوري والتوزيع الإلكتروني\n8- الروابط الكيميائية\n\nمتيريال الفاينل\n9- أشكال المركبات (تكملة لشابتر 8)\n10- الغازات\n11- الخصائص الفيزيائية للسوائل والمواد الصلبة\n(شابتر 12 في chem 102)\n13- الخصائص الفيزيائية للمحاليل\n\nالكتاب المستخدم للمقرر\n\nكتاب جدًا رائع وتستمتع بقراءاته. المادة تحتاج قراءة الكتاب حتى تفهمها ( لا تقتصر على السلايدات ) وتحتاج في نفس الوقت حل مسائل كالمسائل الموجودة بعد كل قانون و check points و بعض المسائل نهاية كل سكشن على الأقل .\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nيوجد في الكتاب عدد كبير جدًا من المسائل لكن لا أنصح بحلها كلها إلا إذا استطعت تنظيم وقتك فهناك مواد أخرى كالماث والفيزياء …\n\nإضافات\n\n1- بالنسبة لي الحصول على درجة عالية في الميجر الأول أسهل من الميجر الثاني. متيريال الميجر الأول سهل جدًا وهو الأساس لبقية الدروس.\n2- الميجر الثاني يحتاج مذاكرة وحل مسائل بالذات شابتر 5 واحرص أنك تحل مسائل أولد أقزام من بداية دراستك للشابتر.\n3- الكوزات عليها نسبة 17.5% احرص أنك تجيب في كل كويز فل مارك خصوصًا إذا كان دكتورك يعطي كوز على كل شابتر فتقدر تركز على شابتر واحد وتجيب درجة عالية في الكوز.\n4- اللاب سهالات إن شاء الله وبالنسبة إلى الوقت يعتمد على التجربة ما راح تقعد أربع ساعات كاملة إلا تجربتين أو ثلاث.\n5- كوزات اللاب وفاينل اللاب حاول تجيب درجة فيهم ( مع الأسف كنت متهاون فيهم وأعتمد على درجة شغل اللاب ).\n6- في الفاينل ركز على شابتر 9- 10 -11 -13 وراجع متيريل الميجر الأول والثاني ع السريع.\n7- مسائل قانون هس و lattice energy راح تجيك في الميجر الثاني وفي الفاينل فحاول تتقنهم.\n8- الكورس طويل وما أنصح أنك تأخذه في الصيف إلا إذا استطعت تنظيم وقتك وتابعت أول بأول من قراءة وحل مسائل من دون تأخير أو تأجيل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/27", "user": "hassan001", "ts": 1452215644000, "tid": 120589, "pn": 27}}', 1452215644000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449560-chem101', 'stk-osamah56', 'CHEM 101', 'info', '{"desc": "Term 152\n\nللأمانة الكورس سهل, تقريباً كل الي اخذنا في الثانوي مع زيادة متعمقين في كم شغلة ( عن نفسي ما قد درستها )\nالقريد العالي في ذي المادة جداً سهل مو مثل الفيزيكس والماث ( أقول ذا الكلام وأنا اكره الكيمياء), والكتاب اكثر من كافي عشان تجيب A , كل شيء واضح بالكتاب مع امثلته لدرجة انه احسن من بعض الدكاترة 😉\nماكنت عند دكتور جيد ف ما اعرف مين احسن واحد\nاللاب جداً مهم عليه 25% (100 pts) ويمديك تجيب فوق 75 حتى بعد الـNormalization, لأن اغلب التجارب سهلة وللأسف اغلب الطلاب ما يشدون حيلهم, باللاب انصح ب( Hakimu Nasubga)\n\nوشكرا 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/28", "user": "osamah56", "ts": 1463600540000, "tid": 120589, "pn": 28}}', 1463600540000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466714-chem101', 'stk-mkd', 'CHEM 101', 'info', '{"desc": "بداية تخصصي لا هو كيميكال ولا بيور كمستري لكني استمتعت بالمادة !\nكورس بشكل عام سهل إلى متوسط ، مب زي الفيزيكس أبد أبد أبد\nاللي تحتاج تسويه طال عمرك :\n1- تذاكر الكتاب أو مصدر المذاكرة اللي ترتاح فيه ( شخصيا أذاكر من الكتاب وأحدد النقاط المهمة وأحدد برضو الأشياء اللي مالها داعي عشان ما أضيع وقت مذاكرة المياجر والفاينل ) + مع التركيز على السامل بروبلم تكون فاهمها صح + التشك بوينتس كلها أجمعين كاملة مكمّلة . ما تحل لا سامبل ولا تشك بيونتس أنت ما قاعد تذاكر أنت قاعد تضيع وقتك ( Unless you are a genius تلقط المعلومات عالطاير ) .\n2- تحل أسئلة الـ HW المكتوبة بالسيلبس ، حل الأسئلة موجود بموضوع Mr.A بقسم الكمستري .\n3- تفتح أولد اقزام شابتر باي شابتر بالجمعية حقت أنور الجمّال المحلولة ( بعض الحلول نادرا تلقى فيها غلط ، تأكد من حلك ) وتحله للشابتر اللي تبيه .\n4- تحل اولد كويزز تحصلهم بتقييمي بموضوع تقييم إيساب ( الدكتور ) .\n5- قبل المياجر والفاينل حل لك كم اولد اقزام اللي تقدر عليه ، إثنين على الأقل )\n6- وضعك بالسليم إن شاء الله … بأسوأ الأحوال لو طحت بسكشن سيئ كله دوافير أفرجهم صاك السبعين مع راح تنزل عن الـ B+ بإذن الله )\n\nبالتوفيق … وتراها من الآخر مادة قريد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/29", "user": "MKD", "ts": 1485014453000, "tid": 120589, "pn": 29}}', 1485014453000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492643-chem101', 'stk-user11009', 'CHEM 101', 'info', '{"desc": "بسم الله الرحمن الرحيم\nCHEM101-172\n\nجودة المقرر بشكل عام\nنوعاً ما مكرر من الثانوي مع تعمق شوي وتفاصيل بسيطة ( تركات بالاختبارات) , المنهج طويل ويحتاج مذاكرة أول بأول ومن الكتاب, الدراسة من الكتاب أفضل من السلايدات بكثير\n\nالكتاب المستخدم للمقرر\n\nالكتاب ممتاز جداً جداً لأنه يعطيك الكونسبت والقانون وبعدها عليها Sample problem سؤال عليه واخر الدرس تشيك بوينتز, ممتازة جداً جداً . أنصح بحلها وبقوة. والمياجر أولد اقزامز وممكن بعض اسئلة نهاية التشابتر الصعبة.\n\nمدى فائدته في الناحية التطبيقية\n\nالكورس يشرح اشياء كثير حولنا بشكل بسيط, فيكون عندك خلفية جيدة جداً عنها.\n\nوبالأخير, اللي يبي قريد ممتاز, عن نفسي أنصحه يذاكر أول بأول ويحاول يستعمل الكتاب قدر الإمكان وممكن يتبع طريقة التلخيص, صح ممكن تأخذ وقت لكن مردودها جيد خصوصاً لما تتورط بفاينل على 600 صفحة تقريباً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/33", "user": "user11009", "ts": 1526596705000, "tid": 120589, "pn": 33}}', 1526596705000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1498447-chem101', 'stk-to_be_engineer', 'CHEM 101', 'info', '{"desc": "Chem 101 - 171\nالسلام عليكم بعطيكم تجريتي في كيمستري 101 وان شاء الله الكل يستفيد.\n\nطبعا الماده شوي طويله وتقريبا كل اسبوع الدكتور يخلص تشابتر وبعض التشابترات تكون غثيثه وما يخلص الاسبوع الا وانت مخلص التشابتر تبعه … ذاكر اول بأول واذا قعدت تسوف بيجي الميجر وانت باقي ما خلصت الماتيريال.\n\nكيف تذاكر لكل تشابتر ؟ قبل ما ابدا لازم تعرف ان نظام الاختبارات والكويزات بيكون 25% مفاهيم و 75% مسائل ف خلي مذاكرتك بنفس الطريقه بحيث تركز على المسائل اكثر من المفاهيم …بداية المذاكرة تكون من السلايدات او الكتاب ( اُفضِّل السلايدات لانها موجزه وشامله ) اذا فهمت المفاهيم روح للامثله (sample problem) وحاول تفهم كيف انحلت المسألة (لا تحفظ ) اذا فهمت حل A و B تحت المثال، A نفس فكرة المثال و B فيه فكره غير وغالبا يجي في المياجر زيه ، اذا خلصتها حل ال check points (الاسئلة نهاية الدرس ) ، اذا خلصت منها روح للسيليبس تبع الكورس بتلقى اسئله مقترحه لكل تشابتر شوف الاسئله اللي بنفس السكشن وحلها وتراها مهمة جدا (حلول اسئلة الامثله واسئلة نهاية الدرس موجودة نهاية التشابتر ، حلول اسئلة نهاية التشابتر المقترحه تحصلها في موقع الكورس ) وعلى هذا النظام تمشي على كل سكشن لين ما تخلص التشابتر ، اذا خلصت التشابتر روح حل اولد أقزام من نوتة انور الجمل ( تقريبا 20 سؤال من كل تشابتر ) . وبكذا تكون شطبت على التشابتر ،قبل الميجر بكم يوم حل اللي تقدر عليه من الاولد الاقزام المخلوطه 172،171 ،173…\n\nحاول تختبر نفسك بنفس ظروف الاختبارك عشان ما تنصدم من ضيق الوقت امش على هذا النظام لين ما تخلص الكتاب واضمن الA+ في جيبك انا مشيت على هالطريقه ولله الحمد طلعت ب A لو مشيت عليه من البدايه كان جبت A+ لكن الحمدالله على كل حال ، المادة من اسهل مواد الفرشمن لكن اذا سحبت عليها بتكون من اصعب المواد حاول ما تضيع القريد فيها.\n\nبالتوفيق للجميع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/34", "user": "To_Be_Engineer", "ts": 1535655382000, "tid": 120589, "pn": 34}}', 1535655382000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1513510-chem101', 'stk-user11724', 'CHEM 101', 'info', '{"desc": "TERM182\nكورس عموما سهل، ولكن تكمن صعوبته في تنظيم الوقت، الكورس طويييييييييييييييييل جدا جدا ولو ما تذاكر أول بأول راح تجيب العيد.\nالكتاب هو الـ A+ -*مهم* وحل الأسئلة الي فيه- ومر مرور سريع على مراجعة الفصل، أنصح بتلخيص الفصول وهي 12 فصل، كل أسبوع راح تخلصون واحد ورتب نفسك على هذا الأساس، وعشان تتأكد من فهمك حل أولد اقزامز شابتر باي شابتر تلقاها في مكتبة المول، لأن الكويزات عليها كثير (15% في ترم182).\nحاول تكون مخلص ومراجع قبل الميجر بيومين أقل شيء عشان تحل كم أولد أقزامز وماتنصدم من الميجر.\nالأغلب بعد ما يخلص الكورس يتفق أن الكورس سهل، بس السؤال: هل طلعت بالقريد الي تبغاه ولا قريد سيء؟\nفالكم A+ 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/35", "user": "user11724", "ts": 1565223397000, "tid": 120589, "pn": 35}}', 1565223397000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518647-chem101', 'stk-mr.power', 'CHEM 101', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nأنا تخصصي تقريباً ماله اي علاقة بالكيمياء وأنا شخصياً لا أحب الكيمياء ولكن المادة ليست صعبة ، بل بالعكس مادة سهلة وغير ثقيلة ! المادة يعيبها كثرة الحفظ فقط وهذا اساساً هو الكيمياء ، المادة العلمية الوحيدة تقريباً اللي معظمها حفظ .\n\nالمادة ليس مستحيل الحصول على قريد A وما فوق فيها لو فهمت وحفظت زين ، الميجر الاول عادتاً بسيط ولكن الصعوبة تكمّن في الشابتر الرابع ، إذا ضمنت الميجر الأول فخلاص الميجر الثاني بسيط جداً أغلبه تعويض مباشر بالقوانين وكونسبت بسيط …\n\nوماتيريال الفاينل كذلك معظمه بسيط …\n\nالمادة مو ثقيلة لو ذاكرت كل اسبوع شابتر ، والشابتر كذلك لا أنصح أي شخص يذاكره من الكتاب ، ذاكر من سلايدات الكتاب والشيء اللي يستصعب عليك تبحث عنه ، الكتاب لا أحبذه ، محشي كلام كثير ولاتدري وين المهم اللي فيه ، فلذلك أنصح بالسلايدات لفهم الكونسبت وكذلك حل الشيك بوينتس وقبل الميجر حل ٣-٢ أولد اقزامس وإن شاء الله الامور طيبة …\n\nبالنسبة للاب ، اللاب مايبيله شيء ، في اليوم الذي يسبق يوم اللاب ، ذاكر وحل وتأكد من حلولك حق اسئلة البري لاب وأمورك طيبة إن شاء الله …\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/36", "user": "Mr.power", "ts": 1577952071000, "tid": 120589, "pn": 36}}', 1577952071000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522025-chem101', 'stk-yousef_alamoudi_4507', 'CHEM 101', 'info', '{"desc": "CHEM101 - term 192\n\nالمادة طوييييلة جدا و لكن ممتعة للي يحب الكيمياء، تقريبا مراجعة عامة للي اخذته في الثانوي ( كيمياء 1 و 2 و 3 و 4)، المادة بقسمها بحسب ماتريال المياجر بعد شوي، الكتاب المستخدم\n( Chemistry by Julia Burdge 4th edition) جدا ممتاز و رائع خصوصا في السامبل بروبلمز و التشكبوينتس اللي انصح بكل قوة انك تحلها ما تاخذ اقل دقايق و تفهمك المطلوب في الدرس سواء كونسبت او مسائل.\n\nتقسيم الوحدات كالاتي :\n\n1- ماتريال الميجر الاول :\n\n-شابتر 1 : Introduction into chemistry\n- شابتر 2 : Atoms, molecules and ions\n-شابتر 3 : Stoichiometry ( كيفية قراءة التفاعلات و النسب في التفاعلات و الخزعبلات ذي)\n- شابتر 4 : Reactions in aqueous solutions (التخفيف و الاكسدة و الاختزال و شوية بهارات 🤠 )\n\n2- ماتريال الميجر الثاني :\n-شابتر 10 : Gases (خصائصها العامة )\n-شابتر 5 : Thermodynamics ( كيفية انتقال الحرارة في التفاعلات)\n-شابتر 6 : Quantum Mechanics (نظريات الذرة و خصائص الموجات و ذي الحاجات الفيزيائية)\n-شابتر 7 : Electron configuration and periodic table\n\n3-ماتريال الفاينل :\n-شابتر 8 : Chemical Bonding I (بعض نظريات الروابط منها نظرية لويس)\n-شابتر 9 : Chemical Bonding II (تكملة للشابتر اللي قبل بس اعمق و مليان كلام و كونسبت)\n- شابتر 11 : Intermolecular Forces and physical properties of liquids and solids ( الروابط بين الجزيئات و شوي خصائص للحالتين المذكورة)\nشابتر 13 : Physical properties of solutions ( خصائص المحاليل )\n\n# الميجر الاول يعتبر اسهل من الثاني ولكنه مليان حفظ بسبب شابتر 1 و 2 و 4، بس اذا انك راعي حفظ لا تفوت الفرصة.\n# الميجر الثاني يعتبر اصعب عل كلام دكتوري،بس ما قدرنا نختبره بسبب ازمة كورونا ، و نفس الحكاية للفاينل بس بحسب كلام الشباب فوق يقولوا نار فاستغل الفرصة في الميجرين.\n#انصح تحل اولد اكزام اللي في الريسورسز و السامبل بروبلمز و التشكبوينتس ضروري.\n#بالنسبة للكتاب اتوقع شرحه كويس بس ما جربت ادرس منه بالكامل الا خفافي مرة للامانة، اعتمدت عل قناتين في اليوتيوب انصح و بقوة فيهما خرافيين لابعد درجة 👍اللي هما (ارجعلهما لتثبيت المعلومة او اذا انك ما فهمت):\nThe organic chemistry tutor\nProfessor Dave Explains\nالاول يحل مسائل و الثاني راعي كونسبت :popcorn:.\n\n#بالنسبة للكوزات دكتوري اللي درسني لكتشر (وسام يالي، معليش اذا كان لقبه غلط عجزت اعرف 😂) كان هو اللي يدرس ريساتيشن و يحط الكويزات، جدا حلوة و بسيطة و احلى من ذا كله يجيب اسئلة اولد اقزام فيها، بس ممكن تلاقي سؤال واحد يلخم مخك فيه و يبلعك احلى تريك 🥊، فحاول تجيب فيها درجات طيبة و كويسة عشان النورماليزايشن (للي ما يعرف هذا اسلوب غريب من الديبارتمنت ينقصك اخر الترم لافرج معين السكشن كامل).\n#بالنسبة للاب حاول تنزل مع وسيم منصور لانه يزبطك اذا انك كنت مهتم، مرررة يفهم (للعلم ،سبورته اللي يكتب فيها تعتبر كنز اذا تبغا تجيب درجة رهيبة في فاينل اللاب) و كوزات اللاب حقته حرفيا هي صفحتين الاسايمنت اللي في نهاية التجربة اللي عليك في المانول، و ازيدك من الشعر بيت كل اللي يطلبه في الكويز جدول واحد او اثنين بالكثير اللي في الاسايمنت و السلام 👏، يعني حرفيا مخمخ و حل الجدول و امورك ان شاء الله في السليم 👍، بس بالنسبة للي يقولوا انه ما يمديك تعدي حاجز ال80 بعد النورماليزايشن في اللاب (ايه نعم برضوا هنا :zipper_mouth_face:) ، احب اقله الكلام هذا خاطئ و الدليل انا جايب 84 :muscle: بس ترا تحتاج شوي جهد. بالنسبة لفاينل اللاب ما عندي علم بيه لانه تكسنل بسبب كورونا 🤔.\n#الواجبات ما يحتاج اتكلم عنها، هذي عندك يبو 🤠.\n\nزبدة الزبدة، المادة طويلة حبتين و دسمة، كل اللي عليك تسويه ذاكر كل يوم بيومه (نصيحة لا تركم الدروس ابد، ولا حتندم بكرة يا جميييل 😂) و اعطي المادة حقها و بتقع سهالات عل قولتنا الحضارم :).\n\nقريد الB+ ما اظن صعب في المادة ذي، بس مع الكورونا جبنا C+ 😭 معوضين خير ان شاء الله.\n\nالمادة حلوة لكن يعيبها بالنسبة لي الحفظ الزايد شوي و فالكم الA+ في كل مكان و زمان.\n\nو معليش عالاطالة 😅، و اي اسئلة تحت امركوا 😄.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/37", "user": "yousef_Alamoudi_4507", "ts": 1589433193000, "tid": 120589, "pn": 37}}', 1589433193000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522277-chem101', 'stk-guest', 'CHEM 101', 'info', '{"desc": "192\nالمادة كمتريال سهل لكن المشكلة في رأيي المياجرصعبة جداً\nانا في المذاكرة اكون فاهم جداً واحل اسألة الكتاب بدون اي صعوبة\nلكن اسألة المياجر بالنسبة لي منهج آخر يحتاج مذاكرة لحاله لانه صعب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/38", "user": "Guest", "ts": 1590216169000, "tid": 120589, "pn": 38}}', 1590216169000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531227-chem101', 'stk-tweiti', 'CHEM 101', 'info', '{"desc": "203-صيفي\n\nالسلام عليكم و رحمة الله و بركاته.\nchem101\nعبارة عن 12 شابتر\n\nCH1\nأهم فكرة في هذا الشابتر هي كيف تتعامل مع الفواصل (significant figures)\nو بعدها تحويل الوحدات\nقواعدها بسيطة في العمليات لازم تعرفها و تدريب بسيط من نوتات حمزة بعنوان significant figures\nو عند اولدات عبيد فيها اسئلة كثيير\nاسئلة الكتاب جيدة في هذا الباب كمان.\nCH2\nأهم فكرة هنا التسمية و كيف تكتب رموز المركب من الاسم لازم تحفظ لازم لازم تحفظ و تحل اولدات عبيد و اسئلة الكتاب و خلك ملم بالتسمية\n--------------------------------------------\nCH1&2\nذي الشابترين أهم شي في الكورس لازم تتقنها لأن بعدين بتجيك اسئلة و يذكر لك اسامي مركبات فقط ولازم تعرف كيف تكتبها الشابتر الاول رح تحتاجه في الاب و الاختبارات كذلك\n-------------------------------------------\nCH3\nالشابتر عن المولات و هنا المادة تبدأ بمستواها الطبيعي الي قبل سهل\nأهم شي تتقنه Ratio و أمورك رح تكون تمام بإذن الله و الله يعينك لازم تتدرب كثير و ذا الشابتر ما استوعبته من اول مره\nCH4\nبنسبة لي أصعب شابتر يحتاج جهد و تدريب عن المحاليل و لابد من التركيز على المعادلات و وحداتها.\nCH10\nالغازيات و قوانينها\nCH5\nحسب ما سمعت من الي درسوا معي أن ذا الشابتر موجود نفسه أو شبيه له في فزكس 102 عموما يتكلم عن انتقال الحرارة و يحتاج تدريب و ركز على الوحدات و لازم تفرق اذا تفاعل طارد او ماص.\n------------------------------------------\nترى شابتر 3-4-5 هي أصعب شيء في المادة و الغالب يدردب عندها انتبه و اصبر\n-----------------------------------------\nCH6&7&8&9\nشباتر سهلة جدا و قوانين كلها من الثانوي و الجدول الدوري و التوزيع و كيف ترسم تركيب لويس بس تفهم الكونسبت و تدرب شوي و خلاص\nCH11&13\nاخر شابترين في المادة عبارة عن خصائص المحاليل و خصائص المركبات و القوى بين الذرات قوانين بسيطة و سهلة تحتاج منك فقط الممارسة البسيطة.\n---------------------------------------\nChem 101.zip\n\nكل شي تحتاجه في الرابط\nاولدات عبيد تحصلها في ملف BASM\nعموما\nافهم ثم حل التشيك بوينت ثم عبيد آخر شي حمزة\nإذا عندك وقت حل السامبل\n---------------------------------------\nالمادة في الصيف متعبة بس مقدور عليها نزلتها مع اسلامي و تخلصها سريع سريع لكن الافرج معروف انه في الصيف مرتفع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-general-chemistry-i/120589/40", "user": "Tweiti", "ts": 1628878772000, "tid": 120589, "pn": 40}}', 1628878772000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1086999-chem101', 'stk-the_silver', 'CHEM 101', 'srcU', '{"html": "دكتورنا رفع لنا السيلابس 🚬<br>تفضلوا 👍<br><br>​<span data-fid=\"stk-f1086999-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1086999-0": {"name": "CHEM 101 - 121.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem101-121/131117/5", "user": "THE_SILVER", "ts": 1346779482000, "tid": 131117, "pn": 5}}', 1346779482000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p820532-chem101', 'stk-user8044', 'CHEM 101', 'srcP', '{"html": "السلام عليكم ورحمة الله …<br><br>عندي اختبارين للفصلين الماضيين ( 092 - 101 ) مع الشرح التفصيلي لطريقة حل كل سؤال …<br><br>حبيت اشارككم فيهم حتى تستفيدوا منهم …<br><br>كل الأمنيات لكم بالتوفيق في الإختبار … 🌹<br><br>​<span data-fid=\"stk-f820532-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f820532-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f820532-0": {"name": "Major1- term092.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/31c0a383dc7e844933a92a1e8c3bf191275855530cfae9cd650b25f0a11ca3f5"}, "stk-f820532-1": {"name": "Major1-term101.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/56aa767ada49666c50039e479286844547d995e94bab6cfabdfd0ef45aea0f0a"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-old-exams-with-solutions/105317/1", "user": "user8044", "ts": 1300635785000, "tid": 105317, "pn": 1}}', 1300635785000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p633503-chem101', 'stk-equal', 'CHEM 101', 'srcP', '{"html": "لا تعتمد عليها … في المرفقات الـ zero versions لفاينلز سابقة … ولا ترفع الأفرج 😆<br><br>​<span data-fid=\"stk-f633503-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f633503-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f633503-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f633503-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f633503-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f633503-0": {"name": "063 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/3b8888eb1813ecd1ffddb7f5c2e436e07291960ee45e8cfef38a88c38c771127"}, "stk-f633503-1": {"name": "071 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a686a0eab0515e5cd7a205867ab5b638f02d78c9af7eb58b35b46966eb7685dc"}, "stk-f633503-2": {"name": "072 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fae73304abb8a9b2284ed3243d6ff827ec760e9c4f26586ed417da11ce7f23cd"}, "stk-f633503-3": {"name": "081 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/1dbb1bcb6a466fe876e36d1b4e908af6887d021ece7893fb2d9602810c2a73c2"}, "stk-f633503-4": {"name": "091 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/85348a05562c2dde70b3ac054815153da25bd43ec2d1dce6493d5ff7376c5ffa"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101-old-exam/90131/2", "user": "equal", "ts": 1276609224000, "tid": 90131, "pn": 2}}', 1276609224000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p770723-chem101', 'stk-everest', 'CHEM 101', 'srcP', '{"html": "في الرابط اللي حطيته موجود 092 محلول<br><br>وهاده 082<br><br>​<span data-fid=\"stk-f770723-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f770723-0": {"name": "final-082.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/9da028e1099931f0d6f7d6246abe959fd90a1ae0e0fb6e22e2bba1cfa71f0be3"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101/101242/6", "user": "EvErEst", "ts": 1295797817000, "tid": 101242, "pn": 6}}', 1295797817000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1195838-chem101', 'stk-sherlock_holmes', 'CHEM 101', 'srcP', '{"html": "بالتوفيق<br><br>​<span data-fid=\"stk-f1195838-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1195838-0": {"name": "Zero_Version_1st_Major_Exam.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/97f5df03fbffafbbd7efb3cd01fa26b7996ef00333b9887dbf8bf55440fa15ab"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-101/141581/8", "user": "Sherlock_Holmes", "ts": 1362528735000, "tid": 141581, "pn": 8}}', 1362528735000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisalcom2008-chem101', 'stk-faisalcom2008', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 111 - Chem 101\nالتحضير : يوميا\nطريقة الشرح : ابداااع تفهم غصبن عنك\nالكويزات : صللللخ … اصعب من المياجير بس اذا ركزت معاه صدقني المياجر تقلب عندك كوزات\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: يجيب النوم بصراحة\nإضافات :\nاذا لقيته مفتوح سجل معااه وانت مغمض ومطمن\nيعطيك العافية يا معلم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p968950-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/27", "user": "faisalcom2008", "ts": 1326712912000, "tid": 68452, "pn": 27}}]}', 1326712912000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mysterious-chem101', 'stk-mysterious', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور قوي جداً جداً بـ 201 لأنه متخصص بالـ Organic ,\n\nبالنسبة لـ كيمستري 101 قال لي شخصياً أنه أول مرة يدرّس هـ الكورس , ( تيرم 112 )\n\nكويزّاته مفيدة جداً وصعبة 🙂\n\nإلي يشرحه بالليكتشر في وادي والأسئلة في وادي ,\n\nمفيييد جداً بالريستيشن ,\n\nأخيراً ,\n\nالدكتور يمتاز بابتسامة سحـرية !! ما تشوفها إلا بالكويزّات والمياجر , D:\n\nالقريد النهائي : +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1051715-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/31", "user": "Mysterious", "ts": 1338940130000, "tid": 68452, "pn": 31}}]}', 1338940130000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a.ee-chem101', 'stk-a.ee', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 - 151\n\nالتحضير : يومي ويمرر ورقة على الطلاب\nطريقة الشرح : سلايدات ويستعمل السبورة لحل المسائل\nالكويزات : كويز على كل تشابتر من أربعة أسئلة خيارات مختلفة في الصعوبة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\nيميز الدكتور تعاونه وأخلاقه الطيبة … ويستقبل كل أسئلة الطلاب خلال الحصة وفي الغالب يجاوبها\nالمادة للأمانة ما تقيس قوة شرح الدكتور بشكل واضح\nالدكتور ما كان يسمح بالميك اب في الريسايتيشن … لأنه كان مقسمنا لمجموعات فيها وكل واحد لازم يحضر في مجموعته لكن يخليك تختار الريسايتيشن اللي يناسبك من بداية السنة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437880-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/45", "user": "A.EE", "ts": 1451822820000, "tid": 68452, "pn": 45}}]}', 1451822820000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10775-chem101', 'stk-user10775', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101\n161\n\nالتحضير :\nورقة تمر على الشباب و توقع عليها\n\nطريقة الشرح :\nيشرح بالسبورة مع السلايدات و يوضح النقاط اللي تحتاج شرح و يقيس مدى تفاعل الطلاب بطلبه مشاركتهم في حل بعض الأسئلة\nبالانقلش طبعا.\nالكويزات :\nمتوسطة من ناحية شرحه و الهوموورك اللي يعطيك إياه تقريبا نفس طريقة الهوموورك\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي:\nA\nالصوت:\nصوته مسموع نوعا ما بس طريقته شوي مملة و تجيب النوم فلازم يصير معك شاي و لا قهوة تخليك صاحي\nإضافات :\nطيب و ممكن يوضح لك النقاط و اللي تستفسر عنه بالعربي في المكتب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480659-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/50", "user": "user10775", "ts": 1505912156000, "tid": 68452, "pn": 50}}]}', 1505912156000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_1022-chem101', 'stk-_1022', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nCHEM101--Term 171\n\nالتحضير :\nتحضير يومي … ورقة تمر ع الطلاب\nيتضايق من التأخير\n\nطريقة الشرح :\nيشرح من سلايدات السعدي و يكتب ع السبوره … شرحه حلو\n\nالكويزات :\nكل أسبوع تقريبا في كلاس الريسايتيشن\nكويز في كل شبتر وأشوفها ممتازة حق تذاكر للميجر وتركز ع كل شابتر\nأشوفها متوسطة\n\nالمياجر:\nكومن .\n\nالفاينلات :\nكومنن\nالصوت:\n\nواضح ( بالأنجليزي) قليل يتكلم عربي\n\nإضافات :\nالدكتور طيب وأخلاق ويتجاوب مع أسئلة الطلاب …\nمشكلته : طيب ومتساهل ف تشوف بعضهم يسولفون ويستخدمون الجوال ويخربون ع غيرهم , هو يتضايق بس ما يتكلم\nبشكل عام الكمستري بعد ما أخذته استوعبت انه سيلف ستدي\nبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485997-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/51", "user": "_1022", "ts": 1515773581000, "tid": 68452, "pn": 51}}]}', 1515773581000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-chem101', 'stk-user12081', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "HASAN AL-MUALLEM\nCHEM101- T211\nبنود التقييم :\n\nالتحضير:\nيحضر مرة كل اسبوعين في اللكتشر , الريسايتيشن التحضير باوراق الكويزات.\nطريقة الشرح:\nالدكتور متمكن متمكن متمكن في المادة العلمية + متمكن في ايصال المعلومة, اذا سجلت عنده ما راح تشيل هم الفهم.\nالكويزات:\nكويزات مستواها مقارب للاولد اقزامز. عادلة جدا.\nالمياجر:\nكومون\nالفاينلات:\nكومون\nالقريد النهائي:\nA+\nاضافات:\nالدكتور عسل ومتعاون, مطلع في تاريخ العلماء اللي موجودين بالمنهج , يتكلم عنهم وعن جوائز نوبل للي ياخذها منهم وواضح انه مهتم فيها , والله انه يستاهل جائزة نوبل لكن وين اللي ينصفه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533250-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/60", "user": "user12081", "ts": 1641135653000, "tid": 68452, "pn": 60}}]}', 1641135653000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_alkalaf-chem101', 'stk-mohammed_alkalaf', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101\nTerm 211\n\nالمعلم وما امدراك ما المعلم … للامانة اسم على مسمى معلممم\n\nالشرح :\nالدكتور متمكن من المادة بشكل كبير ويوصل المعلومة لو تركز معه . طبعا يمكن بعض الايام تحس ان الكلاس ممل وودك تنام لكن م احس الدكتور له علاقة في ذا الموضوع هي المادة فيها بعض المواضيع الي مالها داعي\n\nالكويزات:\n\nكل شابتر عليه كويز تقريبا كل اسبوع كويز\nالكويزات وسط للامانة ومستواها مستوى الاولد اقزام ويجيب لك ٤ اسئلة خيارات … اختبرنا كويز يوم الاثنين وجانه سؤال نفس فكرته بالضبط في الميجر يوم الثلاثاء\n\nالتحضير:\nكل اسبوعين ثلاثة يحضر مره وحدة بس\n\nالدكتور متعاون جدا ويرحب بالجميع لو عندك اي شي + عنده اوفس اور اون لاين ليلة الكويز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533316-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/61", "user": "mohammed_alkalaf", "ts": 1641382392000, "tid": 68452, "pn": 61}}]}', 1641382392000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wiss_alamri-chem101', 'stk-wiss_alamri', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 - T211\n\nالتحضير :\nالتحضير كان شبه يومي غالبا بعد ربع ساعة من الكلاس عن طريق البلاك بورد، محد يقدر يحضر نفسه وهو غايب لانه يحط باسوورد ويعلمه الطلاب الحاضرين 😁\nمتساهل مع التأخير الى ثلث ساعة.\n\nطريقة الشرح :\nما شاء الله تبارك الرحمن، موسوعة ضخمة في الكيمياء، شرح جبار ومفهوم وبتفهم معه من وقت الكلاس بمعنى لو رجعت تبغى تراجع تلقى نفسك فاهم وتدخل عالأولد على طول.\nفعلًا، اسم على مسمى.\n\nالكويزات :\nكل اسبوع في الريسيتيشن، مستواها متوسط إلى صعب ولكنها بتجهزك للمياجر.\nعيبها الوحيد انها MCQ ويهتم فقط للفاينل أنسر.\n\nالمياجر:\nكومن.\n\nالفاينلات :\nكومن.\n\nالقريد النهائي:\nA++++\n\nالصوت:\nواضح جدا ومسموع واللكنة واللغة خياليين ما شاء الله.\n\nإضافات :\n- الدكتور دائما مبتسم واخلاقه وتعامله رائع جدا.\n- الدكتور ذاكرته قوية ما شاء الله ومن ثاني يوم بيعرف الأسماء.\n- ما يحب احد ينام او يستخدم الجوال.\n\nبإختصار، لا تفوت الموسوعة حسن المعلم وسجل عنده مهما كان وقته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535902-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/62", "user": "Wiss_Alamri", "ts": 1668448046000, "tid": 68452, "pn": 62}}]}', 1668448046000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silence-chem101', 'stk-silence', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68452", "n": "Dr. Hasan Al-Muallem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 (T221) & CHEM102 (T222):\n\nالتحضير :\nيحضر دايما, غالبا يحضر بعد ربع ساعة من بداية المحاضرة على البلاكبورد مع كلمة سر يعطيكم اياها اذا فتح التحضير\n\nطريقة الشرح :\nيشرح من سلايداته و الي تعتبر مصدر ممتاز في كلا المادتين, الشرح اكثر من ممتاز في كلا المادتين, الدكتور جدا فاهم و متمكن على توصيل المعلومة و الكونسبت, في الريسايتيشن يحل بالتفصيل اياً كان السؤال, الدكتور حرفيا يقدر يحل اي سؤال ماشاءالله تبارك الرحمن\n\nالكويزات :\nجميع الكويزات MCQ, مستواها متفاوت لكن اغلب الاحيان متوسطة مائلة الى السهلة\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nممتاز و انجليزيته اكاديمية و واضحة, نادرا يتكلم عربي\n\nإضافات :\nالدكتور منظم و دقيق في كل شي, يحب الي ينتبه معه, جدا متعاون و حبيب مع الطلاب و بيئة الكلاس حلوة, يشاور الطلاب دايم في مواعيد الكويزات و متساهل في هذا الجانب, اذا انت شخص مايركز في الكلاس ف يفضل مايعرف اسمك لأن اذا عرف اسمك راح يقعد يناديك دايم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538830-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-al-muallem/68452/63", "user": "Silence", "ts": 1736346797109, "tid": 68452, "pn": 63}}]}', 1736346797109, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10508-chem101', 'stk-user10508', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور شكله جديد في التدريس، ماخذ الدكتوراه 2014\n\nاخذ عنده الحين 101\n\nالتحضير : كان يمرر ورقة في البداية ويوم شاف تسيب صار ينادي بالسيريال نمبر وأحياناً ما يحضر\n\nطريقة الشرح : من سلايدات الكتاب الرسمية نفسها - ينقز سلايدات ويمشي عليها بدون ما يخلصها وشرحه غير منظم ويشرح مثال واحد أو مثالين ويعيد ويزيد في نقطة وحدة ، شرحه بشكل عام ممل لكنه يشرح أشياء مهمة إذا تركز معه وبتلقاها مهمة إذا صرت تقرا الكتاب أو تحل الاولد اكزامز، الدكتور ماعنده اي اسلوب ممتع يجئبك عشان تنتبه معه زائد انك تنتبه معه يبيلها جهد عشان تفهم وتربط كل الكلام اللي يقوله، لأن أحياناً تظل أفكار معلقة ما قفلها من محاضرة لمحاضرة ثانية فلازم تربط كل الكلام للي يقوله مع بعض\nمايشرح الكونسيبت ابد تلقاه على طول يطب في المسائل فلازم ترجع للكتاب وتقراه عشان تفهم الكونسيبتس\n\nالكويزات :متوسطة ‘لى صعبة، في السؤال الواحد يعطيك معطيات أقل من المعطيات اللي تكون في اسئلة المياجر ويطلب منك مجاهيل أكثر من المياجر وتصحيحه عالفاينل انسر ، صحيح إن كويزاته تجهزك للمياجر لكن عليها 17 درجة يعني أكثر من الميجر الثاني\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالتقييم النهائي: حاول لا تنزل عنده لأن المادة معاه ثقيلة، لكن إذا ما لقيت الا هو نزل وركز معه في الشرح خصوصا حله للمسائل في الريسايتيشن\n\nالصوت: واضح لكن لغته الإنجليزية سيئة جدا وبتلخمك بعض الاحيان\n\nإضافات : أفرج سكاشنه عالي في الميجر الأول سكشنا كان أعلى أفرج بين كل سكاشن الكيميستري 101\nوالميجر الثاني كنا أعلى من الأفرج بأكثر من 10 بمالية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434231-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/5", "user": "user10508", "ts": 1448227670000, "tid": 68453, "pn": 5}}]}', 1448227670000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10547-chem101', 'stk-user10547', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 - CHEM101\n\nتحضير : في البداية كان يمرر ورقة التحضير وبعدها بالسيريال نمبر واحيانا يطالع بالوجيه ويعرف من غايب , ماشاء الله يحفظ الاسامي بسرررعه\n\nطريقة الشرح : سلايدات الكتاب الرسمية, شرحه جيد جدا يحاول يوصل المعلومه للطالب قد ما يقدر ويعيدها اكثر من مره , بتسمع هالكلمة كثير \" make sure you know \" وبيكمل الجملة وبيعطيك معلومه بتفيدك بالكوز\n\nالكويزات : مو سهله ابدا مرات تكون اصعب من الميجر, لكن في النهاية الكلاس وورك بيرتفع عشان النورملازيشن\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: طبقة وحده ويرفعها اذا كان فيه احد يسولف :d\n\nإضافات : المدرس اخلاق واي شي ما تفهمه تروح له اوفيس اور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438661-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/9", "user": "user10547", "ts": 1452571766000, "tid": 68453, "pn": 9}}, {"id": "stk-dr-f94389", "n": "Dr. Nurudeen Odewunmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 - CHEM101 lab\n\nتحضير : يحضر عن طريق كوز في بداية الحصه\n\nطريقة الشرح : اللاب اربع ساعات يروح نص اللاب والرجال يشرح لنا بالكلام بشكل ممل جدا\n\nالكويزات : بداية الحصه وغالبا تكون الاسئلة من كتاب اللاب وتقدر تلقى الاجوبة في موقع الياهو انسر\n\nالقريد النهائي: أعطيه B\n\nالصوت: الصوت واضح مافيه مشكلة بس لهجته صعبه واحتمال ما تفهم بعض الكلمات\n\nإضافات : درجات الطلاب قريبة من بعض جدا فما بتفرق معك الدرجة, لكن اللاب معه متعب لان اغلب الايام تطلع قبل ما يخلص اللاب بنص ساعة مع العلم بعض المدرسين ما تمر ساعتين الا والطلاب مخلصين اللاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438662-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nurudeen-odewunmi/94389/6", "user": "user10547", "ts": 1452572458000, "tid": 94389, "pn": 6}}]}', 1452571766000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osamah56-chem101', 'stk-osamah56', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 term 152\n\nالتحضير: في بداية السمستر ورقة تمشي بين الطلاب اما في النهاية هو يحضر وتروح 10 دقايق من المحاضرة بس تحضير بس ماله وقت محدد متى ما تذكر التحضير حضر.\nالكويزات: كويزاته سهلة مجرد تركيز معه يأهلك انك تجيب درجة زينة.\nطريقة الشرح: يفتح سلايدات الكتاب وفي أغلب الأوقات يقرأ ويجي ملل مو طبيعي والي يمكن مخرب زيادة لغته الانجليزية.\n\nللأمانة الدكتور ما مر علي شخص بأخلاقه واحترامه وحرصه على الطالب لكن نصيحة اذا سجلت عنده حاول تخلي الليكتشر الي بعدها ف مبنى قريب ,لأنه من بداية السمستر ما قد طلعنا على الوقت أقل شي ياخذ دقيقتين زيادة ويزعل اذا الطلاب اتركوه ومشوا\n\n+ غير متواجد ف مكتبه في الoh رحت مرتين بالوقت الي هو قالي ومالقيته واستنيته فوق ربع ساعة ولا جاء اضف الى ذلك انه ما يرد اذا ارسلت له ايميل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448020-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/12", "user": "osamah56", "ts": 1462303852000, "tid": 68453, "pn": 12}}]}', 1462303852000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_alghamdi-chem101', 'stk-abdulrahman_alghamdi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-172\n\nالتحضير : بداية الكلاس أو نهايته يحضر بالرقم التسلسلي، وياويلك تحضر خويك.\n\nالشرح : يبدأ يشرح النقاط المهمة في الدرس وأيضاً يبدأ بمقدمة بسيطة عن محتوى المحاضرة، بالنسبة لي كنت فاهم الكيمستري من البداية فانتبهت لبعض الأخطاء الي طاح فيها، لكنه يدركها قبل ما ينتهي من الشرح. باختصار، شرحه فيه شوية أخطاء رح تلخمك لكن رح يستوعب ويصحح غلطه.\n\nالكويزات : ما أخذت عنده الكويزات لأني وقعت مع الفخ الأعظم (خرم جويا)\n\nالمياجر : كومن\n\nالفاينلات : كومن\n\nالقريد النهائي : B+\n\nالصوت : واضح لحدٍ ما\n\nإضافات : الدكتور حبوب ومتعاون جداً مع طلابه، مشكلته الوحيدة وما أعتبرها مشكلة أصلاً هي لهجته الانجليزية، في البداية ما حتفهم عليه كم كلمة لكن مع الوقت رح تستوعب , مثلاً كان فيه مصطلح اسمه (formal charge) كان يقول عنه (formula charge) ما استوعبت معنى الي جالس يقوله إلا بعد كلاسين.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498915-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/14", "user": "Abdulrahman_Alghamdi", "ts": 1536238764000, "tid": 68453, "pn": 14}}]}', 1536238764000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tsonayoshi-chem101', 'stk-tsonayoshi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-182\n\nالتحضير : اول اسبوعين يوزع ورقة التحضير بعدين لما تثبت عنده الاسماء يصير يحضر بنفسه اثناء ما يعطينا مسالة نحلها شديد بالتحضير\n\nالشرح : يشرح من سلايدات الكتاب لكنه معدل عليها شوي وضايف عليها زيادة من عنده ، يوصل المعلومة ويعيد اذا ما فهمت\n\nالكويزات : كان معنا دكتور ثاني Mohammad Abu Jafar Mazumder للريسيتيشن بس عموما متوسطة الصعوبة\n\nالمياجر :\n\nالفاينل :\n\nالقريد النهائي : B+\nاضافات : زي ما قالو الشباب اللهجة احيانا تصير تعبانه مثلا كلمة water vapor صارت viber مدري شلون ، في حصة المراجعه ما يعطي سلايدات الاسئلة بعدين بالبلاك بورد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509871-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/16", "user": "tsonayoshi", "ts": 1558212190000, "tid": 68453, "pn": 16}}]}', 1558212190000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11839-chem101', 'stk-user11839', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 / 191\n\nالتحضير :\nبداية الترم كان متساعد بالتحضير وورقة تمر ولكن الكلاس صار فاضي وورقة التحضير فل.\nقام غير النظام وصار يحضر هو اول بأول ويخصم عالغيابات.\n\nطريقة الشرح :\nزي ماقال اللي قبلي،. شرحه من سلايدات الكتاب مع اضافات من عنده، وكشرح حسيته ماهو ذاك الزود مايوصل المعلومة بشكل ممتاز ولا كنت افهم عليه ويستقبل الاسئلة وقت المحاضرة.\n\nالكويزات :\nحق الريسايتيشن يسويها الدكتور وسيم.\n\nالقريد النهائي:\nB\nالصوت:\nوااااضح جدداااا\nإضافات :\n\n1 - الدكتور فاتح مكتبه وماخذ قاعة بعد كل كلاس للي عنده اسئلة.\n2 - قبل المياجر / الفاينل يجلس كلاس يحل كذا سؤال من الاولد اقزام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518366-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/17", "user": "user11839", "ts": 1577422087000, "tid": 68453, "pn": 17}}]}', 1577422087000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-chem101', 'stk-khdsa2022', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f180471", "n": "Dr. Majad Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ترم 172 وكان اول ترم يدرس فيه .\nالتحضير : مرن وطيب بزيادة .\n\nطريقة الشرح : قراءة سلايدات مثله مثل اي مدرس كستري 101 , تقريبا الوحيد اللي يشرح هو العرفج والله اعلم.\n\nالكويزات : سهلة الى متوسطة , مقدور عليها\n\nالمياجر:كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: واضح وما يبان انه بكاستاني لانه مولود و عايش ببريطانيا\n\nإضافات : نزل عنده و انت مغمض بس لا تنسى مادة كمستري 101 تحتاج من الطالب انه يشتغل و يذاكر . الدكتور من ثاني اسبوع بيصير عارف معظم الكلاس .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513289-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majad-khan/180471/5", "user": "Khdsa2022", "ts": 1564834171000, "tid": 180471, "pn": 5}}, {"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :توفيق صالح\nالمادة:CHEM 101\nمنقول عبر واتس اب\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :بداية الترم الى بعد الميجر الاول بيوم ما كان يحضر بعدها شد لكن اكتشفنا انه ما كان يرصد اغلبها\n\nطريقة الشرح :شرح لا يعلى عليه ما تمل منه اذا شافت الطلاب مالين او تعبانين قام ينكت ويغير جو الكلاس ثمين يرجع للشرح\n\nالكويزات : من متوسطه الى سهله\nالمياجر:كومن الاول كان الافرج 11 الثاني كان 13\nالفاينل :كومن كان صعب الافرج 60\nالقريد النهائي:A\nالصوت:واضح\nإضافات : شخص محترم متساعد يقدم اوفس اور خارج اوقات الدوام يرد على الايميل باسرع ما يمكن يسوي هيلب سيشن كل اربعاء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518750-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/49", "user": "Khdsa2022", "ts": 1578209271000, "tid": 69430, "pn": 49}}, {"id": "stk-dr-f68453", "n": "Dr. J Al Thagfi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : جميل الثقفي\nالمادة: CHEM 101\nBY WHATS APP\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بداية الترم كان يدف ورقه وكل واحد يحضر نفسه بعد الميجر الثاني تقريبًا بدا يحضر بنفسه وصار كريه جدًا بالتحضير\nطريقة الشرح : يقرا السلايدات ولا احس انه يقدم لك فايدة\nالكويزات : الكويزات ما كانت بيده كانت بيد دكتور الريساتيشن\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D\nالصوت: واضح\nإضافات : حاول ما تسجل عنده الا اذا يناسب وقتك والوضع سيلف ستدي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518792-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-thagfi/68453/18", "user": "Khdsa2022", "ts": 1578285548000, "tid": 68453, "pn": 18}}, {"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATS APP\nاسم الدكتور : عبدالرحمن العرفج\nالمادة: كيمياء 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يمرر ورقة على الطلاب وشوي متشدد في التحضير. المادة مافيها غيابات مجانية بس هو يعطيك 2 مجانا\nطريقة الشرح : شرح سلايدات عادية\nالكويزات : سهلة ومافيها تركات صعبة فنقصنا تقريبا 4 درجات في النورملايزيشن\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:\nالصوت: واضح\nإضافات : المادة سلف ستدي وماتعتمد على الدكتور، لازم تذاكر الكتاب اذا تبي قريد محترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518798-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/50", "user": "Khdsa2022", "ts": 1578286364000, "tid": 68483, "pn": 50}}, {"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : محمد صديقي\nالمادة: chem101\nBY WHATSAPP\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يومي وما يدقق يعني تقدر تحضر اخوياك بس لا تزودها لأن طول السمستر كامل يمكن راجع التحضير ٤ مرات وحتى لو قفط ما يسوي شيء كبير\nطريقة الشرح : يفتح سلايداته ويشرح قدر الامكان يحاول يوصل الفكرة نصيحة اي شيء ما تعرف فيه روح المكتب لأن انا اكتشفت فائدة الاوفيس اورز نهاية الترم، شرح لي اشياء كثير وبأسلوب جداً واضح غير عن المحاضرات\nالكويزات : سهلة\nالمياجر: مشتركة\nالفاينلات : مشتركة\nالقريد النهائي:\nالصوت: جداً واضح ولو كنت اخر شخص بالقاعة\nإضافات : الدكتور طيب و حبوب ويعامل الطلاب كأنه اب لهم ، وايضاً افضل شيء فيه تلطيف الجو يعني كل شيء قال نكتة او اي شيء يجذب انتباه الطلاب وبكذا يقدرو يركزو معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518807-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/37", "user": "Khdsa2022", "ts": 1578288518000, "tid": 68459, "pn": 37}}]}', 1564834171000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_alnamassi-chem101', 'stk-omar_alnamassi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يمرر الورقة على الطلاب ويتضايق اذا احد حظر لخويه ( من حقه صراحة )\nطريقة الشرح : ممتازة جداً , يتقبل الاسئلة ويحاول ما يعدي فقرة الا والكل فاهمها\nالكويزات : جيدة جدا\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: ممتاز\nإضافات : يحب يساعد الطلاب ويتعاون معاهم\nيحاول قدر المستطاع انه يوصل المعلومة للكل\nخلوق ومحترم ويستحق الاحترام\nصراحة استمتعت عنده وكنت افهم معاه وشخصيا اخذت عنده كمستري 101 في ترم 132 وكنت اتمنى انه يدرس 102 في ترم 141 كنت بنزل عنده بس للاسف ما حصلته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1367722-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/26", "user": "Omar_Alnamassi", "ts": 1400610704000, "tid": 68455, "pn": 26}}]}', 1400610704000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-userdahm-chem101', 'stk-userdahm', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101 - term 132\n\nالتحضير :\nكل كلاس يمرر ورقة على الطلاب\nيقول للمتاخرين اكتبوا late في الورقة , عاد انت وضميرك تكتب late و الا لا\nطريقة الشرح :\nفهمه للمادة موب مرة بس طريقة تقديمه لها رهيب : اول كلاس ريسايتيشن يوزع الطلاب حسب درجاتهم\nلقروبات متساوية بعدين يقول اجلسوا جنب بعض في الكلاس بعدين يعطي اسئلة للقروبات في الكلاس\nفتلقى كلاسه نشيط غالبا\n\nالكويزات :\nكويز يعطيك هومووركين تحل ميجر 1 و ميجر 2 بالخطوات\nكويز ثاني online homework\nو10 كويزات MCQs\nold exams نصصصص ما يغير شيء غالبا سهلة\nويخليك تحلها في قروبك اذا خلصتوا مختبرين\nويعطيك سكراتش شييت حقات اكشط واربح و تشوف اجابتك صح والا غلط\nوفي الاخير يحذف اسوء كويز\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\nالصوت:\nواضح جدا\n\nإضافات :\nهو الي ماسك الريسايتيشن غالبا تكون فيها الكويزات\nمتساعد جدا وخلوق مع الطلاب في الكلاس\nيحب التنظيم وهو الصراحة مرتب ومنظم\nيرسل الدرجات بسرعة على الايميل بطريقة رهيييييبة على شكل ريبورت مع الافريج\nيحاول يغيير نظرة الطلاب في المادة هذي للافضل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374934-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/27", "user": "userdahm", "ts": 1401536347000, "tid": 68455, "pn": 27}}]}', 1401536347000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-chem101', 'stk-mr.a1', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172594", "n": "Dr. Shehzada Muhammad Sajid Jillani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 152 : CHEM 101 Lab\n\nبنود التقييم :\n\nالتحضير :\nعلى البري لاب.\nطريقة الشرح :\nيدخل قبل بداية اللاب بـ 10-15 دقيقة ، ويكتب كل شيء على السبورة من خطوات وقوانين وثوابت…الخ. بعد البري لاب، ياخذ وقت في شرح كل كلمة كتبها لك على السبورة + يعلمك وش تسوي في الريبورت وكيف تسوي الحسابات فيه\nالكويزات :\nمن سهلة الى متوسطة. تجي من الشرح اللي ببداية التجربة ، وأحيانا يجيبها من البري لاب.\nاللي لاحظته إن بعض المدرسين يقولون لطلابهم يحلون بعض الاسئلة من البري لاب ويقطعونه ويحطونه مع الريبورت ، لكن مع جيلاني الوضع مختلف، يجيب لك الكويز على اوراق من عنده ويقول لك تحله بداية اللاب.\nالمياجر:\nلا يوجد\nالفاينلات :\nالنظري: جابه نسخ لصق من كويزات البري لاب السابقة\nالعملي: التجربة كانت محددة من الديبارتمنت ، ونظام التصحيح واضح وطبقه بحذافيره، تصحيحه عادل\nالقريد النهائي:\nA+\nالصوت:\nواضح ، آكسنت باكستاني راح تتعود عليه مع الوقت\nإضافات :\nجو اللاب العام جميل. يحسسك إنه خويك ويسولف ويضحك مع الطلاب ، وهذا اللي مخلي الطلاب يحبونه\nمتى ما خلصت شغلك تقدر تمشي، بس ما راح تقدر تخلص قبل 3 لأنه ياخذ 20-25 دقيقة على البري لاب + 20-25 دقيقة - على الاقل - وهو يشرح ويوضح لك كل شيء.\nأنصح فيه كثير للي يبي لاب مريح ، باستثناء تجربتين بتتعب فيهم اشوي لأنهم طويلين جدا\nطبعا الشغل في اللاب فردي ، لكن تقدر تتناقش مع اللي جنبك أو أي أحد، فهو ما يدقق حول هالموضوع. تجربتين في الأخير خلى الشغل فيهم قروبات ؛ حتى يختصر الوقت علينا\n\nدرجات سكشننا (بعد النورملايزيشن):\nhttp://uploads.tapatalk-cdn.com/20160509/bba63d011c86f130673aa0f9fbb13979.jpg", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444015-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-shehzada-muhammad-sajid-jillani/172594/2", "user": "Mr.A1", "ts": 1457551159000, "tid": 172594, "pn": 2}}, {"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. خالد الحوشاني\n\nد. خالد الحوشاني\n\nأستاذ مساعد\n\nhttp://faculty.kfupm.edu.sa/chem/hooshani/\n\nTerm 152 CHEM 101\n\nبنود التقييم :\n\nالتحضير :\nشيء مقدس. كل محاضرة وكل ريسايتيشن. يمرر الورقة على الطلاب ويوقعون. سبق ونبه إنك ما يصير تحضر خويك وكذا ، بس ما شيك لأن عنده 112 طالب في القاعة\nطريقة الشرح :\nبداية الترم كان يرسل لنا فيديوات - 15-20 دقيقة - ، تشوفها ثم تحل Pre-Lecture على موقع الناشر ، بعد فترة شاف كثير من الطلاب مو متأقلمين مع الطريقة وما يهتمون فيها فصار يجي يشرح في الكلاس بدون ما يرسل لنا فيديوات ؛ لأن الهدف منها حل مسائل اكثر في الليكتشر بس الشعب ما يشوفونها فيجون مو فاهمين شيء\nكشرح أشوفه ممتاز جدا ويعرف يوصل الكونسبت ؛ لكن أحيانا اشوفه يجي وهو مو مستعد فيرتبك وتطلع عليه بعض الاخطاء\nالكويزات :\nكل اسبوع تقريبا ، عدا اسابيع المياجر يجيبها من الاولد اقزام ودايما تكون من وسط الى صعب - راح اتكلم عن تجربتي مع المادة في موضوع مستقل -\nأخذنا 10 كويزات ، وأخذنا قروب كويز في آخر كلاس - بتكلم عن القروبات في الاضافات - ، وحذف اسوأ كويز بين الـ 11 كويز اللي اخذناها\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nجهوري وقوي ، آكسنت انجليزي قصيمي - أول مرة اسمعه [emoji16] -\nإضافات :\nالدكتور يحب العمل الجماعي. بداية الترم راح يقسم الطلاب الى قروبات حسب معايير هو راح يطلب منكم تكتبونها في ورقة ثم يوزعكم\nيستخدم التقنية بشكل رائع: درجات الكويزات ، المياجر ، الفاينل ، كلها يرسل لك درجتك على الايميل بالاسم مع آفرج السكاشن الثلاثة\nأيضا نهاية الترم راح يرسل لك تقرير كامل بأدائك مع ترتيبك على الثلاث سكاشن اللي عنده\nبعد كل كويز يخلي كل قروب يتجمعون ويحلون الكويز مع بعض ويتناقشون حوله ، وهذا كويس عشان تعرف أخطائك\nمن أبرز النقاط اللي أعجبتني فيه إنه ما يسرع في الشرح عشان يلحق السيلبس ، ما عنده مشكلة لو يتأخر عشان الطلاب يفهمون\nباختصار: د. خالد الحوشاني = [emoji106]", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449089-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/33", "user": "Mr.A1", "ts": 1463331406000, "tid": 68455, "pn": 33}}]}', 1457551159000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed3-chem101', 'stk-mohammed3', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68455", "n": "Dr. K Alhooshani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تيرم 181 كورس كمستري 101\nالتحضير : يمرر ورقة للطلاب وتوقع جنب اسمك طبعا يزعل اذا حصل احد موقع عن خويه ومره صاد كم واحد لكن عطاهم تنبيه وعطى تنبيه للكل بشكل عام\n\nطريقة الشرح : يشرح من سلايدات السعدي يقرا منها الكونسبت واذا فيه شي منها يحتاج تفصيل وشرح يوقف ويبدا يشرحه شفهيا او يستخدم السبورة. طبعا يحل كم مسئلة معنا يعطينا وقت معين دقيقة الى دقيقتين عشان نحلها بعدها هو يحلها ويشرح طريقة حلها. بداية كل كلاس يحب يسوي مراجعه بسيطة للي الدروس اخذنها الكلاس\nالي قبل.\nالكويزات : كان يكتبها دكتور الريساتشين ماجد خان وكل اسبوع في كلاس الريساتشين كان فيه كويز\n\nالمياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي: A+\n\nالصوت:واضح والاكسنت واضح وهو يشرح يمشي بين الطلاب عشان يصير صوته اوضح واقرب للطالب\n\nإضافات :الدكتور حبيب مره واخلاق ومن افضل الدكاترة الي تعاملت معاهم ويحاول يوصل المعلومة قد مايقدر للطلاب ومتساعد مع الطلاب من ناحية تأجيل الكويزات وغيره ودائما بعد المياجر يرسل رسالة للطلاب ويسئلهم كيف كان ادائهم في الميجر هل بدعو او خبصو السلبية الوحيدة الي فيه اذا جا يسئل يختار طالب عشوائي بالبرنامج ويسئله وذا الشي كثير من الطلاب مايحبونه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503620-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-alhooshani/68455/38", "user": "Mohammed3", "ts": 1544889323000, "tid": 68455, "pn": 38}}]}', 1544889323000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5712-chem101', 'stk-user5712', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f96572", "n": "أ. أوك سالم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أولاً هو دكتور وليس محاضر\n\nثانياً بالنسبة للتقييم\nأنا أخذت معه كمستري 101 (لكشر) في سمستر 102\nوهالمدرس ما أنصح به وبقوة ، للأسباب التالية :\n\nالتحضير :\nبداية السمستر يمرر ورقة على الطلاب ويوقعوا ، بس هو شرحه قراءة من السلايدات يعني ما تقدر تستفيد من وراه شيء حتى لو حضرت ، علشان كذا كانوا الطلاب يحضرو أخوياهم وهم مو موجودين ، لما اكتشف الموضوع بدأ يحضر بالأسماء فترة وفترة يخلي الطلاب يوقعوا وبعدين هو يشيك بشكل عشوائي (أغلب الأيام يكتشف ناس محضرين وهم غير موجودين ويسوي الزحمة)\n\nطريقة الشرح :\nقراءة من السلايدات اللي من عند الديبارتمنت ، طبعاً يجي الكلاس وهو ما هو محضر شيء أبد ، يعني أول مرة يشوف السلايد ، حاله حالك ، فيبدأ يقرأ بس ويخبص في القوانين ، يستخدم السبورة نادراً بس حق شخابيط ما تقبض من وراه شي ، وكل شوي يقول مقوله المشهور by the way, why don’t you take notes ، يبقى الطلاب تكتب نوت وهو جالس يقرأ من السلايدات بس ، يعني لما تكون محضر قبل الحصة وتحضر عنده تختبص وتنسى اللي كنت محضره ، لأن الرجال مخبوص وخبل\n\nالكويزات :\nفي بداية السمستر يخير الطلاب بين كوزات كتابة أو اختيارات ، طبعاً كل الطلاب قالوا اختيارات ، فيسوي 6 كوزات في الريسايتيشن ويأخذ أفضل 5 ، بشكل عام الكوزات سهلة وواحد أو اثنين صعبين ، بس الكوز عبارة عن 3 أسئلة سؤالين على 30 وسؤال عليه 40 فلو تخطأ في سؤال تجيب 60/100 ، بس أغلب الطلاب درجاتهم زينة في الكويزات وهذا النقطة ما هي زينة في شغلة الأفرج لكل كلاس.\nطبعاً ما عنده شيء اسمه ميك أب (إعادة) كويزات ، حتى لو عندك عذر رسمي يمسح عنك الغياب بس ما يعيد لك الكويز\nولا يرضى أنك تحضر ريسايتيشن كلاس ثاني ، يقول أوراق الكويزات ما تكفي\n\nالمياجر:\nما له شغل في المياجر لأنها كومون ، ولا يدري عن أي شيء يتعلق بالميجر حتى لو تسأله قبل 4 أيام عن متيريال الميجر يقول لك أنا جديد ولا أدري عن نظام الجامعة!! بس قبل الميجر بيوم أو نفس يوم الميجر يجي ويعطيك معلومات الميجر ، يعني هو أهم شيء عنده أنه يقرأ على الطلاب السلايدات(باعتباره يشرح) وخلاص ماله شغل فيه ولا في أفرج الكلاس\n\nالقريد النهائي:\nصراحة هالرجال من ناحية شرح دمار ، بس المادة تمشيء بمذاكرة الكتاب بس\nحده D ويخب عليه\n\nالصوت:\nعادي تقدر تسمعه\n\nإضافات :\nالمدرس دمار ولا يشرح ولا يحضر للدرس قبل ما يجي ، يعني يطعيك الكلاس على البركة، وأخلاقه لك عليها يعني يجي يوم مروق ويوم ثاني لا أحد يكلمه بالعربي هالرجال مزاجي درجة أولى ، بس المادة ما فيها تعقيد واجد ، يعني لو اضطريت عنده بتمشي أمورك ، بس يفضل وبقوة أنك تبتعد عنه\n\nولا أنصح أحد أنه يضبط وياه أو يخليه يعرف أسمه أو شكله ، لأنه لو عرفك بيبهدلك كل يوم يسأل عنك وينتبه لك ، يعني ما تقدر تخلي أحد من الشباب يحضرك ، فمعرفته ما تجيب إلا المصايب حتى في التصحيح يشدد عليك ، وبعدين يعطيك النتيجة دمار وهو يضحك في وجهك (تحس أنه خبيث)\n\nطبعاً هو ما يستخدم لا ويب سيتي ولا إيميل ولا نت ، فإذا عطاك كويز أو شيء مالك إلا تنتظر إسبوعين أو 3 أسابيع على ما تجيك النتيجة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p840595-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96572/13", "user": "user5712", "ts": 1304587792000, "tid": 96572, "pn": 13}}, {"id": "stk-dr-f68456", "n": "د. عبد اللطيف ابداح", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت مع لاب كمستري 101 في سمستر 102\nوهو أحسن مدرس لاب مر علي ، ولا بتلقى مدرس لاب مثله في الكمستري\n\nالتحضير :\nولا مرة حضر ، طول السمستر\n\nطريقة الشرح :\nبداية الحصة يشرح التجربة شرح وافي ، وبشكل سريع ، ولو كانت التجربة طويلة يخلي شرحة مجزأ ، يعني يشرح قسم ويسوي عليه تجربة وبعدين القسم اللي بعده ويسوي عليه تجربة علشان ما نختبص ، وطبعاً يساعدك في أي جزء من الريبورت وهو يضحك ، وفيه ميزة غير عن مدرسين اللاب الثانيين أنه يكنسل أشياء كثيرة من الريبورت مثل الرسمات والأشياء المعقدة ، طبعاً هو رجال بشوش حيل ، وتقدر تسولف معه كأنه واحد من الشباب حتى لو تقص في مدرسين ثانيين يقعد يضحك ولا يقول شيء\n\nوقت اللاب :\nولا مرة أخذنا وقت اللاب كامل ، هو لاب الكمستري المفروض 4 ساعات أحنا أغلب الحيان 3 ساعات وبعض الأحيان ساعتين بس ، ولو عندك ظرف أو شيء يخليك تمشيء وبعدين تسوي التجربة أو تنقلها من ربعك ، يعني الرجال متساهل وزي العسل\n\nالكويزات:\nما عنده شيء اسمه كويز قبل التجربة ، ولا يحتاج تحضر للتجربة ، بس بعض الأحيان يخليكم تحلوا سؤالين من المنوال في نهاية التجربة وتضيفوهم للريبورت باعتبار أنهم كويز ، وهالسؤالين تستخدم فيهم نفس القوانين اللي شرحهم، والقوانيين يكونوا على السبورة يعني ما يحتاج تحضر للكويز ، ولو خبصت تقدر تشوف اللي جنبك وهو ما يدري عنك\n\nقريد اللاب :\nأحلى تصحيح تآخذه عنده ، أقل قريد أخذته عنده 90/100 طبعاً في طلاب يجيبوا أقل علشان يوازن الأفرج النهائي، بس لو سويت مثل اللي يبي بالضبط بتأخذ قريدات حلوة لكن ما أحد يعطيه أقل من 60/100\n\nالقريد النهائي:\na+ وبجدارة ، لأنه رجال محترم ويخلي اللاب عندك يمشي مثل الحلاوة ، ويسولف مع الطلاب\n\nالصوت:\nعادي ، لأن كان في لاب ، بس ما أدرس عن اللكتشر\n\nإضافات :\nطبعاً هو من أفضل مدرسين اللابات ، فأكيد نزل عنده وأنت مغمض ، وطبعاً سكشنه يسكر بسرعة خصوصاً سكاشن اللابات ، فخلك ذيب وأنت تسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p840604-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68456/26", "user": "user5712", "ts": 1304589121000, "tid": 68456, "pn": 26}}]}', 1304587792000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad18-chem101', 'stk-ahmad18', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68456", "n": "د. عبد اللطيف ابداح", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب كمستري 101 في ترم 102\n\nالتحضير :\n\nما يحضر ابد في اللاب …\n\nطريقة الشرح :\n\nيشرح التجرب في بداية اللاب وانت تطبق واذا بغيت مساعدة او شي اساله مافي مشكلة …\n\nبس نصيحة لا تسالو اساسيات في الكمستري لانه ممكن يحرجك شوي …\n\nالكويزات :\nبعض اللابات يعطينا في نهايتها كويزات والكويز داخل من ضمن درجة اللاب واسالته سهلة ومن نفس الكتاب اذا كنت مركز في اللاب مضبوط وفاهم التجربة ان شاء الله علامة الكويز في يدك\n\nالمياجر:\nالفاينلات :\n\nالقريد النهائي:\n\nb+\n\nالصوت:\n\nكان واضح بالنسبة لي\n\nإضافات :\n\nالدكتور عبد اللطيف اخلاق ويحرجك باخلاقه العالية يعني بس في نقطة وحدة انه احياااانا احيااانا يغلط في تصحيح الريبورت ف لو تقدر كل ريبورت بعد التصحيح تراجعه لحالك واذا لقيت نقطة مهي بعاجبتك رحله ويصحح لك هي اذا شاف ان هو غلط …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p854270-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68456/28", "user": "Ahmad18", "ts": 1308298677000, "tid": 68456, "pn": 28}}]}', 1308298677000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salh_1-chem101', 'stk-salh_1', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68457", "n": "Dr. A. Kawde", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-Term191\n\nالتحضير: ورقة في بداية الكلاس تمر عالطلاب ويقول الي مشغول ولا ما يبي الكلاس يوقع ويمشي وكثير كانوا يوقعون عن بعض.\n\nطريقة الشرح: يشرح السلايدات ويضيف أشياء من عنده وشرحه جدا ممتاز.\n\nالكويزات: متوسطة وكلها اسئلة اولد اقزامز\n\nالمياجر: --\n\nالفاينل: --\n\nالصوت: واضح جدا\n\nالقريد النهائي: A\n\nإضافات: الدكتور فاهم المادة وشرحه جدا ممتاز واحيانا ينكت عالطلاب ويغير الجو واعتقد اول مره له يدرس 101 ويتساعد احيانا مع الطلاب في تأخير تسليم الواجبات وكذا\nأنصح فيه صراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518576-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-kawde/68457/16", "user": "Salh_1", "ts": 1577886304000, "tid": 68457, "pn": 16}}]}', 1577886304000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yasser123231-chem101', 'stk-yasser123231', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68457", "n": "Dr. A. Kawde", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101-192\nالتحضير : ورقة تمر على الطلاب، ومايدقق ابدا، كثير من الشباب يحضرون لبعض.\nطريقة الشرح : يقرأ سلايدات الكتاب.\nالكويزات : سهلة وبالغالب يجيبها من الواجب، كثير يجيبون فل (يرتفع الافرج).\nالمياجر:—\nالفاينلات :—\nالقريد النهائي:—\nالصوت: ممتاز\nإضافات : الدكتور خلوق جداً، وشخصيته جميلة، لكن من ناحية التدريس والشرح فالحقيقة اقل من المستوى، يعني المحاضرة عبارة عن قراءة السلايدات، فماراح تطلع بأي فايدة من المحاضرات. والكويزات والواجب راح تنزل حتى لو تجيب فل بسبب الافرج المرتفع.\n\nنصيحتي اذا كنت مجتهد وودك بقريد لاتنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521921-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-kawde/68457/17", "user": "Yasser123231", "ts": 1589097863000, "tid": 68457, "pn": 17}}]}', 1589097863000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_n1-chem101', 'stk-abdullah_n1', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68457", "n": "Dr. A. Kawde", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-191\nالتحضير : ورقة تمر على الطلاب\nطريقة الشرح : شرحه ممتاز جداً والدكتور متمكن من المادة بشكل كبير، يشرح من سلايدات الكتاب وشرحه يعطيك الزبدة فحاول تركز معه\nالكويزات : كوزاته كانت سهلة جداً فأنتبه حاول تجيب فيها فل لن الآفرج راح يخسف فيك!\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جداً\nإضافات : الدكتور مصري حبيب واخلاقه عالية وجداً محترم ومتعاون، كان يلطف الجو بالكلاس وكنت كل كلاس اخرج وانا مبسوط من الشرح ومن اسلوبه الجميل\nولو باقي لي كورس كمستري آخر كان نزلته عنده. أنصح فيه جداً!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525198-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-kawde/68457/18", "user": "Abdullah_N1", "ts": 1598675302000, "tid": 68457, "pn": 18}}]}', 1598675302000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5938-chem101', 'stk-user5938', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 111 كمستري 101\nالتحضير :\n\nالتحضير كل يوم بورقة تمر على الطلاب وبعض الاحيان يحضر بالاسامي ويا ويلك لو تحضر خويك …\nمتشدد جدا جدا جدا في التحضير ، واذكر صفحة التحضير كانت مليانه بالسواد << يعني الدي انز …\n\nطريقة الشرح :\n\nيشرح من سلايدات وشرحه ممتاز اذا ركزت معاهـ …\nبس بعد تتعب لان المنهج طوويل وهو طول السمستر مستعجل …\n\nالكويزات :\n\nكويزاته مو سهله …\nلكن ادا تذاكر بتجيب علامه زينه وادا ما تذاكر لاتستغرب تاخد 1 او 2 او 3 من 10 …\n\nالمياجر:\n\nالمياجر سهله جدا\n\nالفاينلات :\n\nالفاينل اسهل من الميجر …\n\nالقريد النهائي:\n\nb\n\nالصوت:\n\nواضح جدا …\n\nإضافات :\n\nالدكتور جيد بس شديد جدا جدا …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p975337-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/33", "user": "user5938", "ts": 1327772629000, "tid": 68458, "pn": 33}}]}', 1327772629000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahsas_3ashq-chem101', 'stk-ahsas_3ashq', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 122 كمستري 101\nالتحضير :\n\nالتحضير كل يوم بورقة تمر على الطلاب وبين فترة وفترة يشيك على الاسماء\nوالي يحضر خويه يحط عند اسمه علامة اذا سواها ثاني dn\n\nطريقة الشرح :\n\nيشرح من سلايدات وشرحه كويس اذا ركزت معاهـ …\nبس بعد تتعب لان المنهج طوويل وهو طول السمستر مستعجل …\nوبعض المرات يسال سؤال ويستخدم برنامج لتحديد طالب عشوائي عشان يحل السؤال\n\nالكويزات :\n\nماعنده كويزات … الكويزات بيد مدرس الريستيشن\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nB\n\nالصوت:\n\nواضح جدا …\n\nإضافات :\n\nالدكتور جيد بس شديد جدا جدا … لو شاف احد يتكلم او يستخدم الجوال او يكتب بيحرجه\nيبغاك تنتبه معاه فقطط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1287224-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/38", "user": "ahsas_3ashq", "ts": 1384438956000, "tid": 68458, "pn": 38}}]}', 1384438956000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-chem101', 'stk-user10610', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 term 172\nالشرح : يستخدم السلايدات حقته ( سلايدات خاصه فيه جمييييييييلة جدا حتى الطلاب اللي ما يدرسون عنده يذاكرون منها ) زي اي دكتور يشرح سلايدات … بس تجيك مرتبة وصور وروابط والوان واشياء مريحة للعين. خلال الشرح ما يحب احد يقاطعه لكن بعد كل سلايد يوقف ويقول احد عنده سؤال ؟؟ وياخذ جميع الاسئلة ثم يكمل.\n\nالتحضير : ورقة تدور على كل القاعة واحيانا يشيك نهاية الكلاس على الاسماء. تتاخر اكثر من 10 دقايق او ربع ساعة ما بيدخلك.\n\nالصوت: وااضح جدا.\nالكوزات : كانت عند مدرس الريساتيشن بحكم ان الدكتور هو التشيرمان حق الكمستري. وكل اعمال السنة عند حق الريساتيشن.\n\nاضافات : الدكتور ما شاء الله علم وخبرة وفاااااهم جدا ومتمكن من الكمستري.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492728-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/46", "user": "user10610", "ts": 1526729687000, "tid": 68458, "pn": 46}}]}', 1526729687000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-chem101', 'stk-user11264', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 - Term 172\n\nالتحضير: ورقة تمر على الكلاس كله، أحيانًا يتأكد من الحاضرين آخر الحصة ويا ويلك يا سواد ليلك لو درى إن خويك محضرك :d\nنقطة ثانية إنه ما يخلي المتأخرين يدخلون بعد 10 دقايق أو 15 دقيقة، وأخيرًا ما يحب اللي يطلعون ويدخلون كثير وقت الكلاس عشان الإزعاج وصوت الباب. بالبداية كان يمشي هالشيء بس بالفترة الأخيرة صار ينزعج منه\nالشرح: من سلايداته، سلايدات مرتبة وممتازة بس لاحظت ترتيب المواضيع فيها يختلف عن الكتاب أحيانًا\nالكويزات: كان الريسايتيشن عند دكتور ثاني\nالصوت: واضح بس لو قعدت ورا بيجيك نوم\nإضافات: الدكتور فاهم ما شاء الله عليه مثل ما قالوا الشباب فوق، تعامله ممتاز مع الطلاب ويجاوب على كل الأسئلة (أشوف هالشيء فيه شوي سلبية لأن بعض الطلاب يكررون الأسئلة ويضيع الوقت)، يجلد اللي يشوفهم جالسين على الجوال كثير ويحرجهم 😆\nأنصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493227-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/47", "user": "user11264", "ts": 1527600816000, "tid": 68458, "pn": 47}}]}', 1527600816000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-badran11-chem101', 'stk-badran11', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101-172\n\nالتحضير : ورقة تمر على الكلاس , ايام ياخذ الورقة ويقرا الاسماء واللي محضر خويه يعطيه صفر بالحضور ( انسان يحفظ الوجوه والاسماء انتبه لا يحطك براسه ) ويطرد المتاخرين بعد 10 دقايق\nطريقة الشرح : يفتح سلايداته ويشرح منها بشكل عام حليله وتفهم منها لكن ايام تضيعك ولا تدري وش انت قاعد تقرا خصوصا اذا فهيت بالكلاس , يشرح بالانقلش والعربي شرحه ممتاز ويتفاعل مع الاسئلة لكن الشباب كانوا يسالون اسئله كثير وغبيه او مالها علاقة بالدرس فصار يسوي سكيب للي يسأل\nالكويزات : دكتور ثاني\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:ِِA\nالصوت: متوسط ايام يكون منخفض\nإضافات : الدكتور بشكل عام جيد بس انه حار شوي ما حصلته ولا مره بالاوفيس اور شكله مشغول لانه اتوقع صار رئيس القسم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1495080-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/48", "user": "badran11", "ts": 1530743525000, "tid": 68458, "pn": 48}}]}', 1530743525000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahadmh-chem101', 'stk-fahadmh', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68458", "n": "Dr. A Saadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-Term 221\n\nالتحضير : كان بداية اول اسبوع ينادي بالاسماء لكن بعدها صار التحضير بالبلاك بورد نهاية الكلاس بس دايم يحذر لحد يعطي الرمز لشخص غائب\n\nطريقة الشرح : الدكتور ماشاء الله عليه متمكن وسلايداته جدا ممتازة حتى صرت ارجع لها اذا في جزئية مافهمتها من الكتاب وطبعا الكورس ثقيل فا الدكتور يحاول يخلص وما بيرجع لنقطة ثانية. كان يسوي قبل المياجر بالريستيشن تجميع لاولدات شاملة للتشابتر ويجمع فيها الافكار المهمة ويحلها معنا.\n\nالكويزات : عن نفسي اشوفها سهلة الى متوسطة, مرن جدا باوقات الكويزات اذا كانت فترة ميدات ولا شي واغلبه كان يسوي بالتصويت متى يكون الكويز. اختبرنا 7 كويزات كان افرجها 6 من 10 بالبداية او 7 لكن بعدين سوا لنا كويزين يساعدنا فيها وكان افرجها عالي جدا فا انخسفنا من النورم شوي\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : اذا شفت سكشنه مفتوح لا تتردد روح الدكتور جدا ممتاز وتعامله طيب من افضل الدكاترة اللي درسوني.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536092-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-saadi/68458/50", "user": "FahadMH", "ts": 1672615600000, "tid": 68458, "pn": 50}}]}', 1672615600000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8053-chem101', 'stk-user8053', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سلآم عليكم …, ❤️\n\nكيمستري 101\nسيميستر 103\n\nالتحضير :\n\nورقة تمـر على الطلآب + بعض الايآم يحضر هو .\n\nطريقة الشرح :\n\nحلـوة ومن الاشخآص الي تفهم معهم من الكلآس ❤️ + يستخدم سلآيدآت والسبورة .\n\nالكويزات :\n\nمتوسطة + ركز على كويزآته القديمة\n\nالمياجر:\n\nكوومن\n\nالفاينلات :\n\nكوومن\n\nالقريد النهائي:\n\nB\n\nالصوت:\n\nوآضح بس فيه لكنة الهنـود .\n\nإضافات :\nجيـد جيـد مرة ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p935935-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/24", "user": "user8053", "ts": 1322081161000, "tid": 68459, "pn": 24}}]}', 1322081161000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-gamofrn-chem101', 'stk-gamofrn', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "[quote=“تقييم”]\n\nhttp://faculty.kfupm.edu.sa/CHEM/mnahid/images/Siddiqi.jpg\n\nد. محمد صديقي\nجدا طيب … ومتعاون مع الطﻻب\ncourse : chem 101\nterm 131\n\nبنود التقييم :\n\nالتحضير :ورقة تمر على الطﻻب … واذا شاف عدد الطﻻب قليل … يقوم ينادي بالأسامي … على شان يصيد المحضرين\nطريقة الشرح : شرحههه جييد … عنده سﻻديات …ممتازة جدا … لكن يبقى الكتاب النبمر ون … ويمديك تذاكر المادة من الكتاب والقليل جدا جدا من مساعدة الدكتور\nالكويزات : سبوعيا على تشابتر تقريبا … وو الكوزات متوسطة … الي ذاكر التشابتر … بيحل … وبالكوز يكون فيه سؤال وﻻ سؤالين فيهم ترك من 10 اسئلة … ومكونة من مسائل طبعا وو صح وخطأ واحيانا يحط لنا الخيارات … ومدة الكوز ( يعطيك وقت كافي للكوز وزيادة )\nالمياجر:common\nالفاينلات :common\nالقريد النهائي:c+ , b\nالصوت:مفهوم\nإضافات :\nالدكتور جيد … ومهتم بالطﻻب … وفي وسط اللكتشر يعطي الطﻻب اسئلة على الدرس\n\nوبتسمع كلمة بديهي كثير\nوو why it’s not clear\nهذا common sense", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1307030-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/29", "user": "GAMOFRN", "ts": 1387411573000, "tid": 68459, "pn": 29}}]}', 1387411573000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-chem101', 'stk-chelsea_17', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كيميستري 101 - ترم 123 ( صيف )\n\nالتحضير :\nورقه تمر عالطلاب ويا ويلك لو قفطك محضر خويك.\n\nطريقة الشرح :\nيشرح من سلايدات , بداية الترم كان ممتاز ويحل مسائل أما بعد أول 3 اسابيع بالصيف سار يمشي عالسلايدات سريع سريييع ولا يحل أي مسئلة وأحيانا ما كان يشرح بعض السلايدات ويقول ذاكروها بالبيت واللي ما يفهم شئ يجيني ( هالكلام كان بالصيف ).\n\nالكويزات :\nتقريبا كل اسبوع كويز ولأن بالصيف في كلاسين ريسيتيشن فكلاس كنا نختبر وكلاس محد يحضر ( نسيت ليش لكن أتوقع انه اتفاق غير معلن بين الطلاب والدكتور 😆)\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nD+\n\nالصوت:\nواضح\n\nإضافات :\nأحيانا الواحد ما وده يسأله لو ما فهم ممكن يتشمت فيك قدام الطلاب ويضحكهم عليك ( المشكله انه احيان يكون فعلا خفيف دم ويضحكون الطلاب من قلب 😁 )\n\nبالصيف ما أنصح بهالدكتور نهائيا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372385-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/30", "user": "Chelsea_17", "ts": 1401150027000, "tid": 68459, "pn": 30}}]}', 1401150027000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-oubaida-chem101', 'stk-oubaida', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nليكتشر CHEM101-173\n\nالتحضير :\nورقه تمر على الطلاب\n\nطريقة الشرح :\nسلايدات سريع بالتعاريف و مواضيع الحفظ\nيحل بعض المسائل على السبورة و يعطيها وقتها\nبشكل عام ممتاذ\n\nالكويزات :\nمن اسهل الدكاترة بالكويزات + يحذف كويز واحد فقط لا غير ( الافرج غالباُ عالي )\n\nالقريد النهائي :\nA\n\nالصوت :\nجيد جداً\n\nإضافات :\nالمادة سيلف استدي :muscle: الدكتور مجرد مساعد لا تعتمد عليه\nالاوفيس اور كان دائماً زحمة و رحت له مرتين و صراحة ما فهمت منه يمكن انا المشكلة 😕\nيحب المزح مع الطلاب و اوقات يحشر الطلاب\nبشكل عام الدكتور طيب جداً جداً\n\n( في دكاترة احسن منه ولاكن من الصعب تلحق على سكاشنهم لانها بتسكر بسرعة :exploding_head: )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498109-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/36", "user": "Oubaida", "ts": 1535199771000, "tid": 68459, "pn": 36}}, {"id": "stk-dr-f179305", "n": "Dr. Mohammed Abdalwadoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-173 LAB\n\nالتحضير : متعاون جداً\n\nطريقة الشرح : بيشرح بشكل مفصل و بالعربي و بيحاول يكون سريع\n\nالكويزات : بيحدد لك 3 او 4 اسئلة بتحلها قبل التجربة خلال 10د بتكون محضرها من اول\n\nالفاينلات : لأول مرة كان كومن\n\nالقريد النهائي : A+\n\nالصوت : واضح جداً\n\nإضافات :\nالدكتور جداً محترم و متعاون وعادل بين جميع الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498111-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-abdalwadoud/179305/2", "user": "Oubaida", "ts": 1535200465000, "tid": 179305, "pn": 2}}]}', 1535199771000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-chem101', 'stk-21m', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : محمد صديقي\nالمادة: chem101\nالفصل الدراسي:201 اونلاين\n\nالتحضير : من البلاك بورد والخصم يبدا عنده من الغياب الثالث\nطريقة الشرح : يفتح سلايداته ويشرح قدر الامكان يحاول يوصل الفكرة يتعب صراحة ويتعاون مره في قروب الواتس ويحاول يساعد ويسجل المحاضرات وفي كلاسات الريسايتيشن يحل اسئلة اولد اقزامز ما يقصر صراحة\nالكويزات : في البداية كاتت بلاك بورد والافرج مرتفع بعدين غيرها وصارت رتن ونزل الافرج بالقدر البسيط\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: جداً واضح\nإضافات : الدكتور طيب و واخلاق صراحة ويا ما اجل كويزاته عشان الضغط الي حاصل مع الاونلاين و يرفع واجبات بشكل اسبوعي من\nالاولد اقزامز واشوف انها تساعد على انك تتدرب بعد ماتخلص مذاكرة الشابتر\nفي النهاية كل الدكاترة تقريبا نفس المستوى فلا تحرص على أحد دور الي يناسب جدولك وبس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527425-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/39", "user": "21M", "ts": 1609415407000, "tid": 68459, "pn": 39}}]}', 1609415407000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_aldoseri-chem101', 'stk-mohammed_aldoseri', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68459", "n": "د. محمد صديقي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Term 211 - Lec\n\nالتحضير :\nالتحضير كان عن طريق البلاكبورد وللتحضير باسورد يتغير كل كلاس.\n\nطريقة الشرح :\nيشرح من سلايدات وشرحه جيد جدا الى ممتاز في بعض المواضيع.\n\nالكويزات :\nمتوسطة وفي منها خيارات , صح وخطأ , مسائل. وكانت عالبلاكبورد وآخر كويز كان ورقي.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح ولهجته هندية ولكن مفهومة\n\nإضافات :\nتهمه مصلحة الطالب كثير ودايم يقطع الشرح وينصحنا عن أمور كثيرة وكان أهم شي عنده (الصدق) , نصايحه وكلامه عن مواضيع جانبية كان مزعج بعض الطلاب ويشوفونه يشتت والبعض كان عاجبهم (بريك من الدرس) عشان يقدرون يستوعبون كمية المعلومات الدسمة في الكورس. ولا تعتمد على الدكتور من ناحية حل مسائل وأولدات لأنه يركز عالكونسبت أكثر. ما أقول أنه أفضل دكتور في القسم ولكن لازم يكون من خياراتك الأولى .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533455-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68459/40", "user": "Mohammed_Aldoseri", "ts": 1642131510000, "tid": 68459, "pn": 40}}]}', 1642131510000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-chem101', 'stk-student_nz', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68477", "n": "Dr. Abdallah Abulkibash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كمستري 101 ترم 092\n\nالتحضير :\nيحظر بالارقام بعض الايام في النهاية وبعض الاحيان في النهاية\nيقبل المتاخرين\n\nطريقة الشرح :\nبور بوينت وبعض الاحيان على اللوح\nوالامانة البور بوينت يقعد يقرا منوو\nيعني لما يشرح لى اللوح الصراحة احسن من البوبوينت\n\nالكويزات :\nمتوسطه الى صعبه\nوتكون قديمة من ايام مدري كم وخشبه\nحتى كان في اسئلة مهي مقررة علينا 🙂\n\nالمياجر:\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي: اعطيه c+\n\nالصوت:\nواضح\n\nإضافات :\n\nالدكتووور طيب جدا\nوحبووب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p677034-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-abulkibash/68477/19", "user": "student_NZ", "ts": 1281158097000, "tid": 68477, "pn": 19}}]}', 1281158097000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5771-chem101', 'stk-user5771', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كمستري101 سمستر 102\n\nالدكتور خلاصة الكلام افضل الموجود في الشرح والاخلاق\n\nطبعا هو مابيده الا درجات الحظور\n\nطبعا الكلاس ملل لان الماده ممله لكن سهله\n\nاياني واياك تغلط غلطة عمرك وتخلي احد يحظرك\n\nلان الدكتور اهم شيء عنده التحظير ويشيك على الاسماء آخر المحاظره واذا احد حظرك يخصم عليك مالايقل عن 20 درجه\n\nوفيه شباب في سمسترات قديمه خصم 40 وسمعت انه قد اعطا دي ان", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852212-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/20", "user": "user5771", "ts": 1307961286000, "tid": 68483, "pn": 20}}, {"id": "stk-dr-f77906", "n": "Dr. Basheer Chanbasha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "وها نحن نعود بعد سمستر جميل كيمستري 101 لاب\n\nدكتور مررررررررررررررررررررره طيب في اللاب\n\nمن نظرتي له انا اشوف ان شرحه جدا جدا سيء لكن جدا كويس في اللاب ومتساهل في كل شي\n\nالطلاب يدفهم دف في الدرجات ويخليهم يغشون في الكوزات ويساعدهم\n\nبس في النهايه درجتك انسا تكون فوق 80\n\nطبعا اللاب افرج من 75\n\nاعلى واحد في لابنا جاب 79.8 واقل واحد جاب اعتقد 70\n\nيعني لا تغيب واظمن لك انك تجيب الافرج", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852220-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/basheer-chanbasha/77906/18", "user": "user5771", "ts": 1307961654000, "tid": 77906, "pn": 18}}]}', 1307961286000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8521-chem101', 'stk-user8521', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101-111\n\nالتحضير : شديد جدا , ورقة تمر وتكتب عليها اسمك بالعربي واحيانا يحضر بنفسه (سواها 5 مرات السمستر الماضي) واذا قفط واحد محضر يخصم منه 20 نقطة (=5 درجات) ويسجل ليت احيانا قبل ما يمر 5 دقايق , ويغيب بعد ربع ساعة واحيانا قبل .\n\nطريقة الشرح : مع انه يشرح من سلايدات سقيمة ,الا ان شرحه ممتاز .\n\nالكويزات :من مدرس الريسايتيشن مو منه\n\nالمياجر:كومن\nالفاينلات :كومن\n\nالقريد النهائي:a\n\nالصوت: واضح والاكسنت ممتازة , طبعا الدكتور ما يتكلم ولا كلمة عربية بالكلاس غير : (السلام عليكم , كيف الحال شباب؟ , واحيانا يضيف عليها كيفكم مع البرد؟) 🙂\n\nإضافات :ما اقدر اقيم الدكتور من ناحية الاوفيس اور وتعاونه مع الطلاب لان احتكاكي معه انا ومعظم الطلاب شبه معدوم خارج الكلاس بحكم ان الاوفيس اور له كانت الساعة 8 يعني بعد الكلاس على طول لان عنده دوام بكلية المجتمع فما رح يجيه احد بهالوقت وايضا اي مشكلة تصير لك من ناحية الكويزات والكلاس وورك والاون لاين هوم وورك وغيرها تراجع فيها وزير اللي درسنا ريسايتيشن .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971875-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/24", "user": "user8521", "ts": 1327190161000, "tid": 68483, "pn": 24}}]}', 1327190161000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iahmed015-chem101', 'stk-iahmed015', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101 - semester 112\nالتحضير : ورقة تمر تكتب فيها اسمك ، 3-4 دقائق ليت …\nطريقة الشرح : فاشلة جداً ، سلايدات الكتاب و يقعد يشرح … ماعجبني شرحه ابداً + انّي اكره المادة + الكلاس الساعة 7 …\nالكويزات : لـ مدرس الريسايتيشن ،\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: D\nالصوت: كويس ،\nإضافات : هو عميد كلية المجتمع، فـ يجي يعطي كلاسه و ساعة بعدها ويمشي ، انسان مره معقد مايلعب مع التأخير ، و شرحه فاشل ماكنت افهم معاه شي\n\n( ما انصح فيه، وانا ماجربت غيره بالكيمياء والحمدلله افتكينا من هالمادة الغثيثة - 101 )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044858-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/27", "user": "iAhmed015", "ts": 1338020418000, "tid": 68483, "pn": 27}}, {"id": "stk-dr-f118608", "n": "أ. ساهيد بوبولا", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 - term 112\n\nالتحضير : ينآدي بِ الأسماء بِ كُل لآب …\nطريقة الشرح : فاشله ، لهجته سيئة و 3/4 الكلام ماتفهمه 🙂 !\nالكويزات : كويز بداية كل لاب ، عن التجربة اللي راح نبدأها ، نفس اللي يجيك يجي للسكاشن الباقية + الأسئلة تجي من كتاب اللآب.\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: D+\nالصوت: اكسنت خايس وصوت واطي\nإضافات :\n* اعلى واحد بالدرجات كان 78 و اقل واحد 74 ، بالنهاية كلها تتأفرج ، والله أعلم !\n* اذا ماكنت اول لاب عنده وتعرف واحد باللاب اللي قبل ، نزّل عنده بس أعتمد على نفسك باللاب و خذ الاسئلة من اللي قبلك.\n* اذا معآك اخويآ باللاب بيخفف عليك المصيبة ، ممكن تنزّل عنده على أساس تساعدوا بعض.\n\nوبالتوفيق ،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1079900-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118608/10", "user": "iAhmed015", "ts": 1345184713000, "tid": 118608, "pn": 10}}]}', 1338020418000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-chem101', 'stk-magbool', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 -term 131\n\nبنود التقييم :\n\nالتحضير :\nورقة تمر ، شديد جدا في التحضير ، اللي يتأخر أكثر من 5 دقايق ليت من غير اي تفاهم.\nطريقة الشرح :\nممتازة، الغالب يشرح ع السبورة ويكون مشغل السلايدات ويشرح منها بعض الصور ويعلق على بعض الأشياء.\nالكويزات :\nعند درس الرسايتيشن ، سهلة جدا.\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\n-ميزته إنه نشيط في الكلاس ، يعني تجي الساعة 7 نعسان ، يفوقك.\n-يبدأ الكلاس (بسم الله والصلاة والسلام على رسول الله ) ثم بعدها ما يتكلم كلمة عربي لنهاية الكلاس.\n- يستقبل الأسئلة بصدر رحب جدا ، وماعنده مشكلة يضيع وقت عشان يشرح سؤال واحد ، وبرضو ماعنده مشكلة يرجع يعيد النقطة أكثر من مرة.\n-إذا فيه قانون أو نظرية فإنه يشرحلك كيف جاءت أو كيف أتوصل لها مكتشفها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1290126-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/34", "user": "magbool", "ts": 1384854155000, "tid": 68483, "pn": 34}}]}', 1384854155000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem101', 'stk-user9305', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فصل 131 كيمياء 101\n\nالدكتور شرريييح ويجيك كل صبح وهو متحمس وشعلة من النشاط ماشاء الله تبارك الله… يشرح من سلايدات الكتاب ويكتب على السبورة نوت باللي يعتقد هو انه مهم… يتجاوب مع اي سؤال من الطلاب خلال المحاضرة ولو لاحظته هو يشرح راح تلقى انه يستمتع بالمادة بشكل واضح وما يتكلم اي كلمة عرية داخل الكلاس… في الساعة المكتبية حبيييييييب ومتعاون لأبعد حد وللأسف الشديد ما رحت لمه في المكتب الا مرة وحدة لأن ساعته المكتبية الساعة 8 وانا كان عندي رياضيات وقتها… ولو اني داري من قبل ان وقت ساعته المكتبية الساعة 8 كان اجلت الرياضيات واستفدت منه لأقصى حد في ساعاته المكتبية لكن قدر الله وما شاء فعل\n\nلو عطيته a+او اقل ظلمته عشان كذا ماراح اعطيه اي تقييم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1309813-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/36", "user": "user9305", "ts": 1388057936000, "tid": 68483, "pn": 36}}]}', 1388057936000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-chem101', 'stk-user8581', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f118602", "n": "د. شكيل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101 - recitation - term 141\nهو غالبا يكون مسؤول عن الريساتيشن لسشكن العرفج …\n\nالتحضير :\nما فيه و اذا تبي تحضر مع سكشن ثاني ماعنده مشكلة …\n\nطريقة الشرح :\nمن السلايدات الي فيها اسئلة ويحلها مع الطلاب ع السبورة ويتجاوب مع اسئلة الطلاب ومتعاون بشكل كبير\n\nالكويزات :\nغالبا سهلة و تكون خيارات لو ذاكرت من الكتاب الشيك بوينت و اسئلة الهومورك راح تجيب فل مارك هو يحذف اسوء كويز في نهاية السمستر والكويزات تكون اخر نص ساعة\n\nالمياجر& الفاينلات : كومون\nالقريد النهائي: b\nالصوت: واضح والاكسنت هندي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420447-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118602/5", "user": "user8581", "ts": 1421634312000, "tid": 118602, "pn": 5}}, {"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101 - lec - term 141\n\nالتحضير :\nشديد …كان في البداية يسمح بالتأخير خمس دقايق او اقل لكن لأن بعض الطلاب مصخوها قام يعطيك ليت لو تأخرت دقيقة او دقيقتين … اذا انت نومك ثقيل وماتقدر على دوام الساعة 7 نصيحة ابعد عنه لأنك راح تتعب + هو يحذف غياب واحد في نهاية السمستر\nوانتبه تحضر احد بدالك لأن في البداية راح يخصم عليك 20 او 40 بوينت مب متأكد المرة الثانية راح يعتبرها حالة غش … + مايهتم بالي قاعدين على الجوال او نايمين\n\nطريقة الشرح :\nمن سلايدات الكتاب وفيها الشيك بوينت وكل شي فيعني حاول تركز معاه لأنه يحل مع الطلاب هذي الاسئلة واذا مافهمت اسأله وهو راح يشرح لك\nيتقبل اسئلة الطلاب … شرحه ممتاز ويبين الأخطاء الي غالبا الطلاب يسونها\n… ما شاء الله عليه دايما يجي الصبح هو متحمس ويقعد يشرح وهالشي ممتاز لكن مع نهاية السمستر تحس بالملل وبس تبيه يوقف شرح\n\nالكويزات :\nمدرس الرياتيشن هو المسؤول عنها\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=79068\n\nالمياجر & الفاينلات : كومون\nالقريد النهائي: كأخلاق وتعاون a+ و شرح b+\nالصوت: واضح والاكسنت ممتاز\n\nإضافات :\nركز معاه في الكلاس وحاول تراجع بشكل بسيط وتحل الشيك بوينت وراح تاخذ قريد عالي في الكيمستري + الكتاب يمكن يغنيك عن الدكتور لكن تركيزك في الكلاس راح يختصر الوقت وتوفر جهد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420451-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/41", "user": "user8581", "ts": 1421635663000, "tid": 68483, "pn": 41}}]}', 1421634312000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-chem101', 'stk-abdelaziz', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Term 142\n\nالتحضير :\nأول ما يدخل يمشي ورقة على كل الطلاب وتكتب اسمك\nنهاية السمستر صار يحضر بالارقام\n\nطريقة الشرح :\nيشرح من السلايدات ويستخدم السبورة\nشرحه بطططططل ❤️ يمكن هو الأفضل\nغالباً يخلي الطلاب يحلون إكزامبل في اللكتشر عشان كذا لازم تجيب الحاسبة معاك\nدايما يردد ويقول: \" I want you in our note, to solve … \" 😆\n\nالكويزات :\nيحطها مدرس الريسايتيشن - سهله وبسيطة .\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي: +A\n\nالصوت: واضح والاكسنت مفهوم\n\nإضافات :\nشرحه كله بالانجليزي يعني مستحيل ينطق كلمة بالعربي\nاذا لقيته سجل عنده وانت مغمممممض 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432214-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/46", "user": "Abdelaziz", "ts": 1446740293000, "tid": 68483, "pn": 46}}]}', 1446740293000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-chem101', 'stk-aomab', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه CHEM101 ترم 181\nالتحضير : ورقة تمرر على القاعة( طبعا المحاضرة تجمع فيها كل سكاشن الدكتور)\nطريقة الشرح :شرح ولا اروع (الاختبار ما يخرج عن شرحه)\nالكويزات : متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: يستحق A+\nالصوت: وااااااضححححح جدا\nإضافات : عشان اكون صريح انك تجيب قريد وانت تدرس عنده شوي صعب لان الافرج يكون عالي في الكوزات(الكوزات في الكيمياء تفرق لانها تساوي 15% ما يعادل ميجر كامل 🤪) فيضطر ينقص الطلاب كلهم 🤪(انا عن نفسي نقصت 6% بسبب الافرج)(6% ما يعادل قريد كامل)\nفنصيحتي للي يبي قريد في ذي المادة ينزل عند مدرس مو كويس ويحضر محاضرات العرفج كمستمع ( اعرف ناس سووها وخرجوا بقريد عالي وهم يضحكوا)\nطبعا تقدر تجيب قريد وانت منزل عنده بس لازم تبدع في المياجر والفاينل (اما اذا كنت من النوع اللي على الافرج دور على دكتور افرجه نازل في اللكتشر وللاب )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504072-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/49", "user": "AOMAB", "ts": 1545768858000, "tid": 68483, "pn": 49}}]}', 1545768858000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-chem101', 'stk-mohammed_mag', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\nعبدالرحمن العرفج\n\nالمادة:\nCHEM 101\n\nالفصل الدراسي:\n201 ( عن بعد , أون لاين )\n\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :\nأول اسبوعين كان توه جديد على التيمز ف ماكان يحضر\nبعدها صار يحضر على اخر المحاضره عن طريق موقع\n\nطريقة الشرح :\nجدا جدا ممتاز , محاضراته مسجله على اليوتيوب وهو يسجلها في التيمز , ما اتوقع في افضل منه , يشرح الماده يخليك تحبها فوق انها ماده جدا ثقيله\n\nالكويزات :\n- لكل تشابتر تقريبا عطانا كويز , \" حول 10 كويزات \"\n- ماذكر قد اختبرنا في النهار او وقت الريسايتيشن , دائما يكنسل الريسايتيشن ويخلي الاختبار الليل حول 10 , سواء الخميس او السبت ماعنده مشكله .\n\nالميد تيرم:\nصعب والوقت قليل\n\nالفاينلات :\nكومن\n\nالصوت:\nواضح جدا وممتاز\n\nالقريد النهائي:\nC+\n\nإضافات :\nدام محاضراته اغلبها مسجله على اليوتيوب , وأفرج سكشنه جدا مرتفع وأوقات اختباراته متأخره بعض الاحيان , ما اشوف انه مره مهم تسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527525-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/52", "user": "Mohammed_Mag", "ts": 1609691744000, "tid": 68483, "pn": 52}}, {"id": "stk-dr-f176827", "n": "Dr. Muhammad Sharif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\nمحمد زار\n\nالمادة:\nCHEM 101 - LAB\n\nالفصل الدراسي:\n201 ( عن بعد , أون لاين )\n\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :\nجدا متساهل , بعض الاحيان يحضر وبعض الاحيان لا , عن طريق الموقع\n\nطريقة الشرح :\nمن أول كلاس , مافهمت منه ولا شيء للأسف\n\nالكويزات :\nيوجد تاسكات اسبوعيه زي كل الدكاتره , متساهل من ناحيه التصحيح ويتفهمك\n\nالمياجر:\nلا يوجد من ناحيه اللاب مياجر , لكن يوجد بس اختبار بسيط بدايه الكورس حق سلامه ولازم تعديه .\n\nالفاينلات :\nصعب جدا للأسف.\n\nالصوت:\nلهجه غير واضحه جدا\n\nالقريد النهائي:\nC+\n\nإضافات :\nالدكتور جدا متساعد وقلبه ابيض ويتساهل مع طلابه من ناحيه الحضور والتاسكات والتصحيح , لكن اذا انت تبي تفهم اللاب فعلا وماده تخصصك , لا تنزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527529-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-sharif/176827/7", "user": "Mohammed_Mag", "ts": 1609693886000, "tid": 176827, "pn": 7}}]}', 1609691744000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-housam-ae-chem101', 'stk-housam-ae', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم نبدأ اول مشاركة لنا…\n\nالدكتور : ABDULRAHMAN AL-ARFAJ\nترم: TERM 201 ONLINE\nالمادة: CHEM101 General Chemistry I\nالنوع: LECTURE ONLY without Recitation\n\nالقريد النهائي اخر حاجة :bouquet:\n\nملاحظة هامة: التقييم هذا ينطبق على الاونلاين فقط وقد يتغير حال الدكتور في الحضوري! استهدف فيه طلاب ترم 202\n\nالتحضير: الدكتور كان يحضر باستخدام الميكروسوف فورم عن طريق رابط يرسله في التشات ويفتحه لمدة دقيقة او تزيد قليلا ويقفله بعدين - بداية الترم كان يرسل الرابط في نص المحاضرة ماله وقت محدد بس بعدين طفش وصار نهاية كل محاضرة بعد ما يخلص شرح يرسل الرابط والكل يحضر (صاروا الناس الي ما يبغو يحضروا معاه يدخلو اخر 5 دقايق ويحضروا ويمشوا)\nونهاية الترم قالنا رح يتغاضى عن 4 او 5 غيابات ناسي بالزبط! وما اعطى بونص للي عنده صفر غيابات\n\nطريقة الشرح: المحاضرات كانت عن طريق مايكروسوفت تيمز وكان يستخدم سلايدات الكتاب (زي اغلب الدكاترة اتوقع) واشوفها ممتازة للفهم ويستخدم القلم للشرح واشوف شرحه جدا جدا جدا جدا رهيييييب للكونسيبت ومسائل الكتاب وميزته يعطيك كل الي تحتاجه وما يزيد عليك او ينقص ابدا! يعني شرحه كافي ووافي وخصوصا مع القلم 🤣. حتى مرة من المرات قلمه مدري خرب او شحنه خلص كل الطلاب قالو ما فهمنا (في قروب الواتس) 😅 .\nوالدكتور ترا كبير وخبرة طويلة في التدريس فاعرف انه قد شرح الكورس ذا مرات عديدة ومتمكن منه! فاطمئن واعلم انه بيشرح لك باسهل الطرق لتبسيط وتسهيل المعلومة\nحاول حاول تركز معاه لنهاية المحاضرة واهم شيء تكو عندك نوته من اول يوم تدون فبها الملاحظات مع الدكتور! هذي النقطه في بالغ الاهمية ولاحظت الفرق معي\n\nالصوت: واضح ومسموع\n\nاوفيس اور: بعد كل محاضرة مباشرة ووغالبا بيكون قبلك ناس كثير (كنا 3 سكاشن ندرس مع بعض) وما يجلس للاوفيس اور للنهاية اذا ما في احد عنده سؤال! شيء مزعج\nلانه صارلي مرتين اني اروح عشان اصلي الظهر عبال ما يخلصوا الناس اسئلة والاقي انه تم ازالتي من السيشن لانه نادى على اسمي فلان عند سؤال ولمن ما رديت ازالني 👎.\nولكن مجملا كان متعاون معانا في الاجابة عن اسئلتنا والخ. كان ممتاز والكورس اصلا الماتيريال حقه سهل بس يعيبه طول المنهج\n\nالكوزات: ما ادري… كوزاتي كانت عند دكتور الريسيتيشن… بس يقولو كوزاته متوسطه وحلوة\n\nالمياجر + الفاينلات: كومون!\n\nالواجبات: بداية الترم ينزل الواجبات كلها باسئلتها في البلاكبورد وتقدر تتطلع عليها وبعدين (كان عنده قروب واتس مع الطلاب و طبعا هو بس يرسل فيه) يرسل في القروب انه نزل واجب التشابتر الفلاني ودائما يعطيك عدد محاولات لانهائية والوقت مفتوح فالكل يجيب فل في كل الواجبات بدون استثناء معاه بغض النظر عن الصعوبة! مستواها كان وسط.\n\nاضافات متنوعة:\n\nالناس دايما تقول اصلا المادة سلف ستدي وما رح يفرق الدكتور وانا لا اتفق بتاتا! لانه اسهل عليك تفهم في المحاضرة ولا انك تروح تدور شرح في اليوتيوب (Organic Chemistry Tutor) وتجلس بعد المحاضرة اضغاف وقت المحاضرة عشان تفهم الدرس. ولا انكر انه بعض الافكار صعب تفهمها في الدرس والدكتور ما بيضيع وقت المحاضرة يحاول يفهمك هيا.\n\nمحترم واخلاقه ممتازة ويتفهم جدا انه احيانا الطلاب يكونو متنرفزين بعد الاختبارات ونتائجهم فيها - صارلي موقف معاه وبعد ما اعتذرت له شفت قد ايش قلبه طيب وما يشيل اي حاجه فقلبه على الطلاب\n\nمتجاوب في الايميلات - يرد بحد اقصى 3 ايام (هذا اذا استفسارك له رد ويعرف جوابه)\n\nيخصص كلاس مراجه قبل الميجر - لو كنت اصلا مذاكر ما بتستفيد كثير والكويس انه ما يحضر في ذولا الكلاسات الي هو يخصصها للمراجعة\n\nالعرفج كان الCoordinator مع ISAB في ترم 201\n\nشيك على قناه Organic Chemistry Tutor ممتازة جدا كمصدر مساند\n\nلا تفوت هلب سيشن مع HAMZA ALABDULGHANI رهيييييييييييب جدا\n\nالكورس طوييييييييييييل جدا يا عزيزي القارئ لذلك لا تستغرب من سرعة الدكتور في الشرح لانه لازم يمشي بهذه السرعة واالا ما رح يلحق يخلص! وهذا ليس ذنب للدكتور!\n\nالعرفج صارت كلاساته في ترم 201 نظام MW فتجيني الكثير من الاسئلة هل تسوى اضحي واخذ MW بس عشان الدكتور والمادة ما تعتمد عليه بشكل اساسي… جوابي دائما نعم وألف نعم - صحيح انك بتفصل بعد نص المحاضرة من كثرة المعلومات ولكن لا تنسى انه المحاضرة مسجلة وتقدر ترجعلها وقت المذاكرة\n\nالقريد النهائي: A+ بكل جدارة وبكل ما يعنيه القريد من معنى!\n\nفي الختام اتنمى اني قد وفقت في تقييم الدكتور… واعلم يا عزيزي القارئ ان هذا التقييم من وجهة نظري انا الشخصية وقد تكون لأناس اخرين آراءهم والتي - من الطبيبي - قد تكون مختلفة\n\nب التوفيق لكم جميعا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527819-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/53", "user": "Housam-AE", "ts": 1610456681000, "tid": 68483, "pn": 53}}]}', 1610456681000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k.q-chem101', 'stk-k.q', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68483", "n": "Dr. Abdulrahman Al-Arfaj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Term 201\n\nالتحضير: اخر المحاضرة عن طريق Microsoft form.\n\nطريقة الشرح: شرحه عادي جدًّا بالنسبة لي. يشرح من الكتاب ويحل كم سؤال فالمحاضرة.\n\nالكويزات: متوسطة الصعوبة ولازم تلقى كم سؤال من الهومووركات كوبي بيست. نوعها مختلف من كوز لكوز مرات خيارات ومرات فاينال انسر.\n\nالواجبات: كل تشابتر له واجب خيارات وهو نفسه حق كل ترم تقريبا.\n\nالمياجر: كومن.\n\nالفاينالز: كومن.\n\nالقريد النهائي: B.\n\nالصوت: خافت نوعا ما.\n\nاضافات: الدكتور اخلاق بس فيه عنده اشكالية واجهتها معه اللي هي اوقات الكوزات كان يحطها الخميس او السبت الساعة ٩ او ١٠ الليل. ويكنسل الريسايتيشن اذا فيه كوز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529535-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-arfaj/68483/55", "user": "K.Q", "ts": 1618772005000, "tid": 68483, "pn": 55}}]}', 1618772005000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-chem101', 'stk-ad0rs', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68485", "n": "Dr. Hassan Badawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 lec - 122\nالتحضير :\nكل كلاس ورقة تمر عالقاعة>>>3 سكاشن\nطريقة الشرح :\nسيئة وفي اشياء دايما يغلط فيها\nاذا سألت عن نقطة معينة يقاطعك قبل لا تخلص سؤالك ويشرح حاجة بعييدة\nواذا جبت له سؤال صعب من الاولد اقزامز يقلك هذا السؤال لا تضيع وقتك فيه اذا جاك في الاختبار حل غيره وما يشرحه لك\nواذا جبت له اسئلة فيها حسابات يقلك انا الاسئلة ذي ما احلها\nالكويزات :\nسهلة\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nD\nالصوت:\nإضافات :\nالدكتور محترم واخلاق ومتعاون ومتساعد\nالـ DN من 9 غيابات وفي طلاب وصلوا 15 غياب وما نزلهم DN\nلكنه لا يفقه شي في الكيمياء\nاكاد لا اصدق انه دكتور\nانا بالنسبة لي شايف ان الكمستري اكثر مادة يحتاج لها دكتور\nاذا انت لو شوي بس ضعيف في الكمستري ابدا ابدا ابدا لا تنزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1233367-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hassan-badawi/68485/30", "user": "ad0rs", "ts": 1370779894000, "tid": 68485, "pn": 30}}]}', 1370779894000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-super_prince-chem101', 'stk-super_prince', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا منزل عندو كيمستري 101 الترم هدا\n\nالتحضير :\nيحضر دايما آخر الكلاس و ما عندو ليت و اوقات تهبق معاه ما يحضر بس نادرا .\n\nطريقة الشرح :\nشرحو جيد و يعتمد على السلايدات يعني اذا قعدت مركز معاه في الكلاس راح تفهم كل شي تقريبا و دايما يسأل الطلاب اذا كانو فاهمين . يخلينا نكتب نوتات مهمه كل فتره و فتره .\n\nالكويزات :\nكويزاتو سهله الى متوسطه و يميزها حاجتين انو في درجتين في الكويز زياده واحده اذا حليت الهوم وورك و التانيه اذا حليت كويز الويب سي تي طبعا ما يهمو ان كان صح او غلط اهم شي تحلو . الكويز يكون في آخر الريسايتيشن يعني لو انت مانت جاي مذاكر حيعطيك مسائل و يشرحلك قبل الكويز فحتجيب درجه حلوه .\n\nالمياجر: متوسطه\n\nالفاينلات : بآآآقي\n\nالقريد النهائي: A+\n\nالصوت :\nصوتو واضح و لهجتو مفهومه جدا .\n\nإضافات :\nمدرس ممتاز جدا انصح بيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p514601-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/13", "user": "Super_Prince", "ts": 1262468711000, "tid": 68486, "pn": 13}}]}', 1262468711000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3125-chem101', 'stk-user3125', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كلمة حق لكل الأخوة … اللي كانوا يذموا في الدكتور\n\nمع احترامي الشديد الا ان الدكتور برأيي من أفضل الدكاترة اللي مريت عليهم\n\nاخذت معاه chem 101 في صيف 083\n\nاركز على نقطة رائعة تناسبني كثيرا مدري عن غيري\n\nيتميز بأنه في وسط الكلاس يعطي الطلاب مسألة ويخليهم يحلوه طبعا ماعليها شيء لكن من تجربة هذه من أروع الطرق في التدريس بحيث ترسخ المعلومة في نفس وقت اللكشر\nايام الأوريا اخذت ماث 001 مع حسام شرقاوي وكان مستخدم نفس الاسلوب اسئلة في الكلاس تركز على كامل المحاضرة وللأمانة هذول الدكتورين (ايساب و شرقاوي) أخذت معهم اعلى قريد في حياتي الجامعية 🙂\n\nحاول انك تتابع معاه في الهوموورك اللي يحطها في الويب سي تي حيث انها شاملة لأغلب تريكات الكورس 🙂\n\nالتحضير : كل كلاس بورقة تمر على الطلاب في اللكشر طبعا اذا معاه في الريستشن التحضير بالمناداة على الاسم\n\nطريقة الشرح : مذكورة في بداية الرد كذلك اضيف شرحه بالسلايدات ويحاول بأقصى ماعنده ايصال المعلومة لك\n\nالكويزات : برأيي مناسبة للكورس غالبا يعطيك الهوموورك والأسئلة غالبا شبيهة بالهوموورك نصيحتي اجمع اوراق الكويزات وراجعها قبل الميجر - مدري اذا كان بسبب انه في الصيف كان هوا الكوردنيتر فالاسئلة مشابهة …\n\nالمياجر: كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح وممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p514656-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/14", "user": "user3125", "ts": 1262473918000, "tid": 68486, "pn": 14}}]}', 1262473918000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-equal-chem101', 'stk-equal', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور هذا اخلاق يا جماعة … ما اعرفه ولا يعرفني لكن كل ما يشوفني يسلم علي واسلم عليه 🙂 فيه طيبه عجيبه هالدكتور … الكوردنيتور للكيمياء 101 … تعامل الويب سي تي معاه سريع سريع … وهذه لاحظتها من طلابه … درجات المياجر والفاينلز تكون جاهزة عليه في حدود ساعتين !! من ناحية شرح … فاعتقد انه اكثر من جيد … بالاضافة الى ان الكورس يعتمد على مجهودك الشخصي اكثر من المدرس …\n\nبالنسبة للي يسأل عن الكورس … راجع القسم الاكاديمي فيه مواضيع كثيرة راح تفيدك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p645388-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/25", "user": "equal", "ts": 1277660800000, "tid": 68486, "pn": 25}}, {"id": "stk-dr-f68487", "n": "د. عبدالمطلب جابر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير: ورقة تمر على الجميع … لا يحاسب على التأخير وكثير من الطلاب يأتون متأخرين ويتنرفز من هذه المسألة لكنه يمسك اعصابه.\n\nطريقة الشرح : ممتازة وتفهم معاه اذا كنت مركز … ما يحل مسائل ابدا ( حتى في الريستيشن ) … يركز على الفهم واذا تابعت معاه بتستفيد ان شاء الله. باختصار … لا اعتقد ان هناك افضل منه من ناحية الشرح وتوصيل المفاهيم. طريقة شرحه تعتمد على الاسلوب القصصي … \" هذا الموضوع له story … 😆 \" والله انه طيب هالدكتور 🙂 ويعطي استراحة دقيقة الى ثلاث دقائق في نص الليكشتر بعض الاحيان اذا شاف الطلاب منتهين.\n\nالكويزات : 7 طوال الترم ولا يعطيك كوزات وقت المياجر … كويزاته ممتازة وتميل الى الصعوبة … بمثابة الاعداد للميجر … ويشرح بعض الافكار قبل الكويز … يأخذ افضل ستة كويزات.\n\nالقريد النهائي : A\n\nالصوت : واضح جدا ويعطيك كم من نكته بين فترة واخرى …\n\nإضافات : بطبيعة الحال … شرح السلايدات روتيني نوعا ما وقد يتملل منه الواحد … لكنه يشدك الى بعض المواضيع باسلوبه …\n\nانتبهو يا اخوان انكم تقللو من احترام الاستاذ … واحد من الشباب الله يهديه قريدر وجالس يصحح في وقت الحصة … الدكتور فلتت اعصابه عليه لدرجة انه قام يعتذر للطلاب بعد اللي حصل ! والطلاب اللي يتأخرون دائما يحطهم في باله ويعطيهم كم من كلمتين … الشيء الثاني اللي يرفع الضغط صراحة … بعض الشباب في نص الشرح يقومون ويطلعون ولا احم ولا دستور !! والدكتور يناديه وين يا فلان ؟ ما فيه احترام ما فيه شيء … لكنه يخليه يطلع بالاخير … انا اشوف هذي قلة حياء صراحة … والطيب المفروض يقابل بالطيب …\n\nيحذف غياب عن كل طالب … طالب واحد اخذ dn ، اعتقد انه ايضا يحذف الغيابات اللي في نفس ميجر يوم الكيمياء لانه حذفها عني …\n\nافرج الدكتور مرتفع … لان الطلاب فاهمين المنهج … فقريدك بينزل شوي اذا تساهلت في الفاينل خصوصا …\n\nوخذوها مني … كيمستري 101 = افرج سكاشن …\n\nانصح فيه والكيمياء سهالات معه … اوفس هور والاميل موجودة ويتواصل معك … الواجبات ما يطالب بها لكنه ينصح فيها .\n\nسلايداته من ذهب وانصح بالمذاكرة منها … اي شيء فيه مصلحة للطلاب راح يسويه … فيه سؤال في الميجر الثاني كان من الكتاب القديم … راسل الكوردنيتور وحذفوه 🙂 ، درجات قبل الفاينل طلبو منه الطلاب يحطها على الموقع ووضعها … الله يوفقه هالدكتور النشمي … له باع طويل بالتدريس … شارك في كتابة المناهج اللي في الثانوية وكتاب المهارات اللي بالاوريا … ويعرف اسلوب المياجر ويقول لك هذا السؤال بيجي … ويجي … 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p645400-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68487/23", "user": "equal", "ts": 1277661905000, "tid": 68487, "pn": 23}}]}', 1277660800000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brain_man-chem101', 'stk-brain_man', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nأنا أخذت معاه كمستري 101 - ترم 102 - لكتشر\n\nالتحضير كل كلاس ورقة تمر ع الطلاب … وفي أخر السنة لما يحس بدا يكثر الغياب ينادي هو بأرقام الطلاب … بس مو كثير …\n\nالصوت : واضح\n\nدكتور راااائع جدا وطريقته في الشرح أكثر من رائعة وزي ما قالوا الاخوان يخليك تحل معاه في الكلاس وهذا يخلي المعلومة ترررركز في راسك … طيب جدااا مع الطلاب وما يحب يرفع صوته الا على اللي يلعبون بالجوالات في الكلاس … هذا ممكن يطرده على طول لو تكرر منه هالشي … حريص على ان كل طالب يكون فاهم معاه …\n\nالتقييم النهائي : A+ … إذا لقيته نزل معاه ولا تشاور ^_* ما بتندم …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p853911-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/41", "user": "Brain_Man", "ts": 1308156766000, "tid": 68486, "pn": 41}}]}', 1308156766000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8654-chem101', 'stk-user8654', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :ورقة يمررها واذا شاف الحضور قليل ينادي\n\nطريقة الشرح : من السلايدات حقته يعرض الكونسبت ويتكلم عنه ، وإذا كان مهم يفصل ويعطي عليه تمارين وأمثلة كثير لين تطفش\n\nالكويزات :كل اسبوع ، تحتاج مذاكرة مش سهلة\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: B+\n\nالصوت: من واضح إلى منخفض\n\nإضافات :\n\n- عيوب رئيسية : سرعته بالشرح يعني بيكون كويس انك تقرا السلايدات قبلها بيوم او تذاكر يوم بيومه\n-ميزاته : النقاط المهمة يركز عليها كثير كثير كثير ، يقلك سجل واكتب طول الوقت + كويزاته فيها تحدي يعني لو حليتها تمام تضمن درجة طيبة بالمياجر + يحاول يهتم بالطالب قد ما يقدر + محترم ومتواضع وخلوق\n\n* مشكلة بعض الطلاب المعلقين إنهم يخلطون بين الجهد الضعيف اللي بذلوه بالمادة والقريد اللي اخذوه وتعامل الدكتور معاه بموقف من جهة ، والجهة الثانية عادة الدكتور طول الترم\n\nكمستري 101 مادة تحتاج تعب وجهد ، فيها كلام كثير وتفصيلات واستثناءات وتحتاج جهد ، الدكتور ما يقدر يقدم لك كل شي\n\nواذا حصل مرة وحدة موقف بينك وبين الدكتور لا تعممه ، الدكتور بشر يصير له مثل ما يصير لك من الضغط والتعب والمشاكل والعبرة هي بعمله وسلوكه مدار الترم .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1138247-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/51", "user": "user8654", "ts": 1355243290000, "tid": 68486, "pn": 51}}]}', 1355243290000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9306-chem101', 'stk-user9306', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركاته\nاعتقد هو الكوردنيتر حق chem 101\n\nالسمستر:-132\nالتحضير : يمرر ورقة على كل الطلاب وبعض الاحيان في نهاية الحصة يشيك على الاسامي يعني ياويلك ان حضرت خويك.\n\nطريقة الشرح : الشرح كويس لكن في اشياء لازم ترجع لها سواء من الكاتب او السلايدات وحاول تركز معاه في الشرح مو تنام انتبه وتبلم الانك يمكن تضيع الانه يقول بعض الاشياء وتجي في الميجر خصوصا اذا كان يحل المسائل حاول تفهم وش قاعد يسوي.\n\nالكويزات : سهله الى متوسطة لكن لاتخاف وترتبك.\n\nالمياجر: كومن لكن اذا تبي تجيب درجه حلوة حل اسئلة اللى في اخر الكتاب واذا ماعرفت اكتب السؤال في قوقل وحل جميع الاسئلة الفردية والزوجيه الان كثير من الاسئلة تجي بس يغيرون الارقام + حل اولد اقزامز.\n\nالفاينلات : نفس الكلام اللي في المياجر\n\nالقريد النهائي: B\n\nالصوت: عادي\n\nالكويزات تقريبا 10 وراح يحذف اسوء واحد منها “مومتأكد من هذا الكلام”", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1360268-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/59", "user": "user9306", "ts": 1398969965000, "tid": 68486, "pn": 59}}]}', 1398969965000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-strange_phantom-chem101', 'stk-strange_phantom', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "شطحة : الصورة أقدم شي يبغالها تغيير الرجال شيب الله يحسن لنا وله الخاتمة 🌹\n\n151 CHEM 101\n\nالتحضير :\nورقة تمر على الطلاب بداية الحصة … واذا شاف العدد قليل اوقات ينادي على الارقام ومايحب احد يحضر خويه!\n\nطريقة الشرح :\nصراحة أنا اشوف المادة تعتمد عليك وعلى طريقة مذاكرتك اهم من الدكتور بدرجة كبيرة\nيمكن أكثر مادة اعتمدت فيها على الكتاب من يوم مادخلت الجامعة للأن … ويفيدك بشكل كبير\nما أخفيكم المادة تحتاج متابعة أول بأول خصوصا للي ما يداني الكمستري مثلي 😛\n\nالشرح يكون بسلايدات الكتاب ومتمكن من المنهج باحتراف ويجاوب على أي سؤال عندك\nغالبا ماكنت اركز معاه الا بالأشياء اللي احسها مهمة وتحتاج شرح …\n\nأوقات كثير ممكن يطلع لكم Check Points على السلايدز ويطلبكم تحلونها بعد مايشرح معلومات عنها عشان تثبت المعلومة\nانا ما أحب هالطريقة بالشرح وغالبا ما كنت احلها 😃\n\nالكويزات :\n\nصعبة وفيها شغل\nأسئلة كثير يجيبها من المياجر السابقة\nغالبا تكون اختيارات بس تحتاج تمرس , وممكن يعطيك واجب على Bb و واجب ورقي يكون عليهم 4 درجات ويصير الكويز من 6 المجموع =10\n\nوزي ما الكل عارف الكويزات عليها 17.5 فلازم تركز عليها مو تفهي مثلي 🚬\nعطانا تقريبا 10 كويزات وحذف أسوء واحد لكل طالب بالاخير\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: B+\n\nالصوت: متوسط والاكسنت على خفيف مقارنة بمدرسين اخرين\n\nإضافات : الرجال حسب تجربتي معاه طيب وشغله نظيف بس يبغالك تشتغل معاه ومع المادة\nوفيه حركة سواها اكثر من مرة كبر بعيني … اذا كان فيه ميجر على الطلاب وكلمه اكثر من واحد مستعد يلغي الكويز اذا فيه او الريسيتيشن بكبرها “سواها يمكن 3 مرات هالفصل”\nوزي ماقلت الدكتور مايهم كثير بهالمادة … بالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437734-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/71", "user": "Strange_Phantom", "ts": 1451724390000, "tid": 68486, "pn": 71}}]}', 1451724390000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-chem101', 'stk-user10218', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 T-141\n\nالتحضير:\nينادي\nطريقة الشرح :\n\nيشرح من سلايداته واهي زينه لانه فيها اولد اكزام بس ما يعطيك اياها\n\nشرحه لك عليه ، عادي\n\nالكويزات :\n\nاختيارات\nشفها على\n\nChem 101 Q -141 Isab\n\nالمياجر:\nميجرين كومن\nالفاينلات :\n\nكومن\nالقريد النهائي:\n\nB+\n\nالصوت:\nالاكسنت اشوي صعبه تتعودعليها في اول اسبوع\n\nإضافات :\n\n* المدرس حبوب و محترم و طيب\n\nخلك قدام ورح له اوفس اور حتى لو ما عندك شي وراح يظبطك\n\n* الريسنتيشن يحل فيه اولد اكزام قبل الكويز مفيده جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437964-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/72", "user": "user10218", "ts": 1451888276000, "tid": 68486, "pn": 72}}]}', 1451888276000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulelahft-chem101', 'stk-abdulelahft', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 161\n\nالتحضير: شديد بالتحضير، يوزع ورقة بداية الكلاس وياخذها نهاية الكلاس. أقل شي مره في الأسبوع بعد ماتجيه الورقة يحضر بنفسه مره ثانية عشان يقفط الطلاب الي يحضرون اخوياهم.\n\nطريقة الشرح: سييييييئ للغاية، يشرح عالسلايدات والسبورة وصراحة يحاول قد مايقدر يوصل المعلومة لكن ماتقدر تفهم معه ابد.\n\n**الكويزات:**صعبة لكن تقدر تحلها. كل كلاس رسيتيشن كويز.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالقريد النهائي: D+\n\nالصوت: واطي ماتسمع زين واللهجة هندية لك عليها شوي.\n\nإضافات: صراحة دكتور محترم لكن في النهاية اقولك انحش منه سيئ من كل النواحي. الميزة الوحيدة فيه إنه الكوردنيتر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467294-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/75", "user": "AbdulelahFT", "ts": 1485779603000, "tid": 68486, "pn": 75}}]}', 1485779603000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-deadly_scorpion-chem101', 'stk-deadly_scorpion', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(162) chem101 lab\n\nالتحضير: يحضر من البري لاب كويز\nالشرح: الدكتور عندو علم وفاهم ما شاء الله بس في عندو مشكلة في شخصيتو وما بقدر يشرح حتى لو هو محضر وجاهز\nالكويزات: الاسئلة اللي كان يختارها بعضها بسيط وبعضها متوسط ويختارها على حسب احتياجنا الها بالتجربة\nالمياجر: NA\nالفيانلات: جابلنا الفاينال بس حسابات ولا اشي نظري\nالقريد النهائي: c\nالصوت: واضح ومسموع ولكن مشكلتو بتأتئ بالكلام كثير فيمكن بالعافية تفهم عليه\nاضافات: الدكتور تعاملو جدا رائع وممتع بس زي ما قلت عندو مشكلة بشخصيتو بتخليه يتوتر وهو بيحكي مع اي حدا\nما بعرف اذا كان السبب انو جديد في الجامعة او لا بحكم انو هاظ السمستر كان الثالث بالنسبة الو\nوكنصيحة لا تنزل عندو الا اذا ما في غيرو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473128-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/5", "user": "Deadly_Scorpion", "ts": 1494773161000, "tid": 175793, "pn": 5}}, {"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(162) chem 101\n\nالتحضير: يمرر ورقة عالطلاب وبعض الاحيان يصير ينادي بالارقام نهاية الكلاس وخصم درجتين للي بحضرو صاحبو\nالشرح: رهيب جدا، بعطيك الزبدة وما بطول في الشرح وبحل امثلة واذا ما فهمت اشي بتقدر تسألو ويجاوبك، وفي الريسايتيشن بحل اولد اكزامز\nبس يمكن في ناس ما تحب الاسلوب السريع في الشرح\nالكويزات: سهلة بس دايما في سؤال واحد لازم يخليك تشك بحالك، وبجمع بين النظري والحسابي\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: +A\nالصوت: للاسف كان الصوت اكبر مشكلة اواجهها صوتو شوي خافت يعني لازم تقعد قدام عشان تقدر تسمع ولهجتو فيها شوية طلاسم\nاضافات: طبعا كان هو الكوردينيتر هاظ السمستر واغلب الطلاب سفلوا فيه بسب حركة الميجر الثاني\nبس عن نفسي انا اشوفو انو دكتور بطل ما يكرفك كثير بالهوموركات والخ\nكان يرسل هومورك واحد بالاسبوع وهي اسئلة اولد اكزام\nومن ناحية اخلاق ما اشاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473129-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/76", "user": "Deadly_Scorpion", "ts": 1494774173000, "tid": 68486, "pn": 76}}]}', 1494773161000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nvm-chem101', 'stk-nvm', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 - 161\nالتحضير : ورقة تمشي، واحيان ينادي الاسماء اخر الكلاس واللي يشوفه محضر ومب موجود يحسب عنه غيابين 🙂\nطريقة الشرح : سيئة ، يجيب النوم وقليل مايكتب على السبورة كل شي كان عالبروجكتر كان يسحب على اشياء كثير بحجه ان الطالب مفروض عارفها.\nالكويزات : متوسطة مائلة للصعوبة وتعتمد على الكويز السابق لانه يحاول يخلي الافرج على ٦/١٠ ، ٥.٥/١٠\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D\nالصوت: واطي، وبسبب موطنه احيان كلامه يكون غير مفهوم.\nإضافات : التأخير عنده عادي وقليل يدقق، تقريبا كل اسبوع كويز وهومورك.\nفي الريستيشن مايشرح، يجلس ويشغل البروجكتر ويخلينا نحل، اذا ماعرفنا نحله كلنا قام من كرسيه وحلها.\nاذا بتنزل عنده بتكمل الكورس سيلف ستدي + قال لكل واحد بينحذف عنه غياب وماحذف.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475384-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/77", "user": "nvm", "ts": 1497719910000, "tid": 68486, "pn": 77}}]}', 1497719910000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-chem101', 'stk-breaktheunbreakable', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 161\n\nالتحضير: يهتم بالتحضير، ورقة تمر بين الطلاب. بعض الأحيان يشيك بنفسه على الورقة عشان لو حد حضر خويه ولا شيء. مرة غيبني بالغلط عشان كذا أنصحكم تنتبهوا وتتأكدوا كل فترة من غياباتكم\n\nطريقة الشرح: شرح مفقع. ما تفهم شيء.\n\nالكويزات: متوسطة مائلة للصعوبة. إذا ذاكرت زين بتحلها إن شاء الله أغلبها أولد اكزامز.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالقريد النهائي: D. حصلت عنده B بمجهودي الشخصي.\n\nالصوت: ينسمع صوته بس لهجته هندية وما تفهم شيء.\n\nإضافات: الدكتور ما يصلح تنزل عنده ونصيحة أخ لأخ لو اضطريت تأخر المادة أخرها ولا تنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492295-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/78", "user": "BreakTheUnbreakable", "ts": 1526267331000, "tid": 68486, "pn": 78}}]}', 1526267331000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-chem101', 'stk-rapls', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 - 181\n\nالتحضير : ورقة يمشيها ع الجميع, واذا كان العدد قليل ينادي بالأسماء .\n\nطريقة الشرح : شرحه حليو يفضل تكون قدام عشان تشوف اللي يكتبه بالسبورة , احيانًا يعطي أسئلة ونحلها بالكلاس , ما هو ذاك الشرح الأسطوري لكن يمشي الحال .\n\nالكويزات : أغلبها كويزات قديمة موجودة في الريسورسز ( 4 أسئلة خيارات ) مستواها متوسط الى سهل .\n\nالمياجر : كومن .\n\nالفاينل : كومن .\n\nالقريد النهائي : B+\n\nالصوت : غير واضح للي جالس ورا , لكنته هندية لكن سهلة .\n\nإضافات : الدكتور مرح وكلاسه ممتع أحيانًا , الافضل تكون محضر للدرس عشان تستفيد بشكل أكبر , هومووركاته سهلة ويرسل مسائل على كل تشابتر اسبوعيًا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504740-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/80", "user": "Rapls", "ts": 1547039585000, "tid": 68486, "pn": 80}}]}', 1547039585000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-chem101', 'stk-salman_al-ghamdi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-181\n\nالتحضير : ورقة يمررها عالطلاب، ما يدقق عالتحضير واجد الا اذا شاف العدد قليل يبدأ ينادي طلاب عشوائيين واللي يشوفه محضر وناداه ما رد يخصم عليه (آخر الترم حذف غيابات فيعني)\nطريقة الشرح : يفتح السلايدات ويشرح اللي فيها ويزيد معلومات من عنده ومفيدة صراحة\nالكويزات : اربع اسئلة، بسيطة اغلبها خصوصا انه يكرر كويزاته مرات وبرضو يشرح مسائل في الريسيتيشن قبل الكويز وتجي اسئلة مشابهة، فتضمن درجة حلوة في الكويزات غالبا.\nالمياجر: كومون، لكن بحكم انه الكوردنيتر فبقول ان اول ميجر جانا حلو وثاني ميجر جا طويل والوقت قصير عشان ينزل الافرج\nالفاينلات : كومون، وجانا سهل جدا، ونصائح الدكتور في الكلاسات جدا فادتني صراحة\nالقريد النهائي: A+\nالصوت: واضح نوعا ما خصوصا مع كبر سنه، انا اجل قدام فما اعاني اي مشكلة خصوصا.\nإضافات :الدكتور حبيب جدا واكثر من مرة يحاول يلطف الجو بنكت الشيبان حقته (واللي شغالة بشكل رهيب خخخ) وبرضو بكم مزحة خفيفة مع الطلاب، صراحة الدكتور جدا استمتعت بوقتي معه ولو أنني أكره الكيمياء كره العمى خصوصا بعد محاولاتي الفاشلة معها وقت الاوريا ودرجاتي اللي تفشّل، لكن مع الدكتور ايساب استانست واستفدت استفادة كبيرة. انصح به كخيار أول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509990-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/81", "user": "Salman_Al-Ghamdi", "ts": 1558436713000, "tid": 68486, "pn": 81}}]}', 1558436713000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed_alhamal-chem101', 'stk-ahmed_alhamal', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101\nTerm 182\n\nالتحضير : ورقة تمر عالطلاب و يوقعون. (غالبا يوم الخميس يحضر بالأسامي).\n\nطريقة الشرح : يقرأ سلايدات الكتاب قراءة سريعة و يوقف عند بعض النقاط المهمة (شرحه عادي جدا).\n\nالكويزات : سهلة تجي نفس اللي موجودة في الريسورسز. 👍\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: +A 🤓\n\nالصوت: خفيييف بسبب كبر سنه، أول أسبوع كان يجي بدون مايكروفون و ما نسمع شي بعدين صار يجيبه وتعدل الوضع 👍\n\nإضافات : شخصيا أشوف إنه من أفضل دكاترة هالمادة لكن حط في بالك إن المادة سلف ستدي مهما كان دكتورك ممتاز+ بعض النقاط اللي سحب عليهم في اللكتشر يشرحهم في الريسايتيشن.(حاول إنك ما تنزل المادة في الترم الثاني لأن الآفرج ناااااااااااااار بسبب الأوريات 🤪).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517009-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/83", "user": "Ahmed_Alhamal", "ts": 1573852227000, "tid": 68486, "pn": 83}}]}', 1573852227000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sab3495-chem101', 'stk-sab3495', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-T192\nالتحضير : زي ماقالو الشباب ورقة تمر على الطلاب ماعنده مشكلة في التأخير القليل بس لو دخلت المحاضرة متأخر بيكلمك, الله أعلم ايش يصير مع الطالب اللي يتأخر انا ما تأخرت الترم ذا. التحضير اونلاين كان بس تكتب السيريال نمبر حقك في الشات حق البلاكبورد اخر الكلاس. وما أتوقع انه دقق فيها كثير\n\nطريقة الشرح : اشوف شرحه جيد جدًا مو مرة ممتاز بس يكفي ويوفي. يستخدم السلايدات حق الكتاب بس يضيف عليها حاجات بسيطة وأسئلة من عنده وتكون مفيدة الصراحة. فترة الاونلاين ماكان يفيدني شرحه ابدًا. مع انه فيه اكثر من شخص ماواجه صعوبة انه يفهم فترة الاونلاين\n\nالكويزات : كويزاته عادية مائلة للصعوبة بس اسئلتها مرة مفيدة وتجي أفكارها في الميجر. كان فيه هوموورك سؤالين او ثلاثة وكانت الاسئلة مفيدة.\n\nالمياجر: كومون\nالفاينلات : كومون\n\nالقريد النهائي: A\n\nالصوت: فيه لهجة وما ينطق ال “ث ذ ش” صح. بس مفهوم جدا وماواجهت مشاكل معاه\n\nإضافات : الدكتور كأخلاق طيب جدا ومتعاون واشوف انه لازم يكون من خياراتك الاولى.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526484-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/85", "user": "sab3495", "ts": 1604324420000, "tid": 68486, "pn": 85}}]}', 1604324420000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-chem101', 'stk-guest', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f179305", "n": "Dr. Mohammed Abdalwadoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Lab\n\nالتحضير : يومياً , عن طريق تسليمك للريبورت حقك .\n\nطريقة الشرح :\nيشرح التجربة بالتفصيل مع كتابة طريقة الحسابات للأسئلة على السبورة .\n\nالكويزات :\nيختار من سؤالين إلى أربع اسئلة من البريلاب في اول 10 دقايق من اللاب تحلهم .\n\nالفاينلات :\nالفاينل لاب ينقسم قسمين :\nتجريبي : عطانا 3 تجارب قال في وحدة منها بتجي .\nنظري : عطانا 6 تجارب قال بتجي عليها اسئلة ( خيارات - صح و خطأ - أذكر - علل - أحسب ) .\n\nالصوت :\nواضح و أغلب الوقت يتكلم عربي مع لهجة سودانية.\n\nإضافات :\n- تصحيحه في الريبورت شديد شوي ويصحح بذمة .\n- في أغلب اللابات نقعد الوقت كامل و نطلع آخر ناس بحكم انه يخليك تسوي التجربة كاملة مع كل trials .\n- ما يفضل الشغل في قروبات .\n- ما عنده مشكلة في الميك اب .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501846-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-abdalwadoud/179305/3", "user": "Guest", "ts": 1541325981000, "tid": 179305, "pn": 3}}, {"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الماده : CHEM 101\nالتحضير : ورقه يمررها قبل نهاية الكلاس , بداية الترم قال لنا أنه بيسامحنا في غيابين بس نهاية الترم خصم على الغيابين\nطريقة الشرح : للأمانه الماده صعب تعتمد فيها على شرح دكتورك في الكلاس لانها طوييلة جداً ولكن رغم ذلك شرح الدكتور سيئ وأذكر طلاب واجد كانوا مستائين من الشرح والسبب أشوف أنه ماعنده مَلَكَة الشرح يعني تحسه كانه بس قاعد يقرأ + رتم الشرح سريع جداً حتى كنا متقدمين على السيليبس لانه يسرع في الدروس.\n\nالكويزات : يحط فيها اسأله صعبه واسأله سهله ويجيب اسأله مشابهه للأولد اقزامز.\n\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: ممتاز ومسموع , ممكن في البدايه تواجه مشكله مع الأكسنت بس بتتعود بعدين.\nإضافات : ما أنصح تنزل عنده الا إذا كان آخر خيار وناوي تشتغل معاه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522217-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/10", "user": "Guest", "ts": 1590016282000, "tid": 172599, "pn": 10}}, {"id": "stk-dr-f182523", "n": "Dr. Sulayman Oladepo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 Lab\nالتحضير : يحضر عن طريق التيمز\nطريقة الشرح : يقرا السلايدات بس وكل ما سألته عن شيء يرد عليك روح اقرا التجربة\nالكويزات : من متوسطة الى صعبة\nالقريد النهائي: D\nالصوت: لغته الانجليزية ممتازة وصوت واضح\nالتصحيح: شديد جداً وينقصك على اي شيء\nإضافات : حاول انك ما تنزل عنده لانه شديد واحيانا يكون ظالم في التصحيح وشرحه لتجربة سيء جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526643-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sulayman-oladepo/182523/3", "user": "Guest", "ts": 1605116471000, "tid": 182523, "pn": 3}}, {"id": "stk-dr-f182958", "n": "Dr. Wissam Iali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سلام عليكم و رحمة الله و بركاته\nالتحضير عند د. وسام كان عبر بلاك بورد و انا بشوف انه تحضير مرن (يكفي تحضر مرة من مرتين)\nالشرح ممتاز، يشرح و يفسر القوانين بشكل مفهوم. لا يعتمد على قراءة السلايدات بل على شرحها.\nالصوت واضح و مفهوم. لغته واضحة و سهلة\nيسجل المحاضرة على البلاك بورد.\nالريسيتيشن مفيده عنده و الكويزات معتدلة الصعوبة.\nالدكتور خلوق و متفهم جداً. يهتم بطلابه و يعمل help session قبل الإختبارات.\nمرن جداً بموضوع الأوفيس اورز.\nانا بشوفه افضل من علم chem 101.\nيعطيه العافيه ماقصر معنا بهذا الترم.\nالقريد A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527504-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wissam-iali/182958/16", "user": "Guest", "ts": 1609617007000, "tid": 182958, "pn": 16}}, {"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم الاون لاين 201\nchem 101\n\nالتحضير: التحضيرسؤال على البلاكبور اول عشر دقايق من المحاضرة.\n\nطريقة الشرح: يشرح على سلايدات الكتاب وشرحه عادي جدا يعني بس يقرا السلايدات واذا جا سؤال بس يقرا خطوات الحل. الشرح (10/6).\n\nالكويزات: تقريبا 10 كوزات على البلاكبورد وكلها خيارات. الدكتور للاسف ما كان يراقب الكوزات والنتيجة ان الافرج كان عالي جدا وفي النهاية كلنا انخسفنا ونقصنا واجد والسبب غلطة الدكتور (كان يقدر يخلي الكوزات في الريسايتيشن ويخلينا نفتح الكاميرات).\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالقريد النهائي: دكتور جنجا B عشان الكوزرات.\n\nالصوت: واضح.\n\nاضافات: الدكتور اخلاق ومن افضل ادكاترة في التعامل واعتقد انه لو في الترم العادي بيكون افضل بواجد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527659-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/26", "user": "Guest", "ts": 1609936918000, "tid": 175794, "pn": 26}}, {"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101- 201\n\nالتحضير : يفتح اختبار من سؤال واحد بالبلاك بورد لمدة 5 دقايق غالبا xx:40، بس عليك تدخل وتجاوب اي شي\nطريقة الشرح : من سلايدات الكتاب، والشرح سريع واعتقد السبب ان المنهج طويل ولازم يخلص بسرعه\nالكويزات : اسبوعيا كويز 3 اسئلة بالريسايتيشن كلاس، آخر الترم صار يطلب مننا نفتح كام وقت الكويز\nالمياجر:\nالفاينلات :\nالقريد النهائي: B\nالصوت: واضح\nإضافات : حاول تنزل عن دكتور تقدر تجيب عنده اعلى درجة بالكلاس وورك، الباقي ما يهمك حرفيا، اذا شفت واحد يطلب تفتح كاميرا وشادها هذا ابعد عنه وريح نفسك، فا اشوف ايساب خيار مناسب جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527670-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/86", "user": "Guest", "ts": 1609950726000, "tid": 68486, "pn": 86}}]}', 1541325981000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11896-chem101', 'stk-user11896', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-T203 (عن بعد)\nالتحضير : فورم في نهاية المحاضرة\nطريقة الشرح : يشرح لنا من سلايدات الكتاب، وشرحه واضح في أكثر الأحيان ، ويستقبل أسئلة الطلاب وأشوف أن الطلاب متفاعلين معه في الأسئلة بشكل لم أرى مثله عند الدكاترة الآخرين. بس المادة أشوف أنها سيلف ستدي مهما كان شرح الدكتور.\nالكويزات : 8 كويزات وحذف لنا أسوأ واحد وكل كويز يكون 3 أسئلة متوسطة إلى سهلة (كويزاته أسهل من أسئلة الهومورك حقته). الآفرج كان مرتفع وصعب أنك تأخذ درجة فوق 12/15 في الكلاس ورك (غالبا لأنه ترم صيفي).\nالهومورك: كان كل واجب فيه 5 أسئلة واللي أتذكره أن الوقت بس ربع ساعة أو ثلث ساعة أحيانا والأسئلة شوية صعبة\nالمياجر: اختبار نصفي فقط والأسئلة موحدة على جميع السكاشن.\nالفاينلات : موحدة\nالقريد النهائي: +B\nالصوت: أعتقد لو كنا في الحضوري ممكن يكون ضعيف شوي بس عن بعد كان واضح في البلاكبورد.\nإضافات : الدكتور أخلاقه ممتازة ويتقبل أنك تراجعه بصدر رحب لو كنت متأكد أنك انظلمت في درجات كويز أو اختبار نصفي أو غيره. وهو ماشاء الله عليه فاااهم المادة بس أحيانا ما يذكر بعض الأشياء لأنه يفكر أننا فاهمينها ، فعليك أنك تسأله في أي شيء ما تفهمه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531424-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/88", "user": "user11896", "ts": 1629752118000, "tid": 68486, "pn": 88}}]}', 1629752118000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12191-chem101', 'stk-user12191', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-TERM211\n\nالتحضير :\nيفتح كويز عن طريق البلاك البورد تحضر نفسك آخر ٥ دقايق وتمشي. سواءً انت في الكلاس ولا انت في البيت ما درا عنك.\nطريقة الشرح :\nشرحه عادي جدًا. ويشرح عن طريق سلايداته وصراحه هي مفيدة وفيها اسئلة جيدة ولكن يرفض إرسالها لنا.\nالكويزات :\nعن طريق البلاك بورد، متوسطة إلى سهلة احيانًا.اختبرنا ٧ كويزات وحذف أسوأ واحد.\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالصوت:\nضعيف حاول تجلس قدام عشان تسمع وش يقول. واللهجة هندية مفهومة.\nإضافات:\nالدكتور مشكلته انه حليل (لطيف) بزيادة فيستغلونه الطلاب. في بعض الكويزات كانت قبل إجازات فكان يقول الي يبي يسافر يقدر يختبر من بيتهم والي بيقعد يجي للكلاس ، فما كان يجي للكلاس الا ٣ أو ٤ طلاب فقط ! . وحاول ما تسأل كثير لأنه بيزبدلك قدام العالم. ولكن بمجمل عام الدكتور قمة في الأخلاق لم أرى مثل أخلاقه قط!.\nالقريد النهائي:\nB ، ماهو احسن واحد فيه خيارات أفضل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533362-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/89", "user": "user12191", "ts": 1641633154000, "tid": 68486, "pn": 89}}]}', 1641633154000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-raawann.00-chem101', 'stk-raawann.00', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68486", "n": "Dr. Anvarhusein Isab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 - T212\nالتحضير : عن طريق البلاك بورد يفتحه اخر 5 دقائق من الكلاس. كل الترم ما كان مهتم لكن فجأه عصب بنهاية الترم و صار يحضر عن طريق ورقة و يتم التوقيع عند الاسم لكل يوم.\nالشرح :\nLEC : ما حبيته جدًا عادي احس في افضل منه بكثير.\nREC : حلو يحط اسئلة ممتازة و يخلينا نتدرب عليها ولكن المشكلة ما كان يرسلها لنا لذلك كنا نضطر نصور كل شيء. بعض النظر عن هالشيء كلاسات الريس مره حلوه اذا كان الشخص فاهم الدرس و يحل معاه.\nالكويزات : من سهلة الى متوسطة , خيارات , 4 اسئلة عن طريق البلاك بورد. اختبرنا 8 و حذف اسوء واحد.\nالمياجر : كومن\nالفاينل : كومن\nالصوت : ضعيف لازم تجلسون قدام او بنص القاعة عشان تسمعون بشكل واضح.\nإضافات : اللهجة هندية بالنسبة لي ما كانت واضحة مره. الدكتور شخصيته جدًا طيبة و يحاول بقدر الامكان يوصل المعلومة لكن المشكلة بعض الاحيان يقول اسألوا اذا عندكم سؤال و اذا سألنا يفصل علينا. بشكل عام الدكتور جدًا عادي و متأكده 100% في افضل منه. مرات يكنسل حصص الريس لو كان في ميجر مادة معينة أي انه يتفهم ظروف الطلاب.\nالقريد النهائي للدكتور : C+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534875-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anvarhusein-isab/68486/90", "user": "Raawann.00", "ts": 1658433251000, "tid": 68486, "pn": 90}}]}', 1658433251000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_student-chem101', 'stk-_student', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68487", "n": "د. عبدالمطلب جابر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا حاليا ادرس عنده في chem101\n\nالتحضير: ورقة تمر على الكلاس، ومايحاسب على التأخير\nالشرح: وااااااضح وعلى السلايدات، ويعجبني شرحه ويعرف يفهم و احيانا يضرب امثلة مناسبة تقرب اهم النقاط\nكويزات: متوسطة تميل للسهولة\nفاينلات: كومون\nالتقييم النهائي: A\nالصوت: وااضح\nإضافات: المدرس اخلاااااق، بس ماادري عن قريداته ودرجات الكلاس وورك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p511413-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68487/11", "user": "_student", "ts": 1262098098000, "tid": 68487, "pn": 11}}]}', 1262098098000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5770-chem101', 'stk-user5770', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68487", "n": "د. عبدالمطلب جابر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101 سمستر 92\n\nالتحضير : كل كلاس يمرر ورقة ونوقع عليها\n\nطريقة الشرح : ممتازة، اذا تركز معاه ما تحتاج غير قراءة سريعة ع الدرس لمدة لا تتجاوز 10 دقائق + حل المسائل لأنه يمر عليها سريعا بالسلايدات وانت يبغالك ترجع وتفهمها كويس، بالاضافة الى إنه يحرق أعصابه بالشرح وما يقصر، و البعض من الطلاب الله يهديهم ما ينتبهون ولا يطلعون من الكلاس وهو يطرطع من ذي الحركة لكنه صبور جدا.\n\nالكويزات : 5 او 6 أسئلة ملتبل تشويز سهلة للي مذاكر.\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات : قد تكون طريقة الشرح بالسلايدات مملة بعض الشئ، فتحتاج الى مجاهدة للبقاء بتركيز معاه 😆 وهذا بالأخير راح يفيدك كثير\n\nفي الريسايتيشن عادة يقول أي واحد عنده سؤال مو فاهمة ولا شئ يقوله يعني ما يحل من نفسه مسائل فيبغالك تحضر الدرس قبل + يشرح بعض الاضافات المهمة اللي ما امداه يقولها بالكلاس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p642533-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68487/22", "user": "user5770", "ts": 1277270704000, "tid": 68487, "pn": 22}}]}', 1277270704000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-chem101', 'stk-user4988', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68487", "n": "د. عبدالمطلب جابر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101\n091\nليكتشر و ريستيشن …\n\nالتحضير : كل كلاس يمرر ورقة ونوقع عليها … المزعج بالنسبة للإستاذ … إن اللي يحضروا 20 و اللي في الورقة 80 😍\n\nطريقة الشرح : زي ما قالوا الشباب … من السلايدات مباشرةً …\n\nالكويزات : 😐\nمين قال إن كويزاته سهلة ؟؟؟\nيا أبويا كويزاته من متوسطة إلى ناااار … حتى لو ذاكرت لازم تجيك حاجات تلخبطك …\nالقهر إنه لما جاب سيرة الكلاس وورك في نهاية السمستر … قال لنا إنه راح يعلقها على باب مكتبه بعد عدة ايام - و جات على وقت الفايلنز - بعدما خلصت الفاينلز ورحت للأوفيس … مالقيت الورقة 😐 و ماني عارف درجة الكلاس وورك حقي إلى الآن 😦\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: اعطيه c+\n\nالصوت: الأكسنت حقه غريب… بس تفهم عليه … فاكرين كيف ينطق كلمة work ؟؟؟\n\nإضافات :\nهممممممم … المدرس لك عليه صراحة … لا في شرح و لا في كلاس وورك !!\nأخلاق ؟؟ نعم … طيب ؟؟نعم …\nبس في كورس أساسي زي chem101 الواحد مو فايق يأكل مطبات من اولها …\nعلى العموم …\nلو إنك من الفصيلة اللي تنام مع الكتاب , نزل عنده و لا بأس عليك …\nغير كذا … شوف لك غيره …\nو لا يفوتك الأستاذ أسامة البيجرامي 🌹…\n\nو الله الهادي غلى سواء السبيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p729316-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68487/30", "user": "user4988", "ts": 1288436277000, "tid": 68487, "pn": 30}}]}', 1288436277000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-everest-chem101', 'stk-everest', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68487", "n": "د. عبدالمطلب جابر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101-Lecture\nTerm: 101\n\nالتحضير: ورقة تمر على الطلاب، ما يحاسب على التأخير وفي ناس تحضر بعد ثلث او نص ساعة ولا يقول لهم شي.\n\nطريقة الشرح: يشرح من سلايدات شاملة للمنهج بس مو مرتبة، يقرا كثير منها بس يوقف شوي ويعلق عليها وقليل ادا يستخدم السبورة، اما بالنسبة للتفهيم يفهم.\n\nالكويزات: ما اخدت عنده رسيتيشين.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالصوت: مسموع بس على مستوى واحد.\n\nإضافات: المدرس اخلاق وشال كم غياب من عندي في النهاية، بس شرحه مملل الى درجة كبيرة خاصة انه يقرا كثير و ما يغير نبرته، والمادة بالنسبة لي ما تحتاج ذاك الشرح، الكتاب يكفي وزيادة.\n\nالقريد النهائي: +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779284-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68487/37", "user": "EvErEst", "ts": 1296426988000, "tid": 68487, "pn": 37}}, {"id": "stk-dr-f96572", "n": "أ. أوك سالم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101-Recitation\nTerm: 101\n\nالتحضير: ورقة تمر على الطلاب، المتاخرين ما يقول لهم شي، ويخليك تطلع من الكلاس ادا عندك شغلة ضرورية.\n\nطريقة الشرح: يشرح النقاط الرئيسية على السريع وبعدين يعرض اسئلة على سلايدات بعضها\nيحلها هو وبعضها يخلي الطلاب.\n\nالكويزات: متوسطة وحذف اقل كويز.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالصوت: واضح بس الاكسنت لك عليه شوي.\n\nإضافات: طبعا المدرس جديد وكان شرحه مو داك الزود، بس بالنسبة لي المادة ما تحتاج شرح.\n\nالقريد النهائي: +C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779291-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96572/9", "user": "EvErEst", "ts": 1296428008000, "tid": 96572, "pn": 9}}]}', 1296426988000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cesar_peace-chem101', 'stk-cesar_peace', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68542", "n": "Dr. Mohammad Wazeer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لآب كيمستري 101 … الترم : 101\n\nفي اللآب بططل … انصصح به في اللآب\n\nمن عدة نوآحي :\nالكويزات انت وخويآك تعاونوا وحلوهـ سووى … يعني مو مرهـ متشدد كل واحد لحاله و محد يغغش … ماعندك هذا كله\n\nالتجآرب على حسب التجربة … تجربة بسيطة تخرج بسرعه … تجربة طويلة تجلس شوي زيادة و زي كذآ … التصحيح حبووب ماعليه بالتصحيح\n\nالزبدهـ : انصح عندهـ باللاب فقط\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p755071-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-wazeer/68542/28", "user": "CeSaR_PeaCe", "ts": 1293726146000, "tid": 68542, "pn": 28}}]}', 1293726146000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_easa-chem101', 'stk-ali_easa', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68542", "n": "Dr. Mohammad Wazeer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خذوا العلم الأكيد من واحد درس عنده هذا الترم\n\nSemester 101\nChem 101\nLab\n\nبسم الله , إن شا الله ما أظلم الرجال\n\n*اشوف بعض الردود القديمة تقول : \" أول ما تخلص تطلع \"\nيعني بالله إذا خلصت التجربة , في دكتور بيمنعك من الخروج ؟\n\n*كويز في بداية كل لاب و بحسب ما سمعت , موب كل الدكاترة يعطون كويز قبل كل لاب\n\n* يطلب إنك تعيد التجربة أكثر من مرة , ما أدري إذا كان هالشي عند كل الدكاترة لكن\nفي كل لاب كان يطلب منا تكرار التجربة\n\n* تصحيحه سيء جدا , أذكر مرة عطاني 8 في الكويز و كانت جنب ورقتي ورقة مكتوب عليها\n10/10 , قارنت بينها و بين ورقتي لقيت أنها شبيهه بالكامل بحلولي , كلمته و سألته وين الخطأ\nبعد ما فرك عينه كم مرة و حك راسه قام يضحك و عطاني 10 , بعد ما عدل الدرجة قالي\n\" وضّح خطك مرة ثانية \"\n؟؟؟\n\n* تصحيح الريبورتات , ما أتوقع أن أحد من السكشن اللي كنت فيه أخذ فل مارك و لا مرة ,\nطبعا هالكلام أقوله لأن الدكتور في كل لاب يجيب معه كويزات و ريبورتات الاب حق الأسبوع اللي فات ,\n\n* شرحه للتجربة موب واضح\n\nما أدري ليه طولت في الكلام , الزبدة :\nمدرس سيء جدا و يستاهل قريد D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p781056-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-wazeer/68542/30", "user": "Ali_Easa", "ts": 1296744339000, "tid": 68542, "pn": 30}}]}', 1296744339000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fond_of_you-chem101', 'stk-fond_of_you', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68543", "n": "د. اسعد الذكير", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 - term 091\n\nالتحضير : كل لاب يحضر اخبر مره نسى 🤠\n\nطريقة الشرح : فلسفة و لا يعطيك المفيد\n\nالكويزات : احفظ و سمع تعاريف تعاريف\n\nالفاينلات : تعاريف الفاينل لاب عنده اي اداة درستها وتكلم عنها\nكم مرره مثل rubber policeman هذا جابه في الفاينل غيرها\nالكثير لو قدامي كتاب لاب كيمياء كان اعطيتكم اللي جابه 😐\n\nالقريد النهائي: حقك بالسنتسيمتر اذا مو اقل شوي عشان الافرج 😞\nالصوت: واضح وجيد\n\nإضافات : شوف الكومنت اللي فوق 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p902897-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68543/11", "user": "Fond_Of_You", "ts": 1316179867000, "tid": 68543, "pn": 11}}]}', 1316179867000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dear_dearly-chem101', 'stk-dear_dearly', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\nLab chem101 -term 161\nالتحضير / لاب.\n\nطريقة الشرح/ اول ساعة شرح وافي و شامل للتجربة.\n\nالكويزات / بري كويز سؤالين بالكثير و تقدر تفتح الكتاب .open book\n\nالصوت / واضح . و يتجاوب مع الأسئلة.\n\nإضافات / يسمح بالخروج اذا خلصت بس لازم على الاقل يروح نص وقت اللاب .\n-ممتاز جداً للاب .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472746-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/4", "user": "Dear_Dearly", "ts": 1494252991000, "tid": 172597, "pn": 4}}, {"id": "stk-dr-f68544", "n": "Dr. M.b. Fettouhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\nChem101 -term 161\n\nالتحضير / ورقة تمرر على الطلاب.\n\nطريقة الشرح / الدكتور ما شاء الله متقن للمنهج و شرحه واضح جداً و يبسط الأمور.\n\nالكويزات / -كويز لكل شابتر في حصص الريسايتيشن.\n-الكويز متوسط الصعوبة لكن طويل غالباً.\n\nالمياجر و الفاينلات / كومن.\n\nالقريد النهائي /للمدرس A++++\n\nالصوت / واضح و لغته ممتازة.\n\nإضافات / -المدرس قمة بالأخلاق و مجتهد دائما ً.\n-يحببك بالكيماء.\nأنصح فيه بأي كورس.\nوالسلام…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472747-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-b-fettouhi/68544/22", "user": "Dear_Dearly", "ts": 1494253576000, "tid": 68544, "pn": 22}}]}', 1494252991000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhakem-chem101', 'stk-alhakem', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f118610", "n": "د. محمد حسن زاهر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم،\n\nCHEM 101 - TERM 121\nLec + Rec\nبنود التقييم :\n\nالتحضير :\nورقة تمر على الطلاب ويمديك توقع لخوياك وماحد درى عنك\nطريقة الشرح :\nسلايدات والسبورة 3% فقط\nالكويزات :\nبداية السمستر كويز على شابتر واحد … بعدين يصيرون على شابترين . واللي بعده 3 شابترات… واللي بعده 4 شابترات وكان يوم الميجر (اختبرنا الكوةيز الصبح في اللكتشر والميجر في الليل)… نفس السيناريو بعد ميجر 1 … وطارت درجات الكوزات بسبب ذلك 😭\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:\nF\n\nالصوت: واضح (ليس من ناحية اللغة)\nإضافات :\nمن الآخر…\n\nالدكتور من بنغلادش …درس البكالريوس في ماليزيا وكمل الدراسات العليا في اليابان\nقعد في اليابان 15 سنة وصار fluent بلغتهم … الزبدة انه ما يعتبر درس انجلش\nالطلاب السعوديين يتكلمون احسن منه … لا قراامر في كلامه والفوكاب عنده كل يتكرر\nوالأكسنت 80% ما ينفهم (مخلوط بنغلاديشي على ياباني طاغي )\nأثناء عرض السلايدات ينقز من سلايد رقم 10 إلى سلايد رقم 17 … ثم بعد كم دقيقة يرجع لسلايد 15 … وهكذا كل تنقيز …وذلك بسبب أنه يتكلم عن بعض النقاط واهو ما انتقل ألى السلايد التالي ليعرض أمامك أو انه يرجع لسلايد معين عشان يوريك نقطة (Just now I have mention << جملة بتسمعها كثيييييييير) لذلك المتابعه معه صعبه\n\nكان ماسك ثلاثة سكاشن في غرفة 125 (الغرفة الكبيرة) … بداية السمستر الكل منتبه معاه وماحد يلعب وكلهم قدام … مع تقدم السمستر الناس قامت تلعب بجوالاتها وتقعد في الخلف وتغيب كثير (باعتبار ان خوياهم يحضروهم) بعد فقد الأمل في الفهم\nطبعا في دوافير مابرحوا جالسين قدام لآخر محاضرة وكان في واحد يسلّك له بشكل غير طبيعي :speech_balloon:\n\nالمادة صحيح سلف ستدري، ولكن الدكتور له دور في أنه يوضح لك مفاهيم انت تبنى عليها مذاكرتك وتتسهّل عليك ويقلل وقت مراجعتك ومن هالكلام << يسبب لغته الانجليزية الركيكة، انسى هالأشياء مع هالدكتور … كل شي بنفسك ومع نفسك :sneezing_face:\nماكان فيه واجبات لذلك أكثر شي يجبرك على المذاكرة هي الكوزات واللي للأسف تكون على شابترين غالبا أو أكثر 😞\n\nمن ناحية الدرجات/ للأمانة هالدكتور يضبطك في الكلاس وورك بس يبغالك تجيب درجات متوسطة-عالية في الكوزات وابشر بالـ 65 وأعلى من 80<< يزيد درجات طلاب كثير حتى بعد الـ normalization\n\nيبقى المياجر تقتمد على فهمك ومتابعتك للمادة\n\nالزبدة:\nاذا نزلت عنده اللكشتر، أعتبر انك تدرس لحالك بدون دكتور وشد حيلك في متابعه نفسك ولا بيتراكم عليك الكثير 🥊\n\nوالسلام عليكم ورحمة الله وبركاته،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1161544-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118610/6", "user": "alhakem", "ts": 1357825177000, "tid": 118610, "pn": 6}}, {"id": "stk-dr-f68545", "n": "Dr. Mazen Khaled", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 LAB - Term 121\n\nبنود التقييم :\n\nالتحضير :\nأول لابين-3 لابات وبعدين هوّن <<الظاهر اعتمد في ذلك على تسليم الريبورت\nطريقة الشرح :\nباعتبار انه يعتبرك فاهم التجربة قبل لا تكون جاي(بسبب البري لاب: سأكتب عن ذلك vv)\nيكتب القوانين وبعض المعلومات على السبورة ، ويبدأ في شرحها على السريع مع بعض التطبيق السريع … ربما يشرح التجربة تطبيقيا بشكل كامل أو اغلبها >>حسب نوع التجربة\nبعد ذلك يتجول في اللاب ساعة أو نحو ذلك وبعدها يجلس أو يطلع من اللاب ويخلي الباقي على مساعده ولا يرجع الا نهاية اللاب… كلا المدرسين(الدكتور ومساعده) متجاوبان مع أسئلة طلابهم <<المساعد اتوقع يتغير كل سمستر بعني مايثبت وما اقدر أقيمه هنا مع انه هو اللي يعتبر ماسك اللاب أكثر من الدكتور\n\nملاحظة: التجربة يعملها كل طالبين مع بعض كل اللابات وهذا جيّد بنظري 👍\nالكويزات :\nلا يوجد ، استبدلها بالـ pre-lab\nيطلب منك انك تعمله في البيت وتسلمه بداية كل لاب ، يهمه انك تحل 80% منه على الأقل ويعطيك عليه أو ينقصك درجة (أو نصفها على حسب) من درجة الريبورت لذلك اللاب …\nرأيي تجاه هذا الشيء:\nحاول تتعب على البري لاب وتحله صح ما أمكن … لأن الدكتور بنظري يقرأ حلك لاحقا ويرى مدى اهتمامك وفهمك لللاب فيزيدك نهاية الكورس في الدرجات.\nالبري لاب ياخذ وقت لحلّله (قد تصل الى ساعتين أوأكثر حسب فهمك وسرعته وحبك للمادة ولغتك الانجليزية لأنك بتقرأ اللاب وبتحل على أساسه … لكن تعبك مارح يضيع بإذن الله ) << هذا مافعلته والحمد لله درجة نهائية عالية جدا 🥊\nالمياجر:\nلا يوجد\nالفاينلات :\nأولا: تعطى 4 تجارب تذاكرها أحدها ستكون عملية\nالـ Written: جاب لنا 5 أسئلة كتابية … ثنين منها حسابات ،الاسئلة تعتمد على البري لاب لأنها بصراحة تحتوي على أسئلة كونسبت 👍\nلذلك بعد ما تحل البري لاب اختفظ بنسخة لديك عشان المذاكرة نهاية السمستر(صورهم بجوالك مثلا) لأنه مارح يرجع لك أي شي\nالتجربة: كومن… كل السكاشن تجيهم نفس التجربة من الديبارتمنت …ذاكر التجربة اللي بيجيبون عليها العملي وأسأل السكاشن اللي اختبروا قبلك عشان تكون بالصورة\nالقريد النهائي:\nB+\nالصوت:\nواضح\nإضافات:\nأنصح به (اذا كنت مستعد تحل البري لاب اسبوعيا لأن غالب الدكاترة يعطون كوزات بدل من ذلك)\nومثل ماقلت لكم أهم شي البري لاب هو اللي يحسسه انك مهتم\nوبالتوفيق لكم جميعا ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1161579-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mazen-khaled/68545/29", "user": "alhakem", "ts": 1357829601000, "tid": 68545, "pn": 29}}]}', 1357825177000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9056-chem101', 'stk-user9056', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f68545", "n": "Dr. Mazen Khaled", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Lecture\nTerm 122\n\nبنود التقييم :\n\nالتحضير :ورقة تلف على الطلاب ، وكل طالب يوقّع . مرة في الأسبوع السابع تقريبا ضاعت الورقة، جاب ورقة جديدة وكأن شيأ لم يكن. الطلاب يجون متأخر ولا يقول شي، وفيه بعضهم يطلع وهو ما يدري .\n\nطريقة الشرح :سلايدات + ليزر ( بوينتر )، ما يتحرك من مكانه. ياليته يقرأ السلايدات حتى. يمر عليها مرور سرييييير جدا جدا جدا ولا أفهم معاه شي.\n\nكنت أعتمد على الكتاب بنسبة 100%\n\nالكويزات :كويزاته كانت من الأولد اقزام. ليست بمستوى شرحه أبدا أبدا أبدا. كويزاته أصعب من مستوى شرحه.\n\nالمياجر:Common\n\nالفاينلات : Common\nالقريد النهائي: F\nالصوت: واضح جدا، وإذا الطلاب ما فهموا يتكلم لهم عربي .\nإضافات :\n\nالدكتور عنده بحوث وخرابيط ومؤتمرات وسوالف كثيره ومناصب .\n\nبس يا أخي ما يعرف يشرح أبدا أبدا أبدا .\n\nفي الحقيقة كان اعتمادي على الكتاب 100% ، وأحضر فقط للحضور .\nوأعرف الكثير من من يحضر لدرجة الحضور ويحضر كمستمع عند العرفج .\n\nنصيحتي لك ، لا تنزّل عنده.\nلو كنت ما تعرف للـ Self study لا تنزل عنده ولو تأجل المادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1234126-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mazen-khaled/68545/30", "user": "user9056", "ts": 1370953825000, "tid": 68545, "pn": 30}}]}', 1370953825000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3767-chem101', 'stk-user3767', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69110", "n": "Dr. W Forner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه Chem101\n\nالتحضير: بالورقة، لكن مرة قد لخمنا وحضر بالاسامي (مرة وحدة بالسمستر).\nطريقة الشرح: نفس السلايدات حقت الكتاب يجلس يشرحها… شرحة اعتبره عادي جداً…\nالكويزات: أتذكر انها مالتبل تشويس… و عبارة عن 5 اسئلة… وعادة ما تكون صعبة.\nالمياجر: كومن.\nالفاينلات: كومن.\nالقريد النهائي: C+\nالصوت: ممتاز ولكنته انجليزية وواضحة جداً.\nإضافات:\nما ادري ما عندي اضافات زيادة. المدرس ألماني الجنسية بس مو مبين عليه لأن لكنته انجليزية بحتة. بشكل عام المدرس عادي جداً.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p760123-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-forner/69110/16", "user": "user3767", "ts": 1294532314000, "tid": 69110, "pn": 16}}]}', 1294532314000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7794-chem101', 'stk-user7794', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101\nالتحضير :\nفي بداية السمستر يعطي الطلاب السجل و كل واحد يحظر نفسه … وأحيان يتأكد من العدد\nفي نهاية السمستر يحظر بنفسه …\n\nطريقة الشرح :\nممتازه في بداية السمستر لكن اذا ما شاف تفاعل يبدأ يسلّك\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح بنكهه يمنيه 🙂\n\nإضافات :\nينزعج جدا لما يشرح و في احد يتكلم … أخلااااااااااااااااااااااااااااااق 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1247742-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/36", "user": "user7794", "ts": 1374499676000, "tid": 69430, "pn": 36}}]}', 1374499676000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-emadba7-chem101', 'stk-emadba7', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركاته\n\nحاليا (Term 131 ) يدرستي الدكتور توفيق مادة CHEM 101\nبنود التـــــــقييم\n\nالتحضير : الدكتور غريب صراحة في موضوع التحضير, غير مهتم به ابدا, في بداية الترم كان ما يحضر اصلا ومع الميجر الاول بدأ يحضر في بداية الكلاس بالاسماء احيانا يكمل وفي الغالب يحضر سكشن واحد او 2 (احنا 3 سكاشن مع بعض) ولو جيت في نهاية الحصة مسكت ورقة التحضير وحضرت نفسك ما درى عنك عادي جدا, بالنسبة للتأخير ما يفكر فيه لو تتأخر ربع ساعة عادي تخش سلام سلام , انا تقريبا التأخير عندي شبه يومي عشانه اول كلاس 🙂\n\nطريقة الشرح : صراحة انا من النوع الي ما يركز وقت الشرح لكن اذاكر لمن ارجع ف ما ابغى اظلم الدكتور لكن بشكل عام شرحة جيد جدا ومتعاااون جدددا لو سألت اي سؤال يجاوبك , لكن انا اشوف انه المادة هذي سيلف ستدي يعني كون الدكتور مهو الافضل في الشرح هذي ليست سلبية في الاخير يعتمد على مذاكرتك\n\nالكويزات : تقريبا اسبوعيا كل ما نخلص شابتر نختبر فيه والكويزات لو فاهم المادة تعتبر متوسطة وعادية ومتساهل جدا في وقت الكوزات دائما كل ما يحدد موعد الطلاب ما يقصروا يا دكتور في ميجر ويا دكتور فيه كويز مدري ايش وعادي يأجل وهلم جرى D:\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: اعطيه A+\n\nالصوت: واضح جدا وممتاز\n\nإضافات : للطلاب الي يحبو الدكتور يكون روققاااان ومتفاهم ومتعاون هذا افضل واحد, والله ولا مرة تقريبا جا زعلان ولا مكشر ولا هزأ طالب مع انو كثير طلاب ما يحترموه ويطلعوا الجوالات وسط الكلاس, طبعا احنا في نص الترم ف ما نعرف كيف حيعطينا قريدات ولا! بالنسبة للشرح زي ما قلت يعتبر متوسط لكن في الاول والاخير حتى لو رحت لاحسن دكتور في القسم مستحيل يشرحلك المتيريال كله, المادة سيلف ستدي وتعتمد عليك\n\nتحيــــاتــــــي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1286873-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/38", "user": "Emadba7", "ts": 1384365162000, "tid": 69430, "pn": 38}}]}', 1384365162000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmer12-chem101', 'stk-kfupmer12', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 ( Term131 )\n\nالتحضير :\nبداية السمتستر فيه تحضير شبه يومي لكن بعد المناصفة تقريبًا …\nما يحضر إلا قليل و أحيانًا يحضر سكشن من اصل 3 او 2 على حسب المزاج =)\nو ما تفرق معه تجي متأخر أو لا و بنهاية الكلاس تقدر تحضر نفسك\n\nطريقة الشرح :\nمن السلايدات يشرح منها و بعض النقاط يوضحها على السبورة …\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح و مسموع للجميع\n\nإضافات :\nالمدرس حبيب و وسيع صدر و لو تسأله ألف مره بيجاوبك …\nو أفضل مافيه متعاون لدرجة خورافيه قلت له عندي ميجر ما اقدر اسلم الهوم وورك في وقته …\nقال متى ما خلصت سلمه =)\nولو تجيه الاوفس أور ما راح يقصر\n\nو بالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1287136-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/39", "user": "KFUPMer12", "ts": 1384418607000, "tid": 69430, "pn": 39}}]}', 1384418607000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imxpz-chem101', 'stk-imxpz', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 - Term 131\n\nالتحضير :\nمـزآجـي … آحيآنآ يحضر وآحيآنآ لآ , آحيآنآ يحضر كل آلسكآشن وآحيآنآ بعضهآ … فـ بدآية آلسمستر كآن يسمح للطآلب آلمتآخر يحضر نفسه. لكن لاحظ بعض الطلاب يحضرون آنفسهم بآيآم كآنوا غآيبين فيهآ (من نفس لون القلم) فـ منع ذآ الشيء.\nشديد فآلتحضيير آيآم الميآجر ونهآية الترم.\n\nطريقة الشرح :\nمن السلايدات … وآحيآنآ يستخدم السبورة.\nبآلنسبة لي آجده ممتآز فـ شرح بعض آلشبآتر مثل شآبتر 11 آلغآزآت وشآبتر 13 آلمحآليل , وجيد نسبيآ فـ بعضهآ.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح و مسموع للجميع\n\nإضآفآت :\nجدآ متعآون , طيب القلب … ممكن يأجل كويز آو هوموررك بنآءآ على حآلة الطلآب ( من ضغط ميآجر وكويزآت ).\nجدآ متوآضع … يحب يسأل الطلآب عن طريقة شرحه وآسلوبه فآلريستآشن … يحب يطور من نفسه … وهآذي اللي لآحضته آن مستوآه فآلشرح يتطر تدريجيآ من شآبتر لـ شآبتر.\nمشكلته الوحيدة… غير دقيق فـ (آلكلآس وورك) … وآحيآنآ يلخبط فـ شرح بعض الكونسبت للطلآب (كلهآ بنسبة ضئيلة)\n\nبآختصآر :\nآلدكتور توفيق صآلح … يعتبر من آفضل دكآترة قسم آلكميستري …\nليس آلآفضل , لكن آنصح آلطلآب فيه بحكم آنه يحآول يطور من آسلوبه وشرحه.\n\nو بالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1320036-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/41", "user": "iMxPz", "ts": 1389879430000, "tid": 69430, "pn": 41}}]}', 1389879430000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rygart-chem101', 'stk-rygart', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem101-151 lec\nالتحضير : أول اسبوع ما حضر ، بعدها يعطينا الأوراق و الطلاب يحضرون ، و لما شاف الطلاب الله يهديهم يحضرون غيرهم وكذا قام يحضر بنفسه\nبس آخر المحاضره يخلي الورقة على الطاولة و في بعض الطلاب يحضرون انفسهم .\nآخر الأسابيع صار يفتح الكمبيوتر و يحضر منه فـ صار م احد يقدر يحضر نفسه xD\n\nطريقة الشرح : طريقة الشرح رهيبة جدا و يعطيك امثلة واقعية و تطبيقات عليها و امثلة بسيطة تقدر تفهم الكونسبت منها .\n\nالكويزات : كل أسبوع كويز و الكويزات مستواها متوسط .\nفيه كم اسبوع الغى الكويز كان مجموع كويزاتنا 6 و حذف اقل اثنين !\n\nالقريد النهائي:ِ B+\n\nالصوت: واضح و تسمعه عادي ولو انك في الاخير\n\nهوموركات : مفيش\n\nإضافات :\nالمدرس رهيب و اخلااااق تتعب وانت تقول اخلاق لكن\n* حذف اقل كويزين فـ صار افرج سكشنا بالكلاس ورك مرتفع و وجا النورملازييشن زاد الطيب بله لذلك عطيته B+\nالدكتور اخلاقه جدا عالية و متعاون مع الطلاب و حاط رقمه في الويب ستي .\nبعض الطلاب يطقطقون بالجوال وهو يشرح و يكلمهم ب أسلوب جميل وهو قاعد يكلمهم تلقى واحد بعد يطقطق بالجوال !\nو لما ينتهي من كلامه معاهم تلقى واحد بعد يطقطق بالجوال او يهرج !\nو يرجع ينصحهم بـ أسلوب احسن من اللي قبل .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437728-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/43", "user": "Rygart", "ts": 1451721813000, "tid": 69430, "pn": 43}}]}', 1451721813000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamza_alnasser-chem101', 'stk-hamza_alnasser', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101- Term 151- Lec.\nبنود التقييم :\n\nالتحضير : أول السمستر ورقة توقيع تمر على الطلاب, وبعدين قام ينادي بنفسه.\nطريقة الشرح : من الSlides يشرح بطريقة عايدية وشرحه جيد,\nالكويزات : متوسطة إلى صعبة, أغلبها اختيار من متعدد\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: C+\nالصوت: Clear\nإضافات : أخلاقه عال العال, وتعاون مع الطالب بشكل كبير, ولكن شرحه مو إلى هناك.\n\nذاكر من الكتاب وحل أسئلته واترك عنك الNotes لأنها راح تتعبك في الميجر لأن في أسئلة تجي من الكتاب وليست موجودة في الNotes & Slides التوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440157-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/44", "user": "Hamza_Alnasser", "ts": 1453464900000, "tid": 69430, "pn": 44}}]}', 1453464900000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10703-chem101', 'stk-user10703', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lec-Term152-Chem101\nالتحضير :ينادي بالارقام يعرضها بالبروجكتر اول 5 دقايق من الكلاس والي يجي متأخر يجي يحضر في نهاية الكلاس احيانا يحضره واحيانا يعطيه ليت.\nطريقة الشرح :من السلايدات ويستخدم السبورة في التوضيح .\nالكويزات:اسبوعيا غالبا اولد اقزام بالنص او يجيب قريبا منها خيارات كلها يحذف اقل كويز منها واحد بس طبعا هو نظامه وسع صدرك في الكويزات يوزع ويطلع يتمشى ويرجع عادي .\nالمياجر:كومن\nالفاينلات:كومن\nالقريد النهائي:++++++++++++Aوبقوة يستاهل.\nالصوت:واضح ويتكلم عربي كثير.\nاضافات:هذا الدكتور اذا سجلت عنده اعرف انك محظوظ جدا لانه حبيب وخلوق ومحترم ومتواضع جداا وشرحه بطل يسوي الي عليه وأكثر ويساعدك ويسوي بونص ويزيد درجات يعطيك حقك وأكثر أفضل دكتور مر عندي للحين لانه متساعد مع الطالب بشكل كبير في نهاية السمستر سوى تكريم للطلاب الي جابوا 80%وفوق في كل الميجرين اه ياتوفيق صالح جعل ربي يوفقك وين ماكنت في ملاحظه أخيره للكورس وليس الدكتور الكورس يحتاج شغل كبير جدا جدا جدا ومذاكره اول باول لاني دخلت على ان الكورس سهل وبتطلع بقريد عالي حسب ماسمعت لكن تاخذون مقلب الكورس مب سهل وطويل والقريدات شحيحه جدا جدا لانه افرج وبالتوفيق للكل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452653-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/45", "user": "user10703", "ts": 1466700611000, "tid": 69430, "pn": 45}}]}', 1466700611000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alharthi999-chem101', 'stk-alharthi999', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nاول شي لا احد يدقق على الهمزات لان بيني وبينها عداوه :slightly_frowning_face: :zipper_mouth_face:\n\nCHEM101-151\n\nدكتور توفيق عبدوه صالح ❤️ ❤️ ❤️\nمن اليمن الشقيقة وراح تعرف من اول حرف ينطقه 😆 😆\nرجل قمة في الادب والاخلاق والرقي في التعاون مع جميع الطلاب … سبحان من رزقه طيبة القلب والصبر 🌹\nالتحضير : اول الاسابيع ورقة تمر على الطلاب… بعدين جا تشديد من الديبارتمنت على التحضير فصار يحضر بنفسه والسبب الثاني كان واجد من الطلاب يحضرون اخوياهم 😂\nطريقة الشرح : شرحه جدا ممتع … بالرغم من ان الماده شوي غثيثه لان فيها حفظ واجد الا ان الدكتور يخليها لك مادة ممتعة… يشرح من سلايدات ويحب يوضح اكثر بالسبورة وبالطلاب يعني يقوم كم طالب ويطبق عليهم 😂\nالكويزات : الكويزات اسبوعيه واذا حصل ضغط على الطلاب ويبون تاجيل ما يقصر ياجله عشان ما يضغطهم… الاسئله من الاولد اكزام او من الكتاب… :popcorn:\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت: واضح\nإضافات :\nالدكتور يهتم بمصلحة الطلاب كثيييييير ودايم يحب الي مركز معه والي مو مركز يروح الى عنده عشان ينتبه … ويحب الي يسال اذا ما فهم… انصحك تسجل عنده وتستمع مع هذا الرجل المحترم 👏 ❤️ ❤️ ❤️ ❤️ ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456021-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/46", "user": "alharthi999", "ts": 1472337305000, "tid": 69430, "pn": 46}}]}', 1472337305000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-chem101', 'stk-user11848', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : CHEM 101 - 191\n\nالتحضير : يوميا بداية الكلاس ومرات مايحضر ابدا\n\nطريقة الشرح : من سلايداته وشرحه ممتع ويضرب امثلة كثير ويضحك\nالكويزات : سهلة جدا\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح جدا\nإضافات : الدكتور قمة الاخلاق وحبييييييييب ويهتم لمصلحة الطلاب كأنهم ابناءه , لكن مشكلته كويزاته دايما سهله فالافريج للكلاس وورك مرتفع , الدكتور متساهل بتسليم الهوم وورك وما يكرفك وشاد حيله جدا , انصح فيه وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526000-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/50", "user": "user11848", "ts": 1601630848000, "tid": 69430, "pn": 50}}]}', 1601630848000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-asim_alharbi-chem101', 'stk-asim_alharbi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f69430", "n": "Dr. Tawfik Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور درسني chem101 ترم 242\n\nالتحضير : بداية الترم كان جدًا متساهل ، لدرجة نص الطلاب صاروا يجون على آخر عشر دقايق ويحضرهم ، في منتصف الترم صار يدقق واجد\nطريقة الشرح : بصراحة شرحه جدًا عشوائي وغير مفيد ، كنت اطلع من المحاضرة ماادري وش قال حتى ممكن الفكرة العامة للدرس مااعرفها ، اذا بتاخذ الكورس عنده غالبًا بتقضي المادة سيلف ستدي ، لأنه فقط يقرأ السلايدات ولا يحل أسئلة إلا ماندر ، وممكن يهنق مرات وهو يحل\nالكويزات : ماكانت من عنده دكتور الريسايتيسن هو المسؤول عنها\nالمياجر: من القسم\nالفاينلات : من القسم\nالقريد النهائي: اذا بتذاكر لحالك A+ اذا بتعتمد على شرحه c\nالصوت: ممتاز وواضح\nإضافات : الدكتور محترم وخلوق وحبوب جدًا لدرجة يجيب معه حلاو واللي يحشّر له ويجاوب صح يعطيه الحلاوه ، لكن عيبه الوحيد هو شرحه العشوائي جدًا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540268-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tawfik-saleh/69430/52", "user": "asim_Alharbi", "ts": 1755706398578, "tid": 69430, "pn": 52}}]}', 1755706398578, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5900-chem101', 'stk-user5900', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f78010", "n": "د . حسان نوري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه لاب كمستري 101\n\nالدكتور محترم وخلوق لكن عيبه الوحيد هو كثرة الكويزات اللي عنده\n\n+\n\nما يخلي الطلاب يطلعون قبل 5\n\nويخلينا نحل البري لاب عشان نآخذ وقت زايد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p943547-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/78010/20", "user": "user5900", "ts": 1323198165000, "tid": 78010, "pn": 20}}]}', 1323198165000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-l7ani-chem101', 'stk-l7ani', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f80958", "n": "د. أسامة البجيرامي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا نزلت عنده ريستيشن Chem 101 on term 91\nوبعدها نزلت عنده ليكتشر وريسيتيشن Chem 102\nبصراحه تعجز الكلمات عن وصف هذا الدكتور بصراحه أفضل دكتور مر على الديبارتمنت أو بالأصح على جامعتنا\nشرح ولا أروع تفهم الماده غصب عنك والأكسنت واضح بشكل كبير والصوت برضوه واضح لو تجلس بالاخير راح تسمعه ويقول لك لو فيه أي شي مو عاجبك إما بطريقة الشرح أو بالأكسنت يغيرهم لك أهم شي إنه يفهمك الماده بأي شكل من الأشكال\nوالكويزات سهله وتركز على زبدة المنهج\nيعني لو تذاكر من السلايدات والكويزات راح تجيب الفل مارك\nوبالنسبه للتحضير ورقه تمر على الطلاب وهو متأكد ان التواقيع اكثر من الطلاب ولكن أنا متأكد ان اللي ما يحضر هو اللي خسران لأني شفتهم على مر ترمين 91 و 92 الطلاب اللي تحت الأفرج هم الطلاب اللي ما كانوا يحضرون\nويحاول قد ما يقدر يعطي الطلاب بونص يضيفه لللإختبارات إما بكويز أو بحضور محاضره\nوالدكتور يقول لك لو فيه شي صعب عليك بأي ماده بس مر عليه بالمكتب أو لو تشوفه ماشي بس وقفه واسئله ما راح يقصر معك ويشرحه لك\nويتضايق لما يشوف طلابه زفتوا بالاختبار ويتضايق من الطلاب اللي ما يحضرون لأنه خايف على مصلحتهم ويهتم لمصلحة الطالب أكثر من الطالب نفسه\nومتى ما شاف اي واحد درس عنده يوقفه ويسأله عن أحواله وعن دراسته\nالقريد النهائي : أحس إني أظلمه لو أعطيه A+++++++++++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p740594-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80958/16", "user": "l7ani", "ts": 1291310009000, "tid": 80958, "pn": 16}}]}', 1291310009000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9412-chem101', 'stk-user9412', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f81025", "n": "أ. الشراع", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 131\n\nبسم الله الرحمن الرحيم\nوالصلاه والسلام على الرسول الكريم\n\nانا العاده ما احب اكتب عن دكاتره لكن هذا الشخص والله يستحق الاحترام والتقدير\n\nterm 131 chem 101 lap\nالأسم / عبدالناصر الشرع\nطالب ماجستير\nوالله اعلم سوري الجنسيه\n\nالمميزات:\n\n1 - الكويزات من البري لاب وما يخرج عنها ابدا (حلها في البيت واذا ما عرفت خش قوقل واكتب السؤال وحتجيك الأاجابه النموذجيه انقشها وتوكل على الله )\n\n2- يطلب منك تجربه واحده فقط تسويها واذا كانت طيبه يقلك امشي واذا النتيجه غلط يقولك سويها مره تانيه عشان لا تاخذ صفر\n\n3- اللاب يبدأ الساعه 1 الظهر كنا نخرج على الساعه 3 او 2.40 اكثر مره طولنا خرجنا على الساعه 3.40 دقيقه لكن التجربه كانت جدا طويله يعني بالعربي( يخرجك بدري )\n\n4- الفاينل لاب مويه بشكل غير طبيعي واغلب السكشن جابو درجات طيبه اعلى درجه كانت 81 واقل درجه 67 عشان عندو غياب\n\n5-الميكاب عندو جدا سهل لو كلمتو قلتلو عندي ميجر بعد 3 ساعات او 2 ساعتين يقلك تعال يوم ثاني ويزبطك\n\n6- لو سألتو بالعربي يرد عليك بكل اريحه ويقلك سبيك ان انجلش\n\n7- اول ما يبدأ اللاب يكتب الخطوات كلها على السبوره وبقلك اش تسوي بالزبط يعني ما حتتعب\n\nالله يوفقه وين كان\nنصيحتي نزل عنده وتوكل على الله وحتدعيلي بأذن الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318651-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/81025/5", "user": "user9412", "ts": 1389578271000, "tid": 81025, "pn": 5}}]}', 1389578271000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-chem101', 'stk-tryagain', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f81690", "n": "Dr. Musa Musa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور : موسى الموسى\nCHEM 101\nTerm 153\n\nبنود التقييم :\n\nالتحضير :\n\nالتحضير حسب العدد … إذا شاف الكلاس ممتلئ غالباً ما رح يحضر … لكن إذا شافه ناقص بشكل ملحوظ يحضر … وينادي بالأرقام آخر الحصة …\n\nطريقة الشرح :\n\nالترم كان صيفي والماتيريال كانت كبيرة فكان يشرح من السلايدات … لكن كان شرحه ممتاز لأبعد الحدود ويشرح كل صغيرة وكبيرة ويجاوبك على أي سؤال … متعاون بشكل كبير …\n\nالكويزات :\n\nسهلة جداً … يختبرنا كويز كل نهاية تشابتر … ويجيب أسئلة سهلة جداً لو كنت مذاكر … حتى لو مذاكرة سريعة … رح تجيب درجات عالية في الكويزات …\n\nالمياجر:\n\nكومون\n\nالفاينلات :\n\nكومون\n\nالقريد النهائي:\n\nA+ بدون أي منازع … والدكتور يستاهل كل خير والله …\n\nالصوت:\n\nعالي والاكسنت ممتاز …\n\nإضافات :\n\nالدكتور ممتاز جداً في كل شي … ويشهد على هالكلام إنو سكاشنه أعلى افرج … الميجر الثاني الافرج تقريبا 64 وفي سكشن عندو 73 …\nوأكيد لازم يكون خيارك الأول عند التسجيل … ونعمة كبيرة لو نزلت عندو …\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1455635-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/musa-musa/81690/18", "user": "TryAgain", "ts": 1471966363000, "tid": 81690, "pn": 18}}]}', 1471966363000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-chem101', 'stk-abdullah2015', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f81690", "n": "Dr. Musa Musa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده CHEM101 ترم 153\nالتحضير :\nحسب العدد في القاعة، إذا كان كثير ما يحضر وإذا كان قليل يحضر في آخر المحاضرة.\nطريقة الشرح :\nبالنسبة لي أشوف إن شرحه عادي جداً … ولأن الترم صيفي كان يمر على الماتيريال بسرعة\nبنظري تحتاج مجهود مضاعف برا الكلاس.\nالكويزات :\nكنت ماخذ عنده اللكتشر بس والكويزات في الريسيتيشن.\nالمياجر:\nكومون.\nالفاينلات :\nكومون.\nالقريد النهائي:\nC+\nالصوت:\nواضح.\nإضافات :\nأشوف الشباب يمدحوه في الOrganic Chemistry اللي هي CHEM201&202 وهو بعد كان يتكلم كثير عنها في محاضراته\nلكن شخصياً من خلال تجربتي معه في CHEM101 أشوف إنه عادي جداً وما هو أفضل الموجود لهذي المادة … مع احترامي له\nفي الأخير تبقى وجهة نظر شخصية وممكن يختلف معي غيري.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457549-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/musa-musa/81690/19", "user": "Abdullah2015", "ts": 1473793311000, "tid": 81690, "pn": 19}}, {"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده ريسيتيشن CHEM101 ترم 153\nالتحضير :\nما فيه تحضير.\nطريقة الشرح :\nيفتح أولد اقزامز بالبروجكتر ويحل في كل كلاس.\nالكويزات :\nمرة سهل ومرة متوسط ومرة صعب، حسب المزاج.\nالمياجر:\nكومون.\nالفاينلات :\nكومون.\nالقريد النهائي:\nB\nالصوت:\nواضح.\nإضافات :\nبدون.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457550-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/16", "user": "Abdullah2015", "ts": 1473793907000, "tid": 99859, "pn": 16}}]}', 1473793311000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osamahz-chem101', 'stk-osamahz', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f84077", "n": "أ. زكريا عبدالكريم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست عندة لاب chem101\nالتحضير: يعتمد على الريبورت … بس اذا تاخرت يحذرك كم مرة بعدين يخصم .\nطريقة الشرح: يشرح طريقة عمل الترجربة ويقسمها لعدة اجزاء اذا هي طويلة … واكثر الاحيان \"يلخبط\"ويقوم يصرف انه احنا اول لاب في الاسبوع. .\nالكويزات : none\nالفاينلات : الفاينل كان جزئين عملي وكتابي … العملي يبغالك تتذكر التجرية بس كان سهل …الكتابي انت وشطارتك في النقش 😉\nالصوت : بالنسبة لي كان مشكلة كبيرة كونة افريقي ويتكلم باللفة الانجليزية …افهمها 😐\nالقريد النهائي : D\nاضافات : كان شين وقوي عين بمعنى الكلمة … يعني لما يشرح التجربة يقوم يلخبط ويلف يمين وشمال … واذا جاء دورك وشافك موقف لو لدقيقه صاح عليك ويعطيك نظارت قوية …يعني لاهو اللي شرح ولاهو اللي فكنا من شرة …استغفر الله …بس لا تعطيه وجه وكمل …وكمان عند الريبورت يقسم مجموعات ولازم تنتبه للوحدات …\nطولت عليكم بس هذا الصدق 😐", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p783625-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/84077/8", "user": "osamahz", "ts": 1297123011000, "tid": 84077, "pn": 8}}]}', 1297123011000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedgs-chem101', 'stk-mohammedgs', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f94389", "n": "Dr. Nurudeen Odewunmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172 CHEM 101 lab\nالتحضير: يكون بالبري كويز في بداية اللاب.\nطريقة الشرح: يشرح بالتفصيل الشديد وأحيانًا يكون ممل، يستخدم السبورة وأغلب الأحيان يشرح بطريقة عملية “يورينا كيف طريقة التجربة”.\nالكويزات: سهلة كانت كلها ما عدا أول لاب من البري كويز اللي موجود بالكتاب. ركز على المعادلات اللي في البري كويز، يحبها.\nالفاينل: كان بسيط وأغلبه من البري كويزز اللي يعطيناها “القسم يحدد أربع تجارب نذاكرها”.\nالصوت: واضح بس ممكن تواجه مشاكل مع اللهجة عشانها أفريقية.\nإضافات: الدكتور مزوح ومتعاون مع إن شرحه طويل وأحيانًا يكون ممل صراحة. يكره الجوالات في وقت اللاب ويسميها شياطين. الدكتور جيد إلى ممتاز صراحة.\nالقريد النهائي: B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492274-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nurudeen-odewunmi/94389/9", "user": "MohammedGS", "ts": 1526226139000, "tid": 94389, "pn": 9}}]}', 1526226139000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-chem101', 'stk-abdulrahman.h', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f96572", "n": "أ. أوك سالم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا اخذت عنده ريسايتشن كمستري 101 ، وهذا التقييم مبني على هالشي …\n\nالتحضير :\n\nورقة تمر على الكلاس … التأخير البسيط ما يدقر عليه …\n\nطريقة الشرح :\n\nبصراحة مستواه ضعيف … يجيب مسائل عنده في سلايدات أو من الكتاب ويحلها بطريقة مرة ما عجبتني … وكذا مرة يغلط في أشياء مدري وش تبي ويصححون له الطلاب … يعني حسيته مو فاهم صح …\nدائما يكون محدد الأسئلة من قبل والاجابة مكتوبة عنده بورقة … يعطينا وقت نحل السؤال وبعدها ينقل الحل اللي عنده عالسبورة ويقول ، دو يو اندرستاند ؟\n\nالكويزات : متوسطة مائلة للسهولة أغلبها multiple-choice ، ومتعاون من ناحية تأجيلها إذا فيه ضغط على الطلاب …\n\nالمياجر: ---\n\nالفاينلات : ---\n\nالقريد النهائي: C\n\nالصوت:\n\nنبرته ترفع الضغط شوي وفيه بعض الحروف والكلمات ينطقها بطريقة غريبة … صوته لاهو عالي ولا منخفض ،، وسط\n\nإضافات :\n\nالأستاذ حبيب وأخلاق بشكل عام بس ما انصح فيه باللكتشر لأني أحسه مو فاهم وتوصيله للمعلومة سيء …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743466-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96572/7", "user": "Abdulrahman.H", "ts": 1292264965000, "tid": 96572, "pn": 7}}]}', 1292264965000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-chem101', 'stk-turky_al-dossary', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f99245", "n": "د. محمد يار", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خذيت معه chem101 ليكتشر بدون ريستيشن ولا لاب\n\nالتحضير :\nورقة تمر ،، وتقدر تحضر نفسك اخر دقيقه 🤠\n\nطريقة الشرح :\nممتازة ،، ويوصل المعلومة ،، بس اكثر الايام ما كنت احضر 😐 واذا حضرت افهم 🤪\n\nالكويزات :\nمو عندي ،، عند واحد يقال له عبد اللطيف\n\nالمياجر:\nكومن ،، بس اسوا ديبارتمن في وضع التركات ،، القس تقدر تجيبه من شكل الاجابات 😆 \" اطلق شيء \"\n\nالفاينلات :\nباقي ما اختبرت بس ان شاء الله سهل\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح ،، والاكسنت مو ذاك الزود بس بالنسبة لهندي يعتبر توووب\n\nإضافات :\nالمدرس حبيب وشريح ،، ونزل عنده وما راح تندم // وفالكم A// 🥰 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p841134-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99245/12", "user": "Turky_Al-Dossary", "ts": 1304682942000, "tid": 99245, "pn": 12}}]}', 1304682942000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idolatress-chem101', 'stk-idolatress', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه لاب chem101 بالصيف 103\nالتحضير :\nكالعادة اغلب اللابات التحضير بالريبورت\nطريقة الشرح :\nجداا رائعه\nالكويزات :\nأخذنا تقريبا 3 كوزات وكلها من البريلاب موجود في اللاب مانويل\nالمياجر:\n…\nالفاينلات :\nيحدد تقريبا 5 تجارب للنظري\nوتجربه واحده فقط للعملي وبسيطه مره\nالقريد النهائي:\nA\nالصوت:\nواااضح جدااا\nإضافات :\nللأمانه كان ممتاز وتعامله مع الطلاب تعامل طيب وكان يحفزنا بالبونص صررراحه أنصح به", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p903645-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/7", "user": "Idolatress", "ts": 1316250072000, "tid": 99859, "pn": 7}}]}', 1316250072000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-help_me-chem101', 'stk-help_me', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f99859", "n": "Dr. Othman Al Hamouz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101\nالتحضير :\nبالريبورت\nواهم شي لاتتاخر لان الكويز اول 10 دقايق واذا تاخرت ماراح يعيده لك\n\nطريقة الشرح :\nجدا جدا رائعة , يشرح ع السبورة كل شي بعدين يكتب ويشرح البروسيجر خطوة خطوة\n\nالكويزات :\nمتوسطة تقريبا\n\nالفاينلات :\nاسهل اربع تجارب يحددها للنضري\nواسهل تجربه يحددها للعملي\n\nالقريد النهائي:\nA++++++++++++ وبقوة\n\nالصوت:\nواضح جدا جدا\n\nإضافات :\nأفضل مدرس لاب مر علي\nوجه يشرح الصدر وانسان شريح وحبوب مرره ومايقصر لو طلبت مساعده منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1028653-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/othman-al-hamouz/99859/9", "user": "help_me", "ts": 1335390801000, "tid": 99859, "pn": 9}}]}', 1335390801000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zoroo-chem101', 'stk-zoroo', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f118602", "n": "د. شكيل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التقييم لــ كيمستري 101 ترم 112 … (ريساتيشن)\n\nالانطباع الأولي: حنا الحين في الأسبوع الرابع،، الصراحة هالمدرس بطل، خاصة في الأخلاق روعة لأبعد الحدود…\n\nنظامه: كويز كل أسبوع + واجب (لكن تونى بدري ما أدري إذا بيكمل باقي السمستر كذا)…\n\nكويزاته ملتبل شويس (متوسطة)،،\n\nسلام …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p990136-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118602/2", "user": "zoroo", "ts": 1329765389000, "tid": 118602, "pn": 2}}]}', 1329765389000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bb_aa33-chem101', 'stk-bb_aa33', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f118609", "n": "أ. وائل محفوظ", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "LAB Chem 101\n191\nالدكتور مرة ممتاز اللاب عنده سهالات يعني كنت أخرج ع 3:00 أو 4:00 بالكثير\nطبعا الافرج لازم يكون 75 عشان كذا اذا شاف الافرج عالي يدقق في تصحيح الريبورت\nطبعا هذا نظام الديبارتمنت مو من عنده\nالتجربة اللي فيها نار تسويها مع البارتنر حقك اما غيرها تشتغل وحدك غير أول وآخر لاب\nعموما أنصح بالدكتور جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517354-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118609/11", "user": "bb_aa33", "ts": 1574793455000, "tid": 118609, "pn": 11}}]}', 1574793455000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-chem101', 'stk-moh_ammed', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f182958", "n": "Dr. Wissam Iali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101-201 (تعليم عن بعد - كورونا)\n\nالتحضير: بصراحة التحضير عند د.وسام شيء غثيث جدا. يكون التحضير عنده على البلاك بورد ويفتحه لمدة دقيقتين أو أقل ويكون في الغالب مرتين في كل محاضرة.المشكلة التحضير ماله وقت محدد، لازم تكون مركز معاه لأنه يعلن عن التحضير بأوقات عشوائية.\n\nالشرح: كنت أركز معه شوي في بداية الترم بس ماعجبني الوضع لإني ماكنت أفهم ولا أستفيد،فصرت ما أركز معه وقت المحاضرة بعدين أذاكر لحالي أو إني أرجع لتسجيل المحاضرة.بشكل عام شرحه مو كويس (هذا رأيي عن شرحه في التعليم عن بعد بس ما أدري عن شرحه في الحضوري).\n\nالصوت: إنجليزيته لك عليها، وكثير من الكلمات يكون نطقه مضروب فيها.\n\nالتعامل:الدكتور حبيب وأخلاقه حلوة.\n\nالكويزات: ما أشوفها صعبة صعوبة تعجيزية، بس أنا درجاتي فيها كانت سيئة والله.\n\nالقريد النهائي: C or C+\n\nإضافات: - الدكتور يبذل كل مايقدر عليه بس عشان يفيد الطالب…تهمه مصلحة الطالب بشكل كبير،وهذا الشيء اللي يخليك تحترمه عشانه.\n- بالنسبة للتحضير…فيه طلاب يقولون ماقصر معهم في التحضير،يعني تغاضى عن الكثير في نهاية الترم.أنا بصراحة مدري لأني ماكنت أغيب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527481-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wissam-iali/182958/15", "user": "Moh_ammed", "ts": 1609572313000, "tid": 182958, "pn": 15}}, {"id": "stk-dr-f118609", "n": "أ. وائل محفوظ", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "lab CHEM 101-term 201 (تعليم عن بعد - كورونا)\n\nالتحضير: غالبا ينادي بالأسماء بعد مايخلص الشرح.\n\nالشرح: والله أتوقع إن غالبية الطلاب كانوا ساحبين ومايركزون ،التعليم عن بعد ممل وماتقدر تركز ،فيعني تقدر تقول شرحه ماله فايدة كبيرة.\n\nالصوت: تقريبا واضح.\n\nالكويزات:لايوجد.\n\nالقريد النهائي: C+ ،يمكن لو كان التعليم حضوري كان يستحق أكثر.\n\nإضافات: - الدكتور يشرح تقريبا إلى نص مدة اللاب أو أقل شوي،بعدين يخليكم تشتغلون على الريبوت. بعض الأحيان يسمح بالتسليم إلى نهاية وقت المحاضرة، وأحيانا يسمح بالتسليم إلى مابعد المحاضرة بكم ساعة،وأحيانا يعطيكم إلى نهاية اليوم.\n\n- اللاب عن بعد عبارة عن نكتة وماله فايدة تذكر،فأتوقع حتى لو تنزل عند هالدكتور أو عند غيره ماتفرق كثير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527483-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118609/13", "user": "Moh_ammed", "ts": 1609575182000, "tid": 118609, "pn": 13}}]}', 1609572313000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abaadi-chem101', 'stk-abaadi', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f180471", "n": "Dr. Majad Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: chem 101\nترم: 201(اونلاين)\n\nبنود التقييم:\nالتحضير: الدكتور كانت طريقته أنو عنده كل كلاس سؤال يحضر فيه مثلا : عاصمة مدينة محددة وهكذا. وأظن في كم يوم قليلة سحب ع التحضير.\nطريقة الشرح : كان حرفيا يقرا السلايدات طول الكلاس وشرحه كان ممل جدا. بس وكان يعني يجاوب ع الطلاب اللي يسألون ما كان عنده مشكلة.\nالكويزات : طبعا المادة لها كلاس ريسستيشن وكان الدكتور عنده 3 سكاشن (8 -9-10) بس هو سحب على الريسستيشن بكبره وخلاه في وقت محدد تم التصويت عليه من بعض الطلاب المناسب وهو كان الساعة 9 وكان ينزل الكويز ونختبر وخلاص نروح مافي شيء بعدها و كان في فترة ثانية للطلاب اللي ما قدروا يكونوا في الساعة 9 وهي الساعة 8 مساء وكان نفس الطريقة( باختصار الكويزز كان له فترتين).\nالمياجر : كومون.\nالفاينلات : كومون.\nالصوت : كان واضح الصوت بصراحة.\nالتقييم للدكتور : اعطيه من 10 ممكن 6.5.(ممكن اذا كانت حضوري يكون افضل)\nإضافات:\nالدكتور حبيب وطيب. صح انو في كويزات كان صعبة نوعا ما ويحط أسئلة يسميها (أسئلة نكبة) بس بشكل عام لا بأس. والدكتور بما انه شال الريسستيشن وحط فترتين كويزز صباح ومساء بس التزم بالاوفس اور الدكتور. بس للعلم والأهمية: كل ذي الشغلات صارت الترم 201 بس ممكن الدكتور يكون مختلف في الترم الجاي(اذا كان اونلاين) وكان الدكتور يجرب وش افضل طريقة يشوفها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527656-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majad-khan/180471/9", "user": "Abaadi", "ts": 1609934755000, "tid": 180471, "pn": 9}}, {"id": "stk-dr-f118609", "n": "أ. وائل محفوظ", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101\nترم 201 (اونلاين)\n\nبنود التقييم :\nالتحضير : الدكتور كان يحضر تقريبا بعد انتهاء الشرح. وتقريبا كان كل لاب يحضر .\nطريقة الشرح : كان صراحة فقط يقرا لاغير وصراحة ملل بشكل مو طبيعي لدرجة انو حتى لو اني مركز ح اطفش.\nما كان في كويزات\nالصوت صراحة نوعا ما ينفهم الدكتور. هو عربي بس اكثر والاغلب يتكلم انجلش طول اللاب. بس مثلا لو في شغلة صعبة تنفهم يقولها بالعربي وكذا يعني.\nالتقييم النهائي: صراحة ممكن اعطيه 5 من 10 ( ممكن كان بيكون افضل وافضل حضوري بس الاونلاين يخرب كل شيء)\nإضافات :\nالدكتور طيب ويجاوب ع الطلاب اللي عندهم أسئلة وكذا, و كمان الدكتور متساعد جدا من ناحية الديدلاين حق الريبورت، مثلا لو كان في مياجر عادي عنده لو تكلمونه عشان يمدد الوقت لين نهاية اليوم. وهو للعلم ما يحد الديدلاين حق الريبورت علطول اول ما يخلص اللاب , لا كان يعطي وقت من نفسه توصل لين ساعة او ساعتين تقريبا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527658-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118609/14", "user": "Abaadi", "ts": 1609936397000, "tid": 118609, "pn": 14}}]}', 1609934755000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silver2012-chem101', 'stk-silver2012', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر : 132\nالمادة : كمستري 101\n\nالتحضير :يوميا وماينسى ابدا , يكون التحضير ورقه تمررها للي جنبك وانتبه تحضر خويك بالريسايتيشن لان الرسايتيشن ياخذ سكشن واحد والعدد قليل جدا ويعدهم نهاية الكلاس ويتأكد , اما باللكشر حيث يتجمع اربع سكاشن تقريبا تحضر خويك او ماتحضره ماحولك احد بس بالنهاية حط انتباهه على كم طالب وبدا يدقق في حضورهم وينادي اسمائهم حتى باللكشر , التأخر يسمح بخمس دقائق وبعدها يقولك اكتب ليت جنب اسمك , بعد فترة لما زودوها الطلاب بالتأخير صار يغيب حتى المتأخرين , يحجر للي يقعدون على الجوالات اثناء اللكشر\nطريقة الشرح : سلايدات الديبارتمنت يشرح منها ويقراها بانجليزية ركيكة شرح مكسر وغير مترابط ومنظم يخليك تضيع , غالبا يكتب على السبورة القوانين الاساسية لكل شابتر بس مايشرحها كويس . المدرس يظن ان الطالب فاهم كل شي ويشرح شرح سطحي جدا والكل يسلك له وغالبية الكلاس مايفهمون معاه وتلاقيهم على الجوال\nالكويزات :كويزاته اسبوعيا لكل شابتر كويز والاسئلة غالبا تكون اسئلة بيسك جدا اذا حليت اسئلة الكتاب والرسايتيشن رح تقدر تحلها بسهولة , احيانا يعلن قبل الكويز انه فيه سؤال من الرسايتيشن رح يجيكم بالكويز ويعطيك رقم السؤال , يعني اذا انتبهت واشتغلت بالرسايتيشن رح تستفيد مع ان شرحه بالرسايتيشن مو ذاك الزود\nالمياجر: من القسم\nالفاينلات : من القسم\nالقريد النهائي: d+ .\nالصوت: واطي جدا وانجليزية ضعيفة وركيكة .\nإضافات :المدرس خلوق جدا بس الشرح وايصال الكونسبت جدا متواضع , احيانا اللي يفوته كويز يروح له المكتب يعيد لك اياه , شرحه لو رحت له الاوفس اورز مارح تستفيد منه لانه سطحي جدا بالشرح يبتر المفاهيم من اصولها ولايركز على حل المشكلة اللي تعاني منها بالفهم ويعطيك الزبدة مباشرة .\nيحط درجة بما يعادل درجة كويز واحد فقط على الاونلاين هومورك للسمستر كامل السمستر كامل بينما تلاقي الهومورك اونلاين اساسا ماعليه درجات من الديبارتمنت فقط موضوع لمجرد الممارسة .\nبالقريد النهائي مايدفك ابدا مهما كان .\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373414-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/4", "user": "silver2012", "ts": 1401294224000, "tid": 152614, "pn": 4}}]}', 1401294224000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ibr2h1m-chem101', 'stk-ibr2h1m', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-term172\n\nالتخضير: ورقة تمر على الكل\n\nالشرح: سيء جدددددددا ما يفهم حاجة كأنه يتكلم مع نفسه\n\nالكويزات: يجيب نفس اسئلة السامبل بروبلمز او التشيك بوينت او الهوموركات بس يمكن يغير الارقام\n\nالمياجر + فاينلات : كومن\n\nالصوت: يجيب النوم بالذات اذا كانت القاعة كبيرة\n\nالقريد النهائي: F\n\nاضافات: الدكتور طيب جدا كمعاملة لاكن كشرح سيء جدا جدا ما يفهم حاجة مع ان المادة سيلف ستدي بس لازم تكون فاهم شي عشان تحل\nو اساسا اغلب دكاترة Chem101 ماش", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491106-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/9", "user": "ibr2h1m", "ts": 1524040695000, "tid": 152614, "pn": 9}}]}', 1524040695000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11369-chem101', 'stk-user11369', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 - term 181\n\nالتحضير : ورقة يمررها.\nالشرح : سيئ وكلام فاضي ويشرح قشور القشور.\nالصوت : هادي يجيب النوم بقووووووووة.\nالتصحيح : سيئ جدًّا .\nالجريد النهائي : F-. ولو في أقل من F عطيته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503290-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/10", "user": "user11369", "ts": 1544078416000, "tid": 152614, "pn": 10}}]}', 1544078416000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-engineer2013-chem101', 'stk-engineer2013', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f152615", "n": "أ. احمد ندى", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا انا نزلت معاه لاب chem 101\n\nبنود التقييم :\n\nالتحضير :\n\nيحضر في بداية اللاب\n\nطريقة الشرح :\n\nشرحه مفصل جدا لدرجة ان يأخذ ساعة من اللاب بس شرح\n\nالكويزات (البري لاب) :\n\nيختار أسهل سؤال أو سؤالين وبعض الأحيان تكون اوبن بوك\n\nالقريد النهائي:\n\nB\n\nالصوت:\n\nواضح بس الأكسنت لك عليه\n\nإضافات :\n\nالأستاذ أحمد متعاون جدا إذا كلمته في الأوفيس\n\nومتساهل في التصحيح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1358041-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/152615/6", "user": "EngiNeer2013", "ts": 1398547861000, "tid": 152615, "pn": 6}}]}', 1398547861000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9534-chem101', 'stk-user9534', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f152615", "n": "أ. احمد ندى", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب كيمستري 101\n\nمتساهل جداً ومتعاون وعادي لو غلطت بالريبورت مابدقق واجد\n\nأنصح فيه اذا أنت تبي تسلك وماتبي تعقيد وشرح طويل , اذا تبي فهم وتجارب تفهمها دور غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1458859-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/152615/8", "user": "user9534", "ts": 1474914735000, "tid": 152615, "pn": 8}}]}', 1474914735000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kjl90-chem101', 'stk-kjl90', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 181\nCHEM 101\nLAB\n\nاول شي الدكتور يكتب على السبورة التجربة والمعادلات اللي راح نستخدمها ويسمح بالتأخير حتى 10 دقايق.\nبعد ما يبدأ الكلاس ب 5 دقايق يقولنا ابدؤوا البري لاب كويز\n(مرة قالنا ابدؤا بتجربه رقم 25 وبالغلط فتحت 24 وقعدت احل وبعدها اكتشفت ان الشعب كله يحل 25 الا انا كلمت الدكتور الله يجزاه بالخير وعطاني ربع ساعة احل فيها الكويز)\nوبالنسبة للكويز فهو دائما يقولنا حلوا اول صفحة او اول سؤالين بس.\n-\nوتصحيحه ما تدري كيف مرة في تجربة قال فيها كل اثنين مع بعض المهم انا خذيت 10 واللي معي اخذ 8 مع اننا كاتبين نفس الأشياء و نفس كل حاجة، حتى بالكويزات اذكر مرة عطانا سؤالين و السؤال الاول فيه فقرتين والسؤال الثاني فيه حول 4 فقرات انا اخطأت في السؤال الثاني في فقرة جوابها بسيط جدا from colorless to pink انا كتبت pink و عطاني بالكويز 6 من 10. أتوقع والله اعلم انه يسوي كذا عشان ينزل الافرج.\nو بالنسبة للفاينل فهو صفحة وحدة وجه وقفى عبارة عن 3 معادلات وسؤال عن لويس ستركشر والزاوية واسم الشكل وسؤالين صح وخطأ و سؤال علل مو مثل بعض الدكاترة يعطون طلابهم فاينل 4 صفحات تهد الحيل\n--\nالدكتور ميزته انه متساعد جدا وقت التجربة ويعلمك وش تسوي اذا سألته ولكن اذا جيت تسأله عن اجابتك النهائية راح يسلك لك ويقلك It’s correct\nوأيضا الدكتور يسمح بالخروج اول ما تخلص اللاب\n\nتقييمي للدكتور\n\nA+++++++\nاي واحد يشوف سكشنه فاتح ينزل عنده بدون تفكير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502930-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/6", "user": "kjl90", "ts": 1543290280000, "tid": 172597, "pn": 6}}]}', 1543290280000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahmankfupm-chem101', 'stk-abdulrahmankfupm', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101\nTerm212\n\nالتحضير :عن طريق رابط رافعه على التيمز يفتح بداية الكلاس او نهايته\n\nطريقة الشرح :شرحه سيء جدا يقعد يقرا لك السلايدات وتطلع من الكلاس مانت فاهم حاجة\n\nالكويزات :سهلة جدا لدرجة انخسفنا خسف قوي بسبة النورم\n\nالصوت:جدا واطي يبيلك تكون عنده اول واحد قدام\n\nإضافات :الدكتور جدا طيب ومتساهل مع الطلاب ويساعدك لو جيت تسأله ومايقصر\n\nالتقييم النهائي :٥/١٠ والسبب اخلاق الدكتور ولا كان عطيته ١", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534466-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/9", "user": "Abdulrahmankfupm", "ts": 1653590754000, "tid": 172597, "pn": 9}}]}', 1653590754000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulsalam_ahmed-chem101', 'stk-abdulsalam_ahmed', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 - term 212\nLec\nالتحضير : رسل لنا رابط بداية الترم و في كل حصة يفتحه اول ربع ساعة من الحصة وتسلم تحضيرك فيه ، عطى كل طالب غيابين بدون خصم\nطريقة الشرح : ضعيفه الى متوسطة ، ما احس فهمت منه شي اغلب الدروس بل يمكن كلها من شرح العرفج على اليوتيوب بحكم ان الكورس يعتبر سيلف ستدي ف ما يهم مين دكتورك\nالكويزات : سهله الى متوسطه بس هالشي نكبنا بسبب النورملايزيشن ونقصنا درجات بسببه لان افرج سكاشن عبدالملك كانت مرتفعه واجد\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B ، الدكتور كان قمه في الاخلاق ومتساعد بس عيبه الشرح ما كان ذاك الشي\nالصوت: صوته كان واطي حيل وانا كنت جالس في النص ف مادري عن اللي كانوا ورا\nإضافات : نصيحة اذا بتنزل عنده شوف الدرس من عند العرفج في اليوتيوب بعدها روح حصت عبدالملك وراجع اللي اخذته او حل اولدات عليه .\nبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534468-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/10", "user": "Abdulsalam_Ahmed", "ts": 1653591236000, "tid": 172597, "pn": 10}}]}', 1653591236000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-chem101', 'stk-user12137', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 - term 212\nLec\nالتحضير : يرسل لنا رابط في التيمز في كل حصة يفتحه اول ربع ساعة من الحصة واحيانا يخليها في نهاية الحصة ، اعطى كل طالب غيابين بدون خصم مثلما ذكر الاخ\n\nطريقة الشرح : الدكتور شغلته يقرأ السلايدات مع شوية شرح خفيف ,بمعنى شرحه ضعيف\n\nالكويزات : سهلة جدا بل تافهة فالنورملايزيشن لعب فينا لعب افرج سكاشنه كانت مرتفعة اغلبهم في ال8 من 10 او ال8 ونص\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت: صوته خفيف نوعا ما فما بينسمع عدل اذا قعدت في آخر القاعة\n\nالقريد النهائي: C\n\nإضافات :الدكتور طييييييييييييب جدا جدا واخلاق ومتساعد ما شاء الله يعني ما اظن احد يكرهه بالعكس حبيب ولطيف, ويخليك تقعد بالجوال في حصته وما بيقول شيء لكن تحسه يزعل منك اذا سويتها , تقدر تغيب وتحضر من السكن وما بيقول شيء, نص الكلاس كان غايب آخر الايام ومع ذلك ما قال شيء والله رجال محترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534656-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/11", "user": "user12137", "ts": 1655359103000, "tid": 172597, "pn": 11}}]}', 1655359103000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-chem101', 'stk-someone33', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172597", "n": "Dr. Abdul Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nCHEM101- Term212\n\nبنود التقييم :\n\nالتحضير : رابط بالتيمز بدون كلمة سر او اي شي تدخل وتحضر\nطريقة الشرح : يستعمل سلايدات الكتاب وللاسف يقراها ولا يضيف اي نقاط خارجيه تربط الدرس بالحياة اللي نعيشها\nالكويزات : نسخ لصق اسئله الكتاب اللي تعتبر سهله جدا\nالصوت: واضح بس يجيب النوم\nإضافات : الدكتور ميزته الوحيده اخلاقه لو تساله عن شيء مافهمته يحاول يشرح لك لين ما تفهم والتحضير والكويزات كانت سهله لدرجة ان افرج الكوزات وصل عنده في السكشن حقي 82 ف شقنا النورم\n\nالتقييم النهائي : c عشان اخلاقه بس\n\n---------------------------------------------------------\n\nالتحضير : على قناة تيمز يرسل رابط قوقل فورمز وتدخل بداية الحصة وتحضّر نفسك، كان قليل جدًا عدد الحضور والاغلب يحضرون نفسهم من تيمز ويذكرون بعض في القروب. الريسايتيشن واللكتشر نفس الطريقة بس فرق ان اللكتشر وقتها ثابت والريسايتيشن على حسب المزاج اثناء الحصة.\nطريقة الشرح : يشرح من السلايدات العامة للمادة وشرحه يجيب النوم المادة اذا بتنزلها عنده تذاكرها وتفهمها بنفسك، اذا رحت له اوفيس اورز بيتعاون معك.\nالكويزات : اختبرنا ٨ كويزات وحذف اقل درجة، اسئلته اسهل من المياجر بكثير، مستواها على مستوى الاسئلة المباشرة للكتاب، اذا جيت تذاكر الكويز يكفي انك تفهم و تتدرب على التشيك بوينتس اللي في الكتاب.\nالصوت: صوته هادئ وهذا اللي يخليه يجيب النوم اذا بتحضر احضر وخلك قريب ولا قل له يرفع صوته.\nإضافات : انحش، لاتنزل عنده الا اذا منحد على اخرك ومستعد تذاكر وتفهم المادة بمجهودك.\nالتقييم النهائي : D، بس لانه محترم مع الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535035-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-malik/172597/13", "user": "SomeOne33", "ts": 1660607338000, "tid": 172597, "pn": 13}}]}', 1660607338000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10879-chem101', 'stk-user10879', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172598", "n": "Dr. Al-Harbi Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 162\n\nانا شخصيا زبال في الكمستري ف ممكن يكون هو رهيب والمشكلة من عندي\nلكن انا حذفت الترم ونزلتها بعدين مع المعلم\nواكتشفت ان الرجال هذا شرحه زبال درجة اولى\n\nالشرح معدوم وغير مرتب ولارح تفهم حاجة\nالتحضير ورقة تمر واحيانا يمسكها وينادي اشخاص واذا طلعت غايب واحد حضرك ياويلك ياسواد ليلك\nالكويزات من اسهل مايكون لكن النظام نورمالايزيشن\nالمياجر كومون\nالصوت جيد\nالهومورك يقلك خش على صفحة الكمستري واختار اولد اكزام وحله حل كامل وسلمه\nالرجال طيب واخلاق لكن ما انصح احد ينزل معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479904-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-harbi-ahmed/172598/6", "user": "user10879", "ts": 1504957827000, "tid": 172598, "pn": 6}}]}', 1504957827000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mqr-chem101', 'stk-mqr', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172598", "n": "Dr. Al-Harbi Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 -171\n\nالتحضير :كانت ورقة تمر على الطلاب\n\nطريقة الشرح : الشرح كان يقرا من السلايدات ويوضح النقطه اللي مو واضحه في السلايدات و المدرس اذا شافك مفهي يداهمك بالسؤال .\n\n+ الكيمياء self study ما يحتاج الدكتور يشرحها لك\n\nالكويزات :كانت كوزاته متوسطة الى صعبة غالبا يجيب الاسئلة من نهاية كل شابتر.\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات : المدرس جداً حبيب وفلاوي في الكلاس ويحب يطقطق والحصة ما تنمل منها و اذا رحت له في المكتب بيحاول يفيدك بكل الطرق الممكنه . وانتبه تخلي احد يحضرك لانه بعض المرات فجاءةً يحضر من جديد هو بالورقة واللي يصيده ي ويله .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493191-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-harbi-ahmed/172598/8", "user": "mqr", "ts": 1527561907000, "tid": 172598, "pn": 8}}]}', 1527561907000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mechanicalism-chem101', 'stk-mechanicalism', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172598", "n": "Dr. Al-Harbi Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 - 181\n\nالتحضير : ورقه تمر بين الطلاب… متساااهل جدا ولو تدخل قبل نهاية الكلاس بعشر دقايق مايقولك شي اضافة الى ان بعض المرات ينتهي الكلاس ويبقى اكثر من طالب ماوصلته ورقة التحضير ف يكنسل التحضير لذاك اليوم. انتبه تحضر خويك لان بعض المرات يحضر بالاسماء باخر الكلاس وقفط كثارين خلال السمستر.\nطريقة الشرح : سيييييييىئ الى ابعد درجه .\nالكويزات : كانت صعبه ومرات يجيبها من المياجر القديمه لكن من حظنا ان الاغلب جايب العيد ف استفدنا من النورمالايزيشن.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: واضح ولكن انقليزيته لك عليها شوي\nإضافات : الدكتور كشخص حبييب ويعاملك كانك خويه وينكت واجد خلال الشرح ولكن وش راح تستفيد لو كان شرحه صفر عالشمال ؟! من رايي اذا تبغى تاخذ الماده كسيلف ستدي وتعامل كلاسات الكيمستري كـ “بريك 40 دقيقه” ف الله يوفقك وسجل معه غير كذا دور واحد غيره.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503977-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-harbi-ahmed/172598/9", "user": "Mechanicalism", "ts": 1545588479000, "tid": 172598, "pn": 9}}]}', 1545588479000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aabasem-chem101', 'stk-aabasem', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101\n\nبنود التقييم :\n\nالتحضير : ورقة تمر على الطلاب وهو يشرح\nطريقة الشرح : من السلايدات , ممتازة و فيها جداول و صور مأخوذة من الكتاب و تمارين بسيطة تشرح لك الفكرة\nالكويزات :من متوسط إلى صعب , أحيانا تجي من الأولد اقزامز\nالمياجر:كومن\nالفاينلات : كومن , ما بعد أختبرنا\nالقريد النهائي: A\nالصوت: هندي بالبداية صعبة و بعدين تتعود , يعني مثال : week ينطقها veek\nإضافات : حبيب و أخلاق و يحاول يساعد الطالب و يحفزه , هوموركاته فيها تريك , لو بعيد الكيمياء نزلت عنده مرة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1447753-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/3", "user": "aabasem", "ts": 1461987262000, "tid": 172599, "pn": 3}}]}', 1461987262000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-chem101', 'stk-to_be_engineer', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 101 -171\nالدكتور يفضل نناديه مستر جعفر\n\nالتحضير : ورقة تدور على القاعة … لو تجي اخر خمس دقايق تقدر تحضر نفسك … اخر السمستر شاف ورقة التحضير فيها 80 طالب والحضور حول 40 انصدم خوينا وقال اللي موجود حاليا يجي يوقع جنب اسمه قدامي … ما أدري اش صار للي صادهم.\nطريقة الشرح :يشرح عن طريق سلايدات رهيبة هو يسويها يجيب الزبدة من الكتاب ويضيف عليها اشياء من بره وكانت معظم الوقت تغني عن الكتاب ( بس لازم ترجعله للاسئلة وبعض الجداول المهمة )… اذا فيه مسألة طويلة يحلها على الصبورة … يجاوب على اي سؤال ممكن تطرحه …يربط الاشياء الغير واضحة بأشياء في الحياة الواقعية فتصير واضحة (مره جاب العيد لانه متعود يدرس في جامعات مختلطة 🤣)… دايم ينبه على التريكات اللي تجي في المياجر .\nالكويزات : الكويز الواحد ما ينزل عن خمس اسئلة بصعوبة متدرجة (نصها اولد اقزام ) … خيارات ويقولك ورني شغلك …حل الاسئلة اللي في نوتة انور الجمل للتشابتر وان شاء الله يكون سهل عليك (في اسئلة جت في المياجر مشابهة جدا للاسئلة اللي جابها وفي سؤال اعتقد انه جاء بالنص).\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي :B+\nالصوت: لهجة هندية في البداية بتتعب لكن عطه اسبوع و بتتعود بس حاول تجلس قريب منه ( اذا لغتك مو جيدة بتتعب معاه طول السمستر).\nإضافات :\nراعي ضحك عليه ضحكة الله وكيلك تقلب الكلاس فوق تحت 😀… كلاسة خفيف ودايم ننكت عليه وينكت علينا …عطانا اوف بعد الميجر الاول والميجر الثاني واخر اسبوع ما حضر …\nاذا عندك شي مو واضح او مسألة اولد اقزام ما فهمتها روح طب عليه في المكتب بيفيدك كثير … انا كنت اجيه مره كل اسبوع… بعض الطلاب اذا الدكتور مو عربي ما يروح الاوفس خوفا انه ما يفهم كلامه… صدقني اي احد بيستمر على هذه العاده بيتعب في الوظيفة … حاول تحتك من الحين وبتشوف الثمار بعدين.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493113-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/7", "user": "To_Be_Engineer", "ts": 1527455750000, "tid": 172599, "pn": 7}}]}', 1527455750000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-naaif-chem101', 'stk-naaif', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**CHEM 101 \\- 171** التحضير : ورقة التحضير يرميها بين الطلاب من بداية المحاضرة إلى نهايتها يعني لو تجي آخر دقيقة تحضر نفسك وبرضو لو خويك حضرة الترم كامل ما درى عنك ( بس عاد لا تفلها ).\n\nطريقة الشرح : سلايدات يقلبها ويقرأ فيها لأن المادة سلف ستدي بحته يعني اذا ما أشتغلت أنت راح تأكلها، الدكتور يفرق معاك في ذا الكورس في التحضير والكويزات.\n\nالكويزات : ناااار بس تجهزك للميجر مزبوط لانه يقول أفتح أربعة أو خمسة أولد اقزام وأنسخ أسئلة للكويز.\n\nالمياجر : كومون\n\nالفاينلات : كومون\n\nالقريد النهائي : A\n\nالصوت : واضح بس هو بنقالي مو هندي زي ما يقولون الشباب بس دارس في الهند، محاضرتين وبتتعود على صوته.\n\nإضافات : الدكتور جيد إذا يناسب وقتك والكورس ذا نزل، والدكتور تخصصه كيمياء عضوية داهية في تخصصه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501559-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/8", "user": "Naaif", "ts": 1540814019000, "tid": 172599, "pn": 8}}, {"id": "stk-dr-f180471", "n": "Dr. Majad Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**CHEM 101 \\- 172** التحضير : مرن ويرمي الورقة بين الطلاب ولو جيت متأخر ثلث ساعة ما كلمك\n\nطريقة الشرح : بحكم ان المادة سلف ستدي غالبًا الشرح يقرأ سلايدات ويحل بعض الأمثلة ويعطي الطلاب فرصة يحلون\n\nالكويزات : من متوسطة إلى صعبة على حسب الأفرج وحريص على طلابه\" لدرجة اني فوتت كويز ولم جاء الكويز اللي بعده وانا عارف نظام الجامعة ما تعيد الكويزات بدون عذر لكن هو جاء كلمني وقال لو تبغى تختبر تعال المكتب \" حبيب يعني\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: A+\n\nالصوت: واضح، جنسيته باكستانية وعنده الجنسية البريطانية وكل دراسته من الابتدائي للدكتوراه في بريطانيا حتى تحس اللهجة حقه بريطانية مضبوطة من أطلق اللهجات اللي بتسمعها من هنود وباكستانيين رهيبه فعلًا\n\nإضافات : الدكتور ما شاء الله عنده قوة حفظ يعني في ظرف اسبوع يكون حافظ طلاب سكاشنه بالاسم والصورة وفِي المياجر والفاينلات يجلس حول طلابه ويساعدهم لدرجة ما باقي الا يقول له الإجابة \" وانت في نص الميجر \" وخلوق ومتعاطف بزيادة مع الطلاب ويحب يساعد باللي يقدر عليه وبرضو فلاوي ما تطفش من خشته، الزبدة لو حصلته ويناسب وقتك نزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501760-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majad-khan/180471/2", "user": "Naaif", "ts": 1541126660000, "tid": 180471, "pn": 2}}, {"id": "stk-dr-f172600", "n": "Dr. Abdulkadir Tanimu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 lab- T172\nتحضير : متساهل وحبوب\nطريقة الشرح : يشرح التجربة بالتفصيل على السبورة\nالكويزات : من حق الكتاب ويختار الأسهل\nالمياجر:-\nالفاينلات :-\nالقريد النهائي: A+ ولو فيه زود يستاهل\nالصوت: واضح جدًا\nإضافات : المحاضر هذا شيء استثنائي ما شاء الله عليه متعاون وحبوب وفلاوي وشبابي يعاملك كأنك زميله وأنت بالفعل زميله لأنه هو طالب دكتوراه ما شاء الله الله يوفقه ومع كتابة هذا التقييم أتوقع يكون أخذها، ملاحظة أخيرة الدكتور من الجنسية النيجيرية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510551-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdulkadir-tanimu/172600/7", "user": "Naaif", "ts": 1559558015000, "tid": 172600, "pn": 7}}]}', 1540814019000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkz-chem101', 'stk-mkz', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 -192\n\nالتحضير : يرمي ورقة بين الطلاب ومرات يحضر بنفسه\n\nطريقة الشرح : سلايدات يقراها على الطلاب ويربط الدرس مع تطبيقات في الحياة. بس من بعد ما صارت الدراسة اونلاين محد صار يفهم عليه.\nالدكتور مايعترف بالسبورة, المسائل اغلبها يشرحها بالكلام و لما يكتب بالسبورة خطه ماينفهم هههههههههههههههه\n\nالكويزات : الكويزات اغلبها MCQ .الكويزات اللي على شابتر واحد تكون صعبة, وفيه الكويزات اللي على شباترين هذي تكون سهله. اغلب الاسئلة من الاولد اقزامز\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: C+\n\nالصوت: لهجته غريبه بس بتتعود مع الوقت\n\nإضافات : الدكتور محترم جدًا و اخلاق مررررره وحبيب. طبعًا شرحه عادي جدًا و فيه دكاتره افضل بكثير. لكن المادة سلف ستدي, يعني اذا مالقيت غيره مافي مشكله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521724-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/9", "user": "MKz", "ts": 1588463407000, "tid": 172599, "pn": 9}}]}', 1588463407000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azizlake-chem101', 'stk-azizlake', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172599", "n": "Dr. Mohammad Abu Jafar Mazumder", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term192 (نص الترم أونلاين)\n\nChem101\n\nالتحضير\n: يقرا الأسماء واحد واحد بالورقة نهاية الكلاس أي واحد يقدر يحضرك بس إذا شاف العدد قليل والحاضرين كثير ياويلكم - طريقة الشرح\n: مادة Chem101 معروفة بأنها تعتمد على دراستك مع نفسك فلا يهمك شرح الدكتور. بس الدكتور جعفر شرحه 0 عالشمال، أول مرة أقيم شرح دكتور زي كذا بس والله ما أنصحك حتى تركز معه تضيع وقتك فقط. يفتح السلايدات حقته ويقراها قراءه وإذا فيه مسأله يحلها عالسبورة مايقراها نملة. الزبدة لو تقدر تجي الكلاس وتذاكر بالدفتر بنفسك أحسن. - الكويزات\n: صعبة شوي مع أني مذاكر زين إلى أنه يجيب كم سؤال سهل وسؤال صععب. - المياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: D\n\nالصوت\n: بنغالي لهجته ثقيلة حتى أني سويت دفتر أحاول أترجم بعض الكلمات اللي ينطقها كلمة ثانية تماماً! - إضافات\n: الدكتور حليل وكذا بس لاتحرص عليه إلّا إذا وقته مناسب جداً…لأنه أصلاً هو متخصص بالبحوثات واللاب مو ليكشرز وشرح حتى مايحطونه بالاوفيرينق الا اذا صار زحمة مرة. بالكلاس مابتفهم شي أبداً والصراحة صار لي كم موقف بالأوفيس يعني شوي ما أعجبني، كم مرة جيت الأوفيس هاورز ومالقيته موجود وإذا لقيته يقول مشغول مشغول وإذا ما قال مشغول يشرح لك بدون نفس وإذا شرح لك ماتفهم علييه ولاااشي! على عكس الدكتور القدير د.عبدالرحمن العرفج إذا رحت له بالأوفيس يرحب فيني مع أني مو من طلابه ويشرح لي بالتفصيل شرح رائع! الله يحفظه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525802-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-abu-jafar-mazumder/172599/11", "user": "AzizLake", "ts": 1600624385000, "tid": 172599, "pn": 11}}]}', 1600624385000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_3zah-chem101', 'stk-abo_3zah', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172600", "n": "Dr. Abdulkadir Tanimu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 LAB 181\n\nالتحضير : متساهل جداً حتى ينتضر تقريباً ربع ساعه الين يجون كل الطلاب\n\nطريقة الشرح : يبدأ بمقدمه طويله يربط فيها بين التجربة و الحياة اليومية بعض الاحيان تكون ممله، بعدها يشرح الجزء العملي و في الاخير يكتب الخطوات على السبوره عشان لو نسيت\n\nالكويزات : نفس الي في الكتاب يحدد كم سؤال\n\nالمياجر:-\n\nالفاينلات :-\n\nالقريد النهائي: A\n\nالصوت: واضح جداً و اكسنت مفهوم\n\nإضافات : الرجل خلوق و يتكلم معاك كأنك زميله. واذا نسيت اللاب كوت يقلك روح البسه و تعال مهو من النوع الي يغيب عليه. يعيبه انه يطول في الشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504699-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdulkadir-tanimu/172600/4", "user": "abo_3zah", "ts": 1546968298000, "tid": 172600, "pn": 4}}]}', 1546968298000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f80-chem101', 'stk-f80', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f172600", "n": "Dr. Abdulkadir Tanimu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab CHEM101 - 182\n\nالتحضير : ينتظر الى ربع ساعه الى أن يكتمل عدد الطلاب , ما عمره غيب أحد متأخر\nطريقة الشرح : يكتب الاهداف عالسبورة بعدين معلومات اثرائيه و استرجاع معلومات سابقه و تعزيز معلومات اخذتها بالليكشر + مرات يعطيك تريكات تنفعك مع المسائل , بعدها يبدأ يشرح التجربه و يكتبها على السبورة .\nالكويزات : نفس حقت الكتاب يختار منها السهل و نكاسره اذا حط شي صعب و يغيرلنا السؤال\nالمياجر: مافيه\nالفاينلات : كويز الفاينل كان اسهل من رقمي الجامعي و التجربه كومن\nالقريد النهائي: ِA+\nالصوت: واضح\nإضافات : لا يردك عنه الا التعارض .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508431-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdulkadir-tanimu/172600/6", "user": "F80", "ts": 1554836516000, "tid": 172600, "pn": 6}}]}', 1554836516000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal70-chem101', 'stk-faisal70', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-161\nالتحضير :\nورقة تمر على الطلاب وبعض الايام يحضر بالسريال نمبر في بداية المحاضرة\nبعض الاحيان اذا شاف اغلب الطلاب اسحبوا في المحاضرة بعد التحضير يقوم يحضر من جديد نهاية المحاضرة\nطريقة الشرح :\nشرح عادي من السلايدات يجيب النوم و لاحظة يجي حافظ السلايدات يجي يقراها بدون مايطالعها بالظبط . يحل مسائل الامثلة الي في السلايدات الي هي اصلا محلولة و لا يشرحها بالتفصيل .\nيكون حالها بطريقته في دفتر بس يجي يكتبها من جديد في السبورة مع شرح سريع غير مفهوم.\nيحل مسائل اولد اكزامز في الريسيتاشن يكون حالها بطريقته في دفتر بس يجي يكتبها من جديد في السبورة .\n(تقريبا حال كل مسائل الاولد اكزامز)\nاذا رحت له الاوفيس اور شرحه للمسائل افضل.\nالكويزات :\nمتوسطة من الاولد اكزامز يمكن يغير الارقام بس ز\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي :\nC\nالصوت:\nواضح.\nإضافات :\nالكورس اشوفه اسهل بس الماتيريال كثيرة مرة يعني اذا بتعتمد على السيلف ستدي لازم تبدا من اول يوم و لا تسوف عشان يصير عندك وقت كافي للاولد اكزامز .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467040-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/3", "user": "Faisal70", "ts": 1485431182000, "tid": 175793, "pn": 3}}]}', 1485431182000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ispd-chem101', 'stk-ispd', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101-153\nالتحضير : أغلب الأحيان ورقة تمر تقدر تحضر حتى لو على نهاية الكلاس، لكن بعض الأحيان ينادي الأسماء.\nطريقة الشرح : يشرح من السلايدات ويسرد ويحل مسائل على السبورة، عبيه مايحل اسئلة كثير. (لو ناوي تجيب قريد عدل معاه لازم تحضر قبل)\nالقريد النهائي: C+\nالصوت: لهجة واضحة، بعض الأحيان يتأتئ.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467697-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/4", "user": "iSPD", "ts": 1486318032000, "tid": 175793, "pn": 4}}]}', 1486318032000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bandar_abdullah-chem101', 'stk-bandar_abdullah', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 … term 181\n\nالتحضير :\nورقه تمر على الطلاب, لكن اذا شاف العدد قليل يحضر بنفسه بداية الكلاس.\n\nطريقة الشرح :\n- عن طريق السلايدات وتجيب النوم للامانه 😅\n- الدكتور مو مره كويس بالشرح لكنه يبذل اقصى جهده عشان يوصل المعلومه\n- يتقبل جميع الاسئلة من الطلاب وقت الشرح وبتسمع كثير \" good question 🤪\"\n\nالكويزات :\n- عطانا 10 كويزات كانت من سهله الى متوسطه, قليل يجيب اسئله صعبه\n\nاضافات :\n- الماده ماتعتمد على الدكتور تعتمد عليك بفهم ومراجعة الدروس لذلك انصح عنده ان كنت تبغى تضمن الكلاس وورك وبتشتغل على نفسك بالمياجر 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503929-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/6", "user": "Bandar_Abdullah", "ts": 1545512676000, "tid": 175793, "pn": 6}}]}', 1545512676000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-notlikethis-chem101', 'stk-notlikethis', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني chem 101 دكتور اخلاق وذوق وعسل وقمر مطلوب دوليا من وكالة ناسا, من كثر الاهتمام والذمه اللي عنده ارسلت له ايميل بعد الفجر قلت ابي درجاتي عشان اعرف آخذ NP ولا IC رد علي بعد دقائق بخمسين سطر جاب درجاتي كلها وجمعها وقسمها وقلبها لي وجلس ينصحني وش اختار وكأنه هو اللي بيجيه القريد مو انا\n\nعموما حتى لو شرحة في تأتأه شوي لكنه انسان ترتاح في كلاسة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521972-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/9", "user": "NotLikeThis", "ts": 1589217483000, "tid": 175793, "pn": 9}}]}', 1589217483000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fms1-chem101', 'stk-fms1', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 T201\n\nالتحضير: من بلاك بورد و ما ينادي خلال الحصه.\n\nالكويزات: فيه السهل و الصعب و كانت كتابه ويحسب كل شي السقنفكنت فقر و الوحده. و اخر اختبارين خلاهم ملتبل لكن مع كام.\n\nالشرح: يشرح من سلايدات اشوفهم كويسه لكن شرح متوسط فيه احسن منه و الماده فالنهايه سلف ستدي.\n\nالصوت: الدكتور امريكي و مرات ينكت على الخفيف. مشكلته مرات يوقف يتردد وش يقول او يجلس يفكر. و بداية كل كلاس يعطيك كلمته Saaalmo Alukm\n\nعموما الدكتور اخلاقه طيبه و يوم نزلته خذيته عشان الوقت وكنت خايف منه لكن طلع احسن من المتوقع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527866-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/14", "user": "FMS1", "ts": 1610593128000, "tid": 175793, "pn": 14}}]}', 1610593128000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_as1-chem101', 'stk-_as1', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Dr.THOMAS GARRISON\n\nالمادة ورقم الترم: CHEM101 & T202 (Online)\n\nبنود التقييم /\n\nالتحضير : من أول يوم حاط لك في خانة فـ \" My grade \" لك توتل 100/100 وعلى كل غياب أو تأخير يبدأ يخصم ذي النسبة وطريقة التحضير من \" Blackboard \" بشكل تلقائي يجيه\n\nطريقة الشرح : أشوف شرحه عادي ومملل ويمكن تتنرفز لأن كل دقيقه لازم يبلع ريقه مرتين لكن ما أتوقع أحد ينزل عند دكتور شريّح فـ \" CHEM 101 \" ومعه مقاطع د.عبدالرحمن العرفج فيها كل شي تحتاجه مرتبة وكامله + أول عشر دقايق من المحاضرة لازم يضيع وقت بإنه يحط الـ \" announcement \" اللي هي واجب جديد ولا افرج ومواعيد وطريقة الكوزات او الصور اللي معنا فالميد و … وعلى كذا يسولف ويتبقى وقت قليل لدرجة كنا متأخرين على السلبلس طول الترم ويعتبر شرحه مرره بطيء و يفوت معلومات كثيره\n\nرابط قناة \" Dr. AbdulRahman AlArfaj \" لـ ترم 202 /\nhttps://www.youtube.com/channel/UCFUI8FZ7CKoNNMlUGPfff2w\nقائمة تشغيل مقاطع ترم 201 لـ CHEM 101 لـ د. العرفح /\nhttps://www.youtube.com/playlist?list=PLjJHIhVAfGMp94MghlxM3bbAxzAVcYAi9\n\nالكويزات : تقريبا كل أسبوع شابتر في وقت الريس على النهاية ومرات يسحب ونظامه \" Final Answer \" ولازم تكون منتبه على ثلاث أشياء ( Significant figures ) + ( Unit ) + ( less than 5% Error ) وإذا أستهبلت في واحد منهم راح تنقص … يمكن الطريقة تشوفها صعبه لكن هو قبل أول كوز يعطيك واحد تدريب أنت تعيده زي ماتبي عشان تتعود على إدخال الإجابة … وطبيعة الأسئلة غالبا 5 أسألة كلهم سهلين مرره إلا سؤال متوسط وكل سؤال لك أربع دقايق زي الميد والفاينل وبدون مراقبه فـ على كذا الدكتور خيار جيد عشان ترتبلك \" Classwork \" جيد والواجبات كلها موجودة بالمواقع ماتاخذ 10 دقايق فـ يعتبر دكتور جيد كـ \" Self study \" لكن أنتبه على \" normalization \" لانه بعصة الأرض بالذات إذا كان معك أوريات راح تتصفق\n\nالمياجر : Common\nالفاينلات : Common\n\nالقريد النهائي : B+ , كـ \" Self study \" + بدون أوريات :slightly_frowning_face:\n\nالصوت : أكسنت أمريكي وواضح مره وشوي بلع ريق مع أصوات غريبة وينكت شوي\n\nإضافات : NONE", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530346-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/15", "user": "_As1", "ts": 1622813230000, "tid": 175793, "pn": 15}}]}', 1622813230000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar-12232-chem101', 'stk-omar-12232', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175793", "n": "Dr. Thomas Garrison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T202 Online CHEM101\n\nالتحضير : اوتوماتيكي من البلاك بورد.\n\nطريقة الشرح : يبدا الكلاس بأعلانات مثلا ايش بناخذ اليوم وبكرا ومتى الكويز الجاي الخ… وياخذ من وقت الكلاس فيها بعدين يشرح من السلايدات وشرحه عادي جدا يميل الى الممل.\n\nالكويزات : صعوبة كويزاته تعتمد على الأفرج اذا كان مرتفع يصعب الكويز والعكس ولكن بشكل عام تكون عادية\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B\n\nالصوت: اكنست امريكي واضح\n\nإضافات : اذا تنقرف من بلعة الريق ابعدددددد عن هذا الدكتور لأنه يبلع ريقه كل ثانية ويطلع اصوات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530481-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thomas-garrison/175793/16", "user": "Omar-12232", "ts": 1623468633000, "tid": 175793, "pn": 16}}]}', 1623468633000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-chem101', 'stk-mohammedj', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term 153 chem 101 lab\nالتحضير : بعد الكويز يممر ورقة .\nطريقة الشرح : يشرح لك التجربة كاملة ويكتب لك المعادلات اللي تحتاجها على السبورة .\nالكويزات : يختار بالعادة 3 اسئلة . دائما كان يختار الاسئلة اللي في الصفحة الاولى في البري لاب كويز .\nالمياجر:---\nالفاينلات :---\nالقريد النهائي:ِ A+\nالصوت:واضح بس اكسنت هندي .\nإضافات :الدكتور حبيب ومتعاون جدا وكان يسمح لنا نتعاون مع بعض في التجربة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466529-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/2", "user": "mohammedj", "ts": 1484743680000, "tid": 175794, "pn": 2}}]}', 1484743680000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majeedfatani-chem101', 'stk-majeedfatani', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 -162 Lec & Rec\nالتحضير : يممر ورقة بداية كل كلاس\n\nطريقة الشرح : يشرح على سلايدات شرح مفهوم وشامل ويتقبل الاسئلة في نص الكلاس\n\nالكويزات : تقريبا كل ريستشن كويز ويراعي المياجر فاذا كان اسبوع مياجر م يعطيك كويز ويحذفلك اسوء كويز\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي:A+\n\nالصوت: واضح ومسموع ولكن في اكسنت بس مفهوم\n\nإضافات : الدكتور يعطيك حقك وزيادة ويشجعك في وسط الكلاس احيانا لو تشارك معاه يمسحلك غيابات او يزيدك درجات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473525-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/4", "user": "MajeedFatani", "ts": 1495362231000, "tid": 175794, "pn": 4}}]}', 1495362231000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ma7mud-chem101', 'stk-ma7mud', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 -162\nالتحضير : بداية الكلاس وما يدقق كثير.\n\nطريقة الشرح : يشرح سلايدات الكتاب، المواضيع السهلة يشرحها كويس، لكن المواضيع الصعبة يبدأ يلخبط فيها وبعض الأحيان يضيع وقت على تشابتر واحد قصير ويحشر الباقي في المحاضرة اللي بعدها. السلايدات نسفها بعض الأحيان ما تكفي انها تشرح الفكرة وتكون حاذفة جزء كبير من الكتاب، وتحتاج ترجع للكتاب لكن الدكتور يشرح السلايدات بس.\nالكويزات : تقريبا اسبوعيا ومتعاون\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي:B\n\nالصوت: جيد\nإضافات :\nلازم تعرف المادة طويلة جدا وتحتاج انك اول بأول تدرسها لحالك، حتى لو تسجل عن دكتور ثاني راح تحتاج انك تدرسها لحالك، الدكور ميزته متعاون وحبيب جدا، أوقات المياجر ممكن يلغي الريسيتشن، ممكن يحذف عنك غياب لو تعطيه سبب له. ما رحتله في الاوفيس لكن الشباب يقولوا انه متاعن جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473532-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/5", "user": "Ma7mud", "ts": 1495368954000, "tid": 175794, "pn": 5}}]}', 1495368954000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student-511-chem101', 'stk-student-511', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 term 171\n\nالتحضير: يمرر ورقة\nالشرح: يشرح من سلايدات كما اسلف الاخوة\nويوضح المعلومة على اللي يقدر عليه ، ولو تساله يعطيك جواب، لذلك الافضل انك تكون محضر عشان تستفيد منه اكثر\n\nالكويزات: اختيار من متعدد متوسطة الصعوبة وغالبا يجيب نفس امثلة الكتاب المحلولة + التشيك بوينتس ، مافيها تعقيد كويزاته\n\nالمياجر : كومن\nالفاينل: كومن\n\nقريده: اعطيه A بلس هو متساعد جدا في الدرجات وطيب …واستغله في المحاضرة لا تجيه بدون تحضير للدرس وانا اشوف ان الافضل تكتب وراه لانه يقولك وش تحفظ ووش المعلومات المهمة بالنسبة للي يكتب الاسئلة… المنهج طويل لكن بالمتابعة يكون سهل ان شاء الله … كويزاته والهومورك حقه تغنيك عن الاولد اقزامز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485099-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/13", "user": "Student-511", "ts": 1514356066000, "tid": 175794, "pn": 13}}]}', 1514356066000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-neran-chem101', 'stk-neran', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 term 171\nالتحضير :ورقه يمررها على الطلاب ومتساهل مع المتاخرين\nطريقة الشرح :يشرح من السلايدات واذا ركزت معه راح تفهم اغلب الدرس\nالكويزات :اهم ميزه اشوفها في هالدكتور ان الكويزات تقدر تجيب درجه كامله بسهوله وكما تعرفون الكويزات وزنها مثل ميجر\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:A+\nالصوت: الاكسنت هندي واللي اشوفها من اغث اللهجات في البدايه كنت اواجه صعوبه في فهمه لكن كلها فتره بسيطه وتتعود عليها\nإضافات : اثناء المحاضرات ينبه على الاسئله المهمه واللي ممكن تجي في المياجر والفاينل فاللي يركز على اللي يقوله راح يستفيد كثير\n\nايضا الدكنور اخلاقه عاليه وطيب جدا ومتساهل مع الطلاب الى ابعد درجه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485177-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/14", "user": "neran", "ts": 1514465578000, "tid": 175794, "pn": 14}}]}', 1514465578000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-o.s.s-chem101', 'stk-o.s.s', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 101 - 171\nالتحضير : ورقة تدور عالطلاب ومتساهل\nطريقة الشرح : سلايدات يشرح عليها وجايب الامثلة من الكتاب ما يحتاج ترجعله , وكل ما خلص من نقطة مهمه قعد يشيك على فهمنا ويعيد أكثر من مره لين يتأكد من فهمهم كلهم اشوفه كويس عمومًا , اعتماده كليًا ع السلايدات بدونها يضيع <<< ( خرب البروجيكتر علينا حول 8 مرات قاعه 362 وكل ذيك الدروس أغلب الطلاب مافهموها )\nالكويزات : كل اسبوع كويز ما تطلع عن السلايدات بس يبيلك تذاكرها زين.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح ومفهوم\nإضافات : الدكتور حاب مادته ودايم متحمس وهو يشرح يخليك تركز معه , كل اسبوع فيه واجب من أسئلة الكتاب تسلمها له ورقي\nمن النوع اللي يحفظ أسماء الطلاب فحاول تخليه يعرفك وتشد حيلك مره ف البداية خصوصا ف الكويزات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485686-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/16", "user": "o.s.s", "ts": 1515357262000, "tid": 175794, "pn": 16}}]}', 1515357262000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.x99-chem101', 'stk-mr.x99', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM101 -201 ( عن بعد )\n\nرتويت لكلام الرجال ، المادة سلف ستدي لكن الدكتور قمة في الاخلاق و التعاون و كويزاته متوسط الى سهلة ، انصح فيه و بقووووة ويستاهل A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526704-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/25", "user": "Mr.X99", "ts": 1605515100000, "tid": 175794, "pn": 25}}]}', 1605515100000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-chem101', 'stk-faisal_19', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f176825", "n": "Dr. Ibrahim Yaagoob", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 LAB - 162\n\nالتحضير : بعض الأحيان يحضر عن طريق الكشف أو البريلاب أو الريبورت لكن الأكيد انه يحضر.\nطريقة الشرح : يعطيكم 10 وممكن يمدها إلى 30 دقيقة للبريلاب ، على بال ما نحل البريلاب يكتب خطوات التجربة على السبورة.\nالكويزات : (البريلاب علية 10 درجات والريبورت عليه 65) الكلام هذا في كل تجربة.\nالمياجر: لا يوجد\nالفاينلات : يحدد القسم 5 تجارب ( 4 منها يجي عليها اسئلة نظرية و 1 تجي عملي ).\nالقريد النهائي: A+ ولو فيه اكثر يستاهل الاستاذ ابراهيم.\nالصوت: واضح لكن الاكسنت ممكن ما تفهمه بنسبة 15%\nإضافات :\n1- الاستاذ ابراهيم وما ادراك عن الاستاذ ابراهيم ، شخص عسل ومتساعد إلى ابعد الحدود، اول معمل عنده جتني دوخه وحسيت اني ما اقدر اكمل وانا ما صار لي 15 دقيقة من يوم ما بدينا ، ولا حتى قال شي الاستاذ غير السلام عليكم ، انتبه لي وسألني وش فيني ،علمته فسأل عن اسمي وحضرني وقال بعدها روح العيادة ( تطمن على نفسك ونشوفك الاسبوع الجاي ان شاء الله ) لكن الحمدلله قدرت اكمل ذاك اليوم .\n2- متساعد اثناء التجربة وحتى البريلاب .\n3- تصحيحه جداً ممتاز لكن في النهاية درجاتكم راح تكون قريبة من بعض بسبب هذا الشي.\n4- اذا الجدول يضبط معك الاستاذ ابرهيم فنصيحه لا تفرط فيه، ما راح تندم الا إذا انت ( مهمل ) 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474944-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-yaagoob/176825/2", "user": "Faisal_19", "ts": 1497209489000, "tid": 176825, "pn": 2}}]}', 1497209489000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amo-chem101', 'stk-amo', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f176825", "n": "Dr. Ibrahim Yaagoob", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 Lap -191\nالتحضير :من الكشف خلال البري لاب ويقبل ميك اب\nطريقة الشرح : وقت الشرح مملة شوي ويجاوب الأسئلة بصدر رحب , وقت العملي متساعد جدا وأي خطأ فني يعلمك عليه ولو تجيه 10 مرات وقت اللاب ابدا ما تحس انك ناشب له.\nالكويزات : يجيب أسئلة من نفس المانيوال والإختبار (Open book) والمدة نصف ساعة.\nالمياجر: Lap\nالفاينلات :العملي يكون من القسم فما له يد فيه , الرتن كان جدا لطيف ومعقول.\nالقريد النهائي: S++++++++++++++ ولو فيه زود عداه الدكتور\nالصوت: واضح بس الأكسنت وقت الشرح شوي مو واضح لكن العملي ممتاز جدا.\nإضافات : طبعا الدكتور انهى الدكتوراة في الكيمياء العضوية , مدرسة في الأخلاق والتعامل وكلامي لن يوفيه حقه , ميزة نحسد عليها عنده ان القريدات تجيك اسبوعيا والفاينل من اليوم الثاني , اذا شفت اسمه في لاب سجل وما رح تندم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517643-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-yaagoob/176825/4", "user": "AMO", "ts": 1575553268000, "tid": 176825, "pn": 4}}]}', 1575553268000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_bub-chem101', 'stk-a_bub', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f176827", "n": "Dr. Muhammad Sharif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 T162\n\nالتحضير : ثلاث ورقات تمر بالقاعة لكل سكشن ولو تتأخر نص ساعة ماقال لك شي بس عشوائيا بعض الكلاسات بعد ما الناس حضرت يجي يعيد الاسامي واللي حضر خويه على طول يعطيه دي ان هذي النقطة جدا متشدد فيها\n\nطريقة الشرح : من السلايدات يقراها قراءة والاسئلة اللي بالسلايدات يقول حلوها انتم بالبيت\n\nالكويزات : سهلة جدا.\n\nالمياجر: كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: C+\n\nالصوت:واضح لهجة باكستانية مائلة احيانا للالماني لانه عايش فترة طويلة هناك\n\nإضافات :الدكتور جديد بالجامعة ومو مرة فاهم الطبخة يكون مربوش بالقاعة وقت الشرح ويكره شي اسمه تستخدم جوالك ومستعد يشرشحك قدام الطلاب على ذي السالفة بس عادي تفتح لابتوبك وتسحب عليه 😕\nجدا جدا جدا جدا جدا جدا متعاون مع الطلاب ولكن للاسف يبدو لي انه رامين عليه المادة وهو لا يفقه شيئا فيها واللهم الجامعة جايبته لانه رجال عنده ابحاث وبرائات اختراع كثر الرز وراح يفيد الجامعة من هذي الناحية.\n\nخليه خيارك الاخير اذا جيت تنزل المادة واذا انحديت عليه مبروك عليك فل مارك كلاس وورك والباقي على الله ثم جهدك الشخصي 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474754-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-sharif/176827/2", "user": "A_BuB", "ts": 1496916655000, "tid": 176827, "pn": 2}}]}', 1496916655000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_mah-chem101', 'stk-abdullah_mah', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f176827", "n": "Dr. Muhammad Sharif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101 162\n\nالتحضير : 3 اوراق تُمرر على ثلاث سكاشن تشيك فيها على اسمك\n\nطريقة الشرح : سلايدات يقلب فيها و يصج راسك فيها من اول المحاضرة الى اخرها .\n\nنادرا ما يستخدم السبورة لدرجة ان نستغرب منه اذا مسك الطبشور .\n\nطبعا كان متاخر في الشرح, ف كان يدعس ب السلايدات وهذا الشي شتتنا و نكبنا , وكان اكثر من مرة ياخذ زيادة عن الوقت ف اللكتشر و الريستيشن , احدى المرات اخذ 20 دقيقة زيادة ب الريستيشن وهذا الشي ادى الى استياء الكثير من الطلاب !\n\nالاسئلة اللي ب الكتاب موجودة ب السلايدات ومعا هذا يسوي لها سكب من باب الدعس .\n\nفي اكثر من موقف يكون في سؤال او نقطة ما يعرف لها ف يطلع طالب ويخليه يشرحها و ب العربي ! يعني استاذ ضايع بمعنى الكلمة .\n\nوفوق هذا مايحب يستقبل احد ف الاوفس اور تحسه يقول : ياخي شتبي ؟؟\nاكثر من مرة يصرفني فيها\n\nالكويزات : سهللللللللللة جدا اسهل من اسئلة الكتاب وهذا الشي سلبي طبعا عشان اتنكبنا ب الميجر و انصدمنا صدمة جامدة , ومعا هذا في افرج للكويزات ف ما استفدنا شي من السهولة !\n\nالمياجر : كومن\n\nالفاينلات : كومن\n\nالقريد النهائي : D\n\nالصوت : واضح و معا لهجة مكس امريكي و هندي\n\nاضافات : نجي للجانب الايجابي للدكتور\n\nالدكتور طيب ومتعاون يسمح ب الميك اب ف الريستيشن ويدف ب الهومورك\n\nلكن السيئات تغلب الحسنات . ما انصح اي شخص ابدا ينزل عنده ( سويت دروب )\n\nو عذرا على الإطالة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1476253-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-sharif/176827/4", "user": "Abdullah_MAH", "ts": 1499784479000, "tid": 176827, "pn": 4}}]}', 1499784479000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moahmmed_alali-chem101', 'stk-moahmmed_alali', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f180471", "n": "Dr. Majad Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem101 term 182\n\nالتحضير : متساهل حييل ف التحضير ف بدايه السمستر كان ف بدايه الكلاس يوزع ورقه التحضير وف نص السمستر قال انا اشوف ناس بعد التحضير يمشو وناس يحضرو ربعهم وقال بغير طريقة التحضير وكل اللي سواه أخر توزيع ورقه التحضير وصار يوزعها بعد نص ساعه من بدايه الكلاس\nطريقة الشرح : مب اللي حيل يعرف يشرح بس شرحه حليو بس لازم تنتبه وياه من البدايه اذا فهيت م بتفهم عدل بعدين\nالكويزات : بيقولك ف بدايه الكلاس انه بيعطيك ١٢ كويز على كل شابتر يعني تقريبا كل اسبوع كويز بس وبيحذف منك اسوء كويز بس بعدين اذا مثلا اغلب الطلاب اذا كان عندهم ميجر مادة ثانيه او شي ويبو الكويز يتكنسل يكنسله عادي وهو الدكتور الوحيد اللي يعطيك ١٠ اسئلة ف الكويز ف ينوع ف الافكار وتغطي افكار المياجر ويجيب ٣ ولا ٤ صعبة شوي\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: الصوت واضح وهو باكستاني بس مقضي حياته كلها ف بريطانيا ف الاكسنت حقه بريطاني وواضح\nإضافات : الدكتور طيييب حيييل وحبوب ويحفظ وجيه طلابه بسررعه يعني حتى اللي يدخلو الكلاس وساكتين يحفظهم وف وقت المياجر او الفاينل يكون يم طلابه واذا احتاجو اي شي م يقصر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509306-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/majad-khan/180471/4", "user": "moahmmed_alali", "ts": 1556906480000, "tid": 180471, "pn": 4}}]}', 1556906480000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-chem101', 'stk-yousef_alamoudi_4507', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f182958", "n": "Dr. Wissam Iali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "معليش عالتأخير في التقييم\nCHEM101-192\n# التحضير : زي ما كتبوا الشباب فوق، ورقة بداية الكلاس تمر عالطلاب، مجال ان طالب يوقع لك انساه مع الدكتور وسام، الله يجزاه خير حذف غيابات للشباب اخر الترم.\n# طريقة الشرح : من سلايدات العرفج اتوقع، شرحه كويس بس انصح فيديوهات لمن تراجع عشان تثبيت المعلومة.\nا#الكويزات: وسط بس اوقات يجيب سؤال فيه ترك اليم، يعني من الاخر مقدور عليها ان شاء الله.\n# المياجر و الفاينل : كومن، بس كل اللي اختبرناه كان الميجر الاول بس.\n#القريد النهائي: A\n# الصوت: واضح و ممتاز بس اللكنة جدا عجيبة و كثير ناس يستغربوا منها.\n#اضافات : واحد من اكثر الدكاترة الخلوقين في القسم، يحرجك بأخلاقه ما شاء الله عليه.\nحبيب و متعاون جدا جدا و يستقبل الطلاب في الاوفس بصدر رحب.\nاذا شافنا وسط الكلاس نايمين يرمي شوية نكات.\nانصح فيه كخيار ثاني او ثالث، بعنى لو ما قدرت تلحق عالاساطير زي جانجوا و العرفج نزل مع وسام و انت مغمض.\n\nبالتوفيق ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1523150-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wissam-iali/182958/14", "user": "yousef_Alamoudi_4507", "ts": 1592413172000, "tid": 182958, "pn": 14}}]}', 1592413172000, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-me_student91-chem101', 'stk-me_student91', 'CHEM 101', 'doc', '{"docs": [{"id": "stk-dr-f185293", "n": "Dr. Saheed Ganiyu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 101\nTERM 241\nLEC & REC\n\nبنود التقييم :\n\nالتحضير : آخر الكلاس بالباركود، يعطي 3 غيابات مجانية قبل الخصم.\nطريقة الشرح : يشرح من سلايدات الكتاب ومرة من سلايدات أحد الدكاترة، شرح متواضع جدا وما يكفي للميجر أو حتى للفهم، يحل أولد ميجرز.\nالكويزات : متوسطة إلى سهلة لو تذاكر قبلها بيوم، أفكاره مشابهه للميجر.\nالمياجر: كومن.\nالفاينلات :كومن.\nالقريد النهائي: b\nالصوت: واضح\nإضافات : أخلاقه عالية وسمح في التعامل ويجاوب على الأسئلة بكل صدر رحب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539427-chem101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saheed-ganiyu/185293/2", "user": "ME_STUDENT91", "ts": 1745057845349, "tid": 185293, "pn": 2}}]}', 1745057845349, 1794764436, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
